const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\n9901803\n00:00:00.000 --> 00:00:02.080 align:middle line:10%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:00:38.830 --> 00:00:41.750 align:middle line:100%,end position:50%,middle\n<i>我有个朋友叫黛博拉\n是位心理学家</i>\n\n2\n00:00:41.917 --> 00:00:44.086 align:middle line:100%,end position:50%,middle\n<i>费城市政府曾委托她</i>\n\n3\n00:00:44.253 --> 00:00:48.340 align:middle line:100%,end position:50%,middle\n<i>为柬埔寨难民提供心理辅导</i>\n\n4\n00:00:48.507 --> 00:00:52.052 align:middle line:100%,end position:50%,middle\n<i>他们是刚逃到当地的船民</i>\n\n5\n00:00:52.219 --> 00:00:55.347 align:middle line:100%,end position:50%,middle\n<i>黛博拉很忐忑\n这些柬埔寨人</i>\n\n6\n00:00:55.514 --> 00:01:00.519 align:middle line:100%,end position:50%,middle\n<i>经历过种族屠杀和饥荒\n亲眼看着亲人被杀</i>\n\n7\n00:01:00.686 --> 00:01:04.438 align:middle line:100%,end position:50%,middle\n<i>在难民营熬了多年\n又冒死坐船逃到西方</i>\n\n8\n00:01:04.897 --> 00:01:06.775 align:middle line:100%,end position:50%,middle\n<i>她如何体会他们的苦难？</i>\n\n9\n00:01:06.942 --> 00:01:08.610 align:middle line:100%,end position:50%,middle\n<i>又该怎么帮助他们？</i>\n\n10\n00:01:14.992 --> 00:01:17.494 align:middle line:100%,end position:50%,middle\n<i>猜猜这些人想跟她聊什么</i>\n\n11\n00:01:17.661 --> 00:01:20.414 align:middle line:100%,end position:50%,middle\n<i>跟我那位心理学家朋友黛博拉</i>\n\n12\n00:01:22.499 --> 00:01:25.335 align:middle line:100%,end position:50%,middle\n<i>全都是“我在难民营认识个男人</i>\n\n13\n00:01:25.502 --> 00:01:28.338 align:middle line:100%,end position:50%,middle\n<i>以为他真心爱我\n可我们失散以后</i>\n\n14\n00:01:28.505 --> 00:01:31.091 align:middle line:100%,end position:50%,middle\n<i>他就跟我表亲好了\n现在又说爱我</i>\n\n15\n00:01:31.258 --> 00:01:34.720 align:middle line:100%,end position:50%,middle\n<i>一直打电话 可他们已经结婚了\n我该怎么办？”</i>\n\n16\n00:01:34.887 --> 00:01:35.971 align:middle line:100%,end position:50%,middle\n<i>人就是这样</i>\n\n17\n00:01:36.138 --> 00:01:37.347 align:middle line:100%,end position:50%,middle\n有什么事吗？\n\n18\n00:01:37.514 --> 00:01:40.184 align:middle line:100%,end position:50%,middle\n我是莉兹·吉尔伯特\n在写一篇关于巴厘岛的杂志文章\n\n19\n00:01:40.350 --> 00:01:41.810 align:middle line:100%,end position:50%,middle\n想拜访一位传统医师\n\n20\n00:01:41.977 --> 00:01:45.063 align:middle line:100%,end position:50%,middle\n大家都叫我找凯图·利耶\n是这里吗？\n\n21\n00:01:45.230 --> 00:01:46.315 align:middle line:100%,end position:50%,middle\n等一下\n\n22\n00:01:46.481 --> 00:01:50.819 align:middle line:100%,end position:50%,middle\n<i>你看 我来见一位传承了9代的医师</i>\n\n23\n00:01:50.986 --> 00:01:53.488 align:middle line:100%,end position:50%,middle\n<i>想问他的是什么呢？</i>\n\n24\n00:01:53.655 --> 00:01:55.991 align:middle line:100%,end position:50%,middle\n<i>如何更接近上帝？</i>\n\n25\n00:01:56.158 --> 00:01:59.703 align:middle line:100%,end position:50%,middle\n<i>如何拯救世上挨饿的孩子？</i>\n\n26\n00:02:00.454 --> 00:02:02.998 align:middle line:100%,end position:50%,middle\n很高兴见到你 我是凯图·利耶\n\n27\n00:02:03.165 --> 00:02:08.086 align:middle line:100%,end position:50%,middle\n<i>都不是 我想聊感情问题</i>\n\n28\n00:02:11.381 --> 00:02:13.926 align:middle line:100%,end position:50%,middle\n你是个周游世界的人\n\n29\n00:02:14.092 --> 00:02:16.178 align:middle line:100%,end position:50%,middle\n你会很长寿\n\n30\n00:02:16.345 --> 00:02:19.681 align:middle line:100%,end position:50%,middle\n交很多朋友 经历很多事\n\n31\n00:02:21.266 --> 00:02:24.937 align:middle line:100%,end position:50%,middle\n你会结<i>2</i>次婚 <i>1</i>次长 <i>1</i>次短\n\n32\n00:02:25.270 --> 00:02:27.064 align:middle line:100%,end position:50%,middle\n我现在这次是长的还是短的？\n\n33\n00:02:27.606 --> 00:02:29.149 align:middle line:100%,end position:50%,middle\n看不出来\n\n34\n00:02:29.316 --> 00:02:33.278 align:middle line:100%,end position:50%,middle\n你还会失去所有的钱\n\n35\n00:02:34.363 --> 00:02:37.616 align:middle line:100%,end position:50%,middle\n大概就在未来<i>6</i>到<i>10</i>个月里\n\n36\n00:02:38.909 --> 00:02:41.995 align:middle line:100%,end position:50%,middle\n别担心 你会再赚回来的\n\n37\n00:02:42.704 --> 00:02:45.082 align:middle line:100%,end position:50%,middle\n你还会回到巴厘岛\n\n38\n00:02:45.249 --> 00:02:51.547 align:middle line:100%,end position:50%,middle\n在这里住上三四个月 教我英语\n\n39\n00:02:51.713 --> 00:02:55.175 align:middle line:100%,end position:50%,middle\n一直没人陪我练英语\n\n40\n00:02:55.926 --> 00:02:57.511 align:middle line:100%,end position:50%,middle\n到时候\n\n41\n00:02:57.678 --> 00:03:03.058 align:middle line:100%,end position:50%,middle\n我会把我知道的全教给你\n\n42\n00:03:05.894 --> 00:03:07.729 align:middle line:100%,end position:50%,middle\n等一下\n\n43\n00:03:11.942 --> 00:03:13.861 align:middle line:100%,end position:50%,middle\n这个送给你\n\n44\n00:03:14.027 --> 00:03:17.489 align:middle line:100%,end position:50%,middle\n要脚踏实地 像长了<i>4</i>条腿\n\n45\n00:03:17.906 --> 00:03:20.158 align:middle line:100%,end position:50%,middle\n这样才能立足于这个世界\n\n46\n00:03:20.742 --> 00:03:24.705 align:middle line:100%,end position:50%,middle\n也别用脑子看世界\n\n47\n00:03:24.872 --> 00:03:27.291 align:middle line:100%,end position:50%,middle\n要用心去看\n\n48\n00:03:27.457 --> 00:03:29.585 align:middle line:100%,end position:50%,middle\n这样你就能认识上帝\n\n49\n00:03:31.044 --> 00:03:33.255 align:middle line:100%,end position:50%,middle\n这不就是你来的原因吗？\n\n50\n00:03:34.423 --> 00:03:37.843 align:middle line:100%,end position:50%,middle\n回头见 小鳄鱼\n\n51\n00:03:52.232 --> 00:03:55.611 align:middle line:100%,end position:50%,middle\n她的书稿都由我校对\n\n52\n00:03:55.777 --> 00:03:59.281 align:middle line:100%,end position:50%,middle\n我太太美极了\n可拼写实在一塌糊涂\n\n53\n00:03:59.448 --> 00:04:02.117 align:middle line:100%,end position:50%,middle\n看看史蒂芬叔叔\n\n54\n00:04:03.619 --> 00:04:04.786 align:middle line:100%,end position:50%,middle\n还有莉兹阿姨\n\n55\n00:04:04.953 --> 00:04:08.665 align:middle line:100%,end position:50%,middle\n真想快点结束\n好换上我的大号裤\n\n56\n00:04:08.832 --> 00:04:10.792 align:middle line:100%,end position:50%,middle\n你刚生完孩子 已经很漂亮了\n\n57\n00:04:10.959 --> 00:04:12.961 align:middle line:100%,end position:50%,middle\n你骗人 我又胖又累\n\n58\n00:04:13.128 --> 00:04:15.672 align:middle line:100%,end position:50%,middle\n脑子也不转了\n简直像莉莎·明奈利\n\n59\n00:04:15.839 --> 00:04:17.507 align:middle line:100%,end position:50%,middle\n史蒂芬 帮我抱一下杰克好吗？\n\n60\n00:04:17.673 --> 00:04:20.010 align:middle line:100%,end position:50%,middle\n- 我带你认识沃尔特\n- 好\n\n61\n00:04:20.802 --> 00:04:24.223 align:middle line:100%,end position:50%,middle\n哥们儿 要不要喝杯啤酒？\n\n62\n00:04:24.473 --> 00:04:27.100 align:middle line:100%,end position:50%,middle\n我的新书<i>4</i>月出版 谢谢关心\n\n63\n00:04:27.267 --> 00:04:28.310 align:middle line:100%,end position:50%,middle\n- 太好了\n- <i>5</i>月\n\n64\n00:04:28.477 --> 00:04:29.811 align:middle line:100%,end position:50%,middle\n<i>5</i>月 对 <i>5</i>月\n\n65\n00:04:30.479 --> 00:04:33.273 align:middle line:100%,end position:50%,middle\n这是安德烈\n你俩都入围<i>《时报》</i>年度好书\n\n66\n00:04:33.440 --> 00:04:36.151 align:middle line:100%,end position:50%,middle\n- 终于见到你了\n- 我也很高兴\n\n67\n00:04:38.153 --> 00:04:39.863 align:middle line:100%,end position:50%,middle\n我喂他吃了玉米片 不行吗？\n\n68\n00:04:40.030 --> 00:04:42.533 align:middle line:100%,end position:50%,middle\n你抱得真顺手\n喂了他什么 迷药吗？\n\n69\n00:04:42.699 --> 00:04:44.660 align:middle line:100%,end position:50%,middle\n- 给他爸爸抱吧\n- 都说了是玉米片\n\n70\n00:04:44.826 --> 00:04:47.371 align:middle line:100%,end position:50%,middle\n拉了这么一大泡 我也能睡着\n\n71\n00:04:47.538 --> 00:04:50.541 align:middle line:100%,end position:50%,middle\n- 还是交给妈妈吧\n- 来吧\n\n72\n00:04:52.167 --> 00:04:54.294 align:middle line:100%,end position:50%,middle\n- 要帮我换尿布吗？\n- 好啊\n\n73\n00:04:54.461 --> 00:04:56.338 align:middle line:100%,end position:50%,middle\n你的老爷车生意怎么样？\n\n74\n00:04:56.505 --> 00:04:59.299 align:middle line:100%,end position:50%,middle\n不做了 我换工作了\n现在是甜点师\n\n75\n00:04:59.466 --> 00:05:01.593 align:middle line:100%,end position:50%,middle\n- 就是烘焙师吧\n- 对\n\n76\n00:05:01.760 --> 00:05:03.512 align:middle line:100%,end position:50%,middle\n想抽两口 嗨一下吗？\n\n77\n00:05:05.013 --> 00:05:07.641 align:middle line:100%,end position:50%,middle\n我知道 我知道\n\n78\n00:05:07.808 --> 00:05:09.852 align:middle line:100%,end position:50%,middle\n很辛苦吧？\n\n79\n00:05:10.352 --> 00:05:14.147 align:middle line:100%,end position:50%,middle\n不会啊 可有意思了\n\n80\n00:05:14.690 --> 00:05:17.317 align:middle line:100%,end position:50%,middle\n你知道自己是哪一刻想生孩子的吗？\n\n81\n00:05:17.484 --> 00:05:21.989 align:middle line:100%,end position:50%,middle\n记不清了\n不过婚前我就准备了那个盒子\n\n82\n00:05:22.155 --> 00:05:23.699 align:middle line:100%,end position:50%,middle\n什么盒子？\n\n83\n00:05:23.866 --> 00:05:26.994 align:middle line:100%,end position:50%,middle\n很少女 很丢脸的\n说了你会笑我的\n\n84\n00:05:27.452 --> 00:05:30.455 align:middle line:100%,end position:50%,middle\n我会笑你 但你还是得说\n\n85\n00:05:31.039 --> 00:05:32.791 align:middle line:100%,end position:50%,middle\n说嘛\n\n86\n00:05:33.458 --> 00:05:34.960 align:middle line:100%,end position:50%,middle\n在床底下\n\n87\n00:05:41.341 --> 00:05:44.052 align:middle line:100%,end position:50%,middle\n我一直往里面放婴儿用品\n\n88\n00:05:44.219 --> 00:05:47.055 align:middle line:100%,end position:50%,middle\n等安迪做好当爸爸的准备\n\n89\n00:05:49.141 --> 00:05:52.019 align:middle line:100%,end position:50%,middle\n真可爱\n\n90\n00:05:52.186 --> 00:05:53.854 align:middle line:100%,end position:50%,middle\n这件有我能穿的尺码吗？\n\n91\n00:05:59.902 --> 00:06:03.405 align:middle line:100%,end position:50%,middle\n我也有这样的盒子\n不过里面是<i>《国家地理》</i>\n\n92\n00:06:03.572 --> 00:06:05.741 align:middle line:100%,end position:50%,middle\n还有<i>《时报》</i>的旅游版\n\n93\n00:06:05.908 --> 00:06:09.036 align:middle line:100%,end position:50%,middle\n都是我有生之年想去的地方\n\n94\n00:06:09.203 --> 00:06:13.665 align:middle line:100%,end position:50%,middle\n莉兹 生孩子就像在脸上文身\n\n95\n00:06:15.083 --> 00:06:17.252 align:middle line:100%,end position:50%,middle\n得彻底想好才行\n\n96\n00:06:21.215 --> 00:06:24.593 align:middle line:100%,end position:50%,middle\n我下周去阿鲁巴岛\n就是写一篇普通的\n\n97\n00:06:24.760 --> 00:06:27.387 align:middle line:100%,end position:50%,middle\n吃喝玩乐住宿攻略\n\n98\n00:06:27.554 --> 00:06:29.014 align:middle line:100%,end position:50%,middle\n我买了件新比基尼\n\n99\n00:06:29.181 --> 00:06:32.684 align:middle line:100%,end position:50%,middle\n还发现客房迷你吧可以随便用\n\n100\n00:06:32.851 --> 00:06:34.686 align:middle line:100%,end position:50%,middle\n- 知道这意味着什么吗？\n- 倒时差？\n\n101\n00:06:34.853 --> 00:06:37.564 align:middle line:100%,end position:50%,middle\n你 我\n\n102\n00:06:37.731 --> 00:06:39.107 align:middle line:100%,end position:50%,middle\n还有夏威夷果\n\n103\n00:06:40.651 --> 00:06:41.735 align:middle line:100%,end position:50%,middle\n真可爱\n\n104\n00:06:41.902 --> 00:06:45.113 align:middle line:100%,end position:50%,middle\n那天聚会上有个人\n说话特别启发我\n\n105\n00:06:45.280 --> 00:06:46.657 align:middle line:100%,end position:50%,middle\n- 就是塔拉的朋友\n- 布赖恩\n\n106\n00:06:46.823 --> 00:06:49.993 align:middle line:100%,end position:50%,middle\n布赖恩 真了不起\n你知道他是老师吗？\n\n107\n00:06:50.160 --> 00:06:51.912 align:middle line:100%,end position:50%,middle\n是代课老师吧？\n\n108\n00:06:52.079 --> 00:06:55.123 align:middle line:100%,end position:50%,middle\n对 他聊到了眼下的预算削减\n\n109\n00:06:55.290 --> 00:06:57.042 align:middle line:100%,end position:50%,middle\n什么都没经费\n\n110\n00:06:57.209 --> 00:06:59.878 align:middle line:100%,end position:50%,middle\n音乐课 美术课都没了\n\n111\n00:07:00.045 --> 00:07:03.006 align:middle line:100%,end position:50%,middle\n他们课后自愿抽时间来教\n\n112\n00:07:03.173 --> 00:07:05.217 align:middle line:100%,end position:50%,middle\n他们在教育我们的孩子\n\n113\n00:07:05.384 --> 00:07:08.262 align:middle line:100%,end position:50%,middle\n亲爱的 我觉得你能当个好老师\n\n114\n00:07:08.428 --> 00:07:11.640 align:middle line:100%,end position:50%,middle\n谢谢 不过我想的是\n\n115\n00:07:12.224 --> 00:07:15.561 align:middle line:100%,end position:50%,middle\n再去读书 拿个硕士学位\n我也说不好\n\n116\n00:07:15.727 --> 00:07:17.396 align:middle line:100%,end position:50%,middle\n你懂吧？\n\n117\n00:07:24.152 --> 00:07:26.280 align:middle line:100%,end position:50%,middle\n我... 就是...\n\n118\n00:07:26.905 --> 00:07:29.491 align:middle line:100%,end position:50%,middle\n- 再去上学？\n- 我只是想到就说了\n\n119\n00:07:32.035 --> 00:07:37.082 align:middle line:100%,end position:50%,middle\n<i>我越来越不安\n凯图的预言似乎正在应验</i>\n\n120\n00:07:37.249 --> 00:07:39.918 align:middle line:100%,end position:50%,middle\n<i>我现在这段婚姻是短的那段吗？</i>\n\n121\n00:07:41.670 --> 00:07:44.673 align:middle line:100%,end position:50%,middle\n<i>这房子才买了1年</i>\n\n122\n00:07:45.340 --> 00:07:46.758 align:middle line:100%,end position:50%,middle\n<i>这不就是我想要的吗？</i>\n\n123\n00:07:49.219 --> 00:07:53.515 align:middle line:100%,end position:50%,middle\n<i>这样的生活</i>\n\n124\n00:07:53.682 --> 00:07:55.517 align:middle line:100%,end position:50%,middle\n<i>每一步我都主动参与了</i>\n\n125\n00:07:55.684 --> 00:07:59.021 align:middle line:100%,end position:50%,middle\n<i>为什么却处处找不到自己？</i>\n\n126\n00:08:04.443 --> 00:08:08.363 align:middle line:100%,end position:50%,middle\n<i>比留下更难的</i>\n\n127\n00:08:08.530 --> 00:08:10.407 align:middle line:100%,end position:50%,middle\n<i>只有离开</i>\n\n128\n00:08:12.034 --> 00:08:16.205 align:middle line:100%,end position:50%,middle\n<i>我不想伤害任何人\n只想悄悄从后门溜走</i>\n\n129\n00:08:16.371 --> 00:08:19.875 align:middle line:100%,end position:50%,middle\n<i>一直逃到格陵兰才停下来</i>\n\n130\n00:08:24.338 --> 00:08:26.882 align:middle line:100%,end position:50%,middle\n<i>可我决定做另一件事</i>\n\n131\n00:08:27.508 --> 00:08:29.218 align:middle line:100%,end position:50%,middle\n<i>祈祷</i>\n\n132\n00:08:29.468 --> 00:08:32.888 align:middle line:100%,end position:50%,middle\n<i>就是向上帝祈祷</i>\n\n133\n00:08:33.597 --> 00:08:38.143 align:middle line:100%,end position:50%,middle\n<i>这对我太陌生了\n我差点就开口说</i>\n\n134\n00:08:38.309 --> 00:08:40.312 align:middle line:100%,end position:50%,middle\n<i>“我很喜欢您的作品”</i>\n\n135\n00:08:47.528 --> 00:08:49.613 align:middle line:100%,end position:50%,middle\n喂 上帝？\n\n136\n00:08:52.491 --> 00:08:55.577 align:middle line:100%,end position:50%,middle\n终于认识您了 我...\n\n137\n00:08:56.495 --> 00:09:02.751 align:middle line:100%,end position:50%,middle\n抱歉 以前从没直接跟您说过话\n\n138\n00:09:02.918 --> 00:09:04.586 align:middle line:100%,end position:50%,middle\n不过...\n\n139\n00:09:05.420 --> 00:09:08.257 align:middle line:100%,end position:50%,middle\n我希望我已经\n\n140\n00:09:08.924 --> 00:09:12.970 align:middle line:100%,end position:50%,middle\n对您赐予我的所有恩惠\n\n141\n00:09:13.136 --> 00:09:15.430 align:middle line:100%,end position:50%,middle\n表达过充分的感激\n\n142\n00:09:25.274 --> 00:09:27.776 align:middle line:100%,end position:50%,middle\n我遇上大麻烦了\n\n143\n00:09:29.778 --> 00:09:32.114 align:middle line:100%,end position:50%,middle\n不知道该怎么办\n\n144\n00:09:33.448 --> 00:09:35.951 align:middle line:100%,end position:50%,middle\n我需要一个答案\n\n145\n00:09:36.451 --> 00:09:40.664 align:middle line:100%,end position:50%,middle\n求您告诉我该怎么做\n\n146\n00:09:42.207 --> 00:09:45.127 align:middle line:100%,end position:50%,middle\n上帝啊 求您帮帮我\n\n147\n00:09:51.300 --> 00:09:54.261 align:middle line:100%,end position:50%,middle\n告诉我该怎么做 我一定照办\n\n148\n00:09:57.097 --> 00:09:59.808 align:middle line:100%,end position:50%,middle\n回床上去吧 莉兹\n\n149\n00:10:21.205 --> 00:10:23.165 align:middle line:100%,end position:50%,middle\n我不想去阿鲁巴了\n\n150\n00:10:26.793 --> 00:10:29.421 align:middle line:100%,end position:50%,middle\n我不想再过婚姻生活了\n\n151\n00:10:46.730 --> 00:10:49.525 align:middle line:100%,end position:50%,middle\n楼下有一整区讲离婚的书\n\n152\n00:11:08.293 --> 00:11:09.878 align:middle line:100%,end position:50%,middle\n- “胡椒研磨器”\n- 她这是\n\n153\n00:11:10.045 --> 00:11:12.256 align:middle line:100%,end position:50%,middle\n- 精神崩溃了\n- 女孩子就这样\n\n154\n00:11:12.422 --> 00:11:14.925 align:middle line:100%,end position:50%,middle\n- 她在慢慢消化\n- 怎么不去喝酒找人上床？\n\n155\n00:11:15.092 --> 00:11:17.094 align:middle line:100%,end position:50%,middle\n你离开我的话 我就会这么干\n\n156\n00:11:17.261 --> 00:11:18.637 align:middle line:100%,end position:50%,middle\n你才不会\n\n157\n00:11:18.804 --> 00:11:21.515 align:middle line:100%,end position:50%,middle\n- 对 我不会\n- 她搬出去 申请离婚了\n\n158\n00:11:21.682 --> 00:11:24.977 align:middle line:100%,end position:50%,middle\n他们在一起<i>8</i>年了\n她现在连家都没了\n\n159\n00:11:32.067 --> 00:11:33.986 align:middle line:100%,end position:50%,middle\n“传承”\n\n160\n00:11:36.572 --> 00:11:41.410 align:middle line:100%,end position:50%,middle\n意大利语每个词都像颗松露\n像个魔术\n\n161\n00:11:41.910 --> 00:11:44.955 align:middle line:100%,end position:50%,middle\n亲爱的 我懂\n这是你现在的救生筏\n\n162\n00:11:45.122 --> 00:11:48.375 align:middle line:100%,end position:50%,middle\n我跟安迪分手那<i>2</i>周\n还买了台织布机呢\n\n163\n00:11:48.542 --> 00:11:51.378 align:middle line:100%,end position:50%,middle\n一台该死的织布机\n他则想开家小啤酒厂\n\n164\n00:11:51.545 --> 00:11:54.506 align:middle line:100%,end position:50%,middle\n你们怎么还没烦我\n我自己都烦了\n\n165\n00:11:54.673 --> 00:11:56.925 align:middle line:100%,end position:50%,middle\n开什么玩笑 我们喜欢你住这儿\n\n166\n00:11:57.092 --> 00:11:59.219 align:middle line:100%,end position:50%,middle\n像请了位驻家作家\n\n167\n00:11:59.386 --> 00:12:01.889 align:middle line:100%,end position:50%,middle\n不过你是作家 也该写点东西\n\n168\n00:12:02.055 --> 00:12:06.226 align:middle line:100%,end position:50%,middle\n不如写个女人去意大利学意大利语\n\n169\n00:12:06.393 --> 00:12:09.855 align:middle line:100%,end position:50%,middle\n就叫<i>《碳水化合物与动词变位》</i>\n\n170\n00:12:10.022 --> 00:12:12.566 align:middle line:100%,end position:50%,middle\n我会开始找住处的\n\n171\n00:12:14.318 --> 00:12:17.029 align:middle line:100%,end position:50%,middle\n- 我爱上你了\n- 我不是你想的那个人\n\n172\n00:12:17.196 --> 00:12:18.697 align:middle line:100%,end position:50%,middle\n我只是你的幻想\n\n173\n00:12:18.864 --> 00:12:23.076 align:middle line:100%,end position:50%,middle\n不 胡扯 你是真实的\n\n174\n00:12:23.952 --> 00:12:26.246 align:middle line:100%,end position:50%,middle\n你的伤痕 你的才华\n\n175\n00:12:26.413 --> 00:12:28.498 align:middle line:100%,end position:50%,middle\n我只有一家破酒吧\n\n176\n00:12:28.665 --> 00:12:30.918 align:middle line:100%,end position:50%,middle\n你却接受我这辈子就这样了\n\n177\n00:12:31.084 --> 00:12:32.461 align:middle line:100%,end position:50%,middle\n好吧 这戏真烂\n\n178\n00:12:32.628 --> 00:12:35.130 align:middle line:100%,end position:50%,middle\n- 我同意\n- 别没礼貌\n\n179\n00:12:42.221 --> 00:12:44.348 align:middle line:100%,end position:50%,middle\n我爱你的痛苦\n\n180\n00:12:45.098 --> 00:12:49.061 align:middle line:100%,end position:50%,middle\n也爱我们在一起时\n我能让它消失\n\n181\n00:12:50.145 --> 00:12:51.647 align:middle line:100%,end position:50%,middle\n- 他真不错\n- 你的爱\n\n182\n00:12:51.813 --> 00:12:55.484 align:middle line:100%,end position:50%,middle\n- 他是帅 这可不一样\n- 就像热腾腾的帕尼尼\n\n183\n00:12:55.651 --> 00:13:00.781 align:middle line:100%,end position:50%,middle\n望着你的眼睛\n我仿佛听见海豚在鼓掌\n\n184\n00:13:00.948 --> 00:13:03.450 align:middle line:100%,end position:50%,middle\n这句可不是我写的\n\n185\n00:13:03.617 --> 00:13:05.118 align:middle line:100%,end position:50%,middle\n有件事他还不知道\n\n186\n00:13:06.370 --> 00:13:10.082 align:middle line:100%,end position:50%,middle\n我会迷失在自己爱的人身上\n\n187\n00:13:10.249 --> 00:13:15.170 align:middle line:100%,end position:50%,middle\n我像一层可渗透的膜\n爱上你就把一切都给你\n\n188\n00:13:15.337 --> 00:13:18.173 align:middle line:100%,end position:50%,middle\n我的钱 时间 身体\n\n189\n00:13:18.340 --> 00:13:21.844 align:middle line:100%,end position:50%,middle\n我的狗 还有我家狗的钱\n\n190\n00:13:22.010 --> 00:13:25.180 align:middle line:100%,end position:50%,middle\n我会替你还债 还以为你有\n\n191\n00:13:25.347 --> 00:13:30.519 align:middle line:100%,end position:50%,middle\n那些你其实从未具备的美好品质\n\n192\n00:13:30.686 --> 00:13:33.272 align:middle line:100%,end position:50%,middle\n这些 乃至更多 我都会给你\n\n193\n00:13:33.438 --> 00:13:36.275 align:middle line:100%,end position:50%,middle\n直到精疲力竭 被彻底掏空\n\n194\n00:13:36.441 --> 00:13:39.278 align:middle line:100%,end position:50%,middle\n唯一能让我恢复的办法\n\n195\n00:13:39.444 --> 00:13:41.989 align:middle line:100%,end position:50%,middle\n就是再迷恋上另一个人\n\n196\n00:13:49.204 --> 00:13:51.415 align:middle line:100%,end position:50%,middle\n- 伊丽莎白 你好\n<i>- 你好</i>\n\n197\n00:13:51.582 --> 00:13:53.208 align:middle line:100%,end position:50%,middle\n真的吗？\n\n198\n00:13:56.128 --> 00:13:58.213 align:middle line:100%,end position:50%,middle\n你好吗？\n\n199\n00:14:29.494 --> 00:14:31.246 align:middle line:100%,end position:50%,middle\n干杯\n\n200\n00:14:32.915 --> 00:14:35.375 align:middle line:100%,end position:50%,middle\n- 谢谢\n- 我得向你道歉\n\n201\n00:14:35.542 --> 00:14:39.421 align:middle line:100%,end position:50%,middle\n- 有人中途离场了\n- 总不能让所有人喜欢\n\n202\n00:14:40.172 --> 00:14:42.132 align:middle line:100%,end position:50%,middle\n我看未必\n\n203\n00:14:42.883 --> 00:14:44.885 align:middle line:100%,end position:50%,middle\n倒是我 演得跟屎一样\n\n204\n00:14:45.677 --> 00:14:50.432 align:middle line:100%,end position:50%,middle\n- 尽管我很努力了\n- 也不用说“屎”吧\n\n205\n00:14:51.099 --> 00:14:52.309 align:middle line:100%,end position:50%,middle\n谢谢\n\n206\n00:14:52.476 --> 00:14:55.437 align:middle line:100%,end position:50%,middle\n你本人看起来比台上矮\n\n207\n00:14:55.604 --> 00:14:57.523 align:middle line:100%,end position:50%,middle\n- 是吗？好多人都这么说\n- 抱歉\n\n208\n00:14:57.689 --> 00:14:59.233 align:middle line:100%,end position:50%,middle\n没关系\n\n209\n00:15:00.025 --> 00:15:02.152 align:middle line:100%,end position:50%,middle\n有时候挺让人不安的\n\n210\n00:15:02.319 --> 00:15:06.281 align:middle line:100%,end position:50%,middle\n一个陌生人看你\n竟比你自己还清楚\n\n211\n00:15:06.448 --> 00:15:08.700 align:middle line:100%,end position:50%,middle\n我说你矮就是这个意思\n\n212\n00:15:13.121 --> 00:15:16.375 align:middle line:100%,end position:50%,middle\n你现在听见海豚鼓掌了吗？\n\n213\n00:15:17.709 --> 00:15:21.129 align:middle line:100%,end position:50%,middle\n我擅自改了你几句台词\n\n214\n00:15:21.296 --> 00:15:24.591 align:middle line:100%,end position:50%,middle\n你尽管笑话我吧\n我知道你早就想了\n\n215\n00:15:26.301 --> 00:15:29.179 align:middle line:100%,end position:50%,middle\n你太迷人了 我可笑不出来\n\n216\n00:15:33.559 --> 00:15:35.811 align:middle line:100%,end position:50%,middle\n我还听得见它们\n\n217\n00:15:44.778 --> 00:15:47.114 align:middle line:100%,end position:50%,middle\n那是你的导师？\n\n218\n00:15:48.198 --> 00:15:51.076 align:middle line:100%,end position:50%,middle\n你在开玩笑 不过没错\n\n219\n00:15:52.369 --> 00:15:54.288 align:middle line:100%,end position:50%,middle\n她很美\n\n220\n00:15:54.454 --> 00:15:57.124 align:middle line:100%,end position:50%,middle\n是啊 是个朋友介绍的\n\n221\n00:15:58.000 --> 00:16:00.919 align:middle line:100%,end position:50%,middle\n我那时失业了\n迫切想抓住点什么\n\n222\n00:16:01.086 --> 00:16:03.922 align:middle line:100%,end position:50%,middle\n不是最近这次 是上次失业\n\n223\n00:16:04.089 --> 00:16:09.344 align:middle line:100%,end position:50%,middle\n我总觉得自己一直找错了地方\n\n224\n00:16:09.511 --> 00:16:10.762 align:middle line:100%,end position:50%,middle\n在找什么？\n\n225\n00:16:11.096 --> 00:16:12.139 align:middle line:100%,end position:50%,middle\n上帝\n\n226\n00:16:13.724 --> 00:16:17.060 align:middle line:100%,end position:50%,middle\n她在印度有座修行院\n我很想去 可是\n\n227\n00:16:17.227 --> 00:16:20.564 align:middle line:100%,end position:50%,middle\n去之前肝炎疫苗得打<i>3</i>针\n\n228\n00:16:20.731 --> 00:16:23.609 align:middle line:100%,end position:50%,middle\n我的保险却总是到期\n\n229\n00:16:23.817 --> 00:16:25.736 align:middle line:100%,end position:50%,middle\n时机到了我就去\n\n230\n00:16:25.903 --> 00:16:29.072 align:middle line:100%,end position:50%,middle\n她的学生每天早上都会聚会\n\n231\n00:16:30.199 --> 00:16:33.202 align:middle line:100%,end position:50%,middle\n你愿意的话 我可以带你去\n\n232\n00:16:33.368 --> 00:16:38.707 align:middle line:100%,end position:50%,middle\n<i>100</i>个崇尚自然生活的人\n用梵语唱诵 你不怕就行\n\n233\n00:16:39.541 --> 00:16:41.793 align:middle line:100%,end position:50%,middle\n我正需要点冲击\n\n234\n00:17:12.699 --> 00:17:16.369 align:middle line:100%,end position:50%,middle\n<i>大卫 来自扬克斯的瑜伽修行者</i>\n\n235\n00:17:17.913 --> 00:17:21.290 align:middle line:100%,end position:50%,middle\n<i>我倒不完全是爱上了他</i>\n\n236\n00:17:22.709 --> 00:17:25.378 align:middle line:100%,end position:50%,middle\n<i>而是从婚姻里跳了出来</i>\n\n237\n00:17:25.546 --> 00:17:27.172 align:middle line:100%,end position:50%,middle\n<i>一头扎进大卫怀里</i>\n\n238\n00:17:27.339 --> 00:17:30.592 align:middle line:100%,end position:50%,middle\n<i>就像卡通里的马戏演员</i>\n\n239\n00:17:30.759 --> 00:17:35.389 align:middle line:100%,end position:50%,middle\n<i>从高台一跃 跳进一小杯水</i>\n\n240\n00:17:35.806 --> 00:17:37.266 align:middle line:100%,end position:50%,middle\n<i>彻底消失不见</i>\n\n241\n00:17:46.191 --> 00:17:48.861 align:middle line:100%,end position:50%,middle\n女王陛下 您的内衣\n\n242\n00:17:52.447 --> 00:17:55.033 align:middle line:100%,end position:50%,middle\n他刚把我的贴身衣物叠好了\n\n243\n00:17:55.200 --> 00:17:58.912 align:middle line:100%,end position:50%,middle\n天哪 宝贝 你这下可栽了\n\n244\n00:18:50.964 --> 00:18:52.341 align:middle line:100%,end position:50%,middle\n<i>36</i>？\n\n245\n00:19:06.021 --> 00:19:08.524 align:middle line:100%,end position:50%,middle\n我的当事人不想离婚\n\n246\n00:19:10.400 --> 00:19:12.569 align:middle line:100%,end position:50%,middle\n他认真的吗？\n\n247\n00:19:12.736 --> 00:19:14.613 align:middle line:100%,end position:50%,middle\n真打算自己给自己辩护？\n\n248\n00:19:14.780 --> 00:19:16.865 align:middle line:100%,end position:50%,middle\n我可是读过<i>1</i>学期法学院的\n\n249\n00:19:17.032 --> 00:19:19.785 align:middle line:100%,end position:50%,middle\n很好 那怎么他才会愿意呢？\n\n250\n00:19:20.369 --> 00:19:23.539 align:middle line:100%,end position:50%,middle\n听着 你毁了我的生活\n\n251\n00:19:23.705 --> 00:19:26.583 align:middle line:100%,end position:50%,middle\n可我想问 为什么非得离开我\n\n252\n00:19:26.750 --> 00:19:29.628 align:middle line:100%,end position:50%,middle\n才能找到自己？\n为什么不说出你的想法？\n\n253\n00:19:29.795 --> 00:19:32.297 align:middle line:100%,end position:50%,middle\n- 说了 你从不听\n- 不 你从没说过\n\n254\n00:19:32.464 --> 00:19:35.217 align:middle line:100%,end position:50%,middle\n“你真烂 我过得很不开心”\n\n255\n00:19:35.384 --> 00:19:38.720 align:middle line:100%,end position:50%,middle\n你直接走了\n从没给我解决问题的机会\n\n256\n00:19:38.887 --> 00:19:41.723 align:middle line:100%,end position:50%,middle\n这不公平 你就是放弃了\n我发过誓\n\n257\n00:19:41.890 --> 00:19:44.810 align:middle line:100%,end position:50%,middle\n至死不渝 我是认真的\n\n258\n00:19:45.310 --> 00:19:48.188 align:middle line:100%,end position:50%,middle\n我相信这只是暂时的\n我愿意等过去\n\n259\n00:19:48.355 --> 00:19:49.815 align:middle line:100%,end position:50%,middle\n史蒂芬 你总是在等\n\n260\n00:19:49.982 --> 00:19:52.234 align:middle line:100%,end position:50%,middle\n等我回家 等我想生孩子\n\n261\n00:19:52.401 --> 00:19:55.070 align:middle line:100%,end position:50%,middle\n等我给你做晚饭\n为什么就不能承认\n\n262\n00:19:55.237 --> 00:19:57.406 align:middle line:100%,end position:50%,middle\n我们都不想再这么不开心了？\n\n263\n00:19:57.573 --> 00:20:00.075 align:middle line:100%,end position:50%,middle\n我承认自己偶尔不靠谱\n\n264\n00:20:00.242 --> 00:20:03.495 align:middle line:100%,end position:50%,middle\n常常分心\n可我以为你喜欢我这样\n\n265\n00:20:03.662 --> 00:20:05.998 align:middle line:100%,end position:50%,middle\n以为我可以有希望和梦想\n\n266\n00:20:06.164 --> 00:20:09.751 align:middle line:100%,end position:50%,middle\n有梦想当然好 史蒂芬\n但你得选定<i>1</i>个\n\n267\n00:20:09.918 --> 00:20:11.920 align:middle line:100%,end position:50%,middle\n好 我选<i>1</i>个 我选你\n\n268\n00:20:21.722 --> 00:20:24.141 align:middle line:100%,end position:50%,middle\n我知道这很难受\n\n269\n00:20:25.517 --> 00:20:30.189 align:middle line:100%,end position:50%,middle\n但我全心全意相信\n你会找到一个人\n\n270\n00:20:30.355 --> 00:20:32.941 align:middle line:100%,end position:50%,middle\n她跟你有相同的愿望\n\n271\n00:20:33.108 --> 00:20:36.445 align:middle line:100%,end position:50%,middle\n能给你想要也应得的生活\n可那个人不是我\n\n272\n00:20:36.862 --> 00:20:40.949 align:middle line:100%,end position:50%,middle\n你显然根本不懂我想要什么\n\n273\n00:20:44.036 --> 00:20:46.288 align:middle line:100%,end position:50%,middle\n我的当事人想呈上一首自作曲\n\n274\n00:20:46.455 --> 00:20:50.792 align:middle line:100%,end position:50%,middle\n他认为与这次协商有关\n大概是这么唱的\n\n275\n00:20:51.793 --> 00:20:53.420 align:middle line:100%,end position:50%,middle\n你在开玩笑吗？\n\n276\n00:20:57.633 --> 00:20:59.927 align:middle line:100%,end position:50%,middle\n逃兵 逃兵 逃兵！\n\n277\n00:21:00.093 --> 00:21:03.055 align:middle line:100%,end position:50%,middle\n就算全是我的错 好吗？\n是我受不了\n\n278\n00:21:03.222 --> 00:21:06.225 align:middle line:100%,end position:50%,middle\n再花一个周末逛那些盒子般的大卖场\n\n279\n00:21:06.391 --> 00:21:07.935 align:middle line:100%,end position:50%,middle\n赊账买电器\n\n280\n00:21:08.101 --> 00:21:12.272 align:middle line:100%,end position:50%,middle\n还假装过着\n我们都不懂怎么过的夫妻生活\n\n281\n00:21:12.439 --> 00:21:13.815 align:middle line:100%,end position:50%,middle\n那烤面包机可是你想要的\n\n282\n00:21:13.982 --> 00:21:19.321 align:middle line:100%,end position:50%,middle\n“你喜欢装 就装吧 你装得好\n我才是废物 我就是装不像”\n\n283\n00:21:19.655 --> 00:21:22.491 align:middle line:100%,end position:50%,middle\n- 那时我表现得很糟\n- 现在进展如何？\n\n284\n00:21:22.658 --> 00:21:25.077 align:middle line:100%,end position:50%,middle\n我们愿意给他一半财产\n\n285\n00:21:25.244 --> 00:21:28.288 align:middle line:100%,end position:50%,middle\n再加上我当事人的退休金账户\n\n286\n00:21:29.456 --> 00:21:31.667 align:middle line:100%,end position:50%,middle\n那就全拿去吧 全部\n\n287\n00:21:31.834 --> 00:21:34.169 align:middle line:100%,end position:50%,middle\n他还是不答应\n\n288\n00:21:34.670 --> 00:21:37.464 align:middle line:100%,end position:50%,middle\n- 他现在恨我了\n- 他不恨你\n\n289\n00:21:37.631 --> 00:21:40.008 align:middle line:100%,end position:50%,middle\n他只是心碎了\n\n290\n00:21:43.178 --> 00:21:44.680 align:middle line:100%,end position:50%,middle\n我觉得他恨你\n\n291\n00:21:44.847 --> 00:21:46.807 align:middle line:100%,end position:50%,middle\n以后绝不让你出地下室了\n\n292\n00:21:46.974 --> 00:21:50.227 align:middle line:100%,end position:50%,middle\n下周再聊 看看情况怎么样？\n\n293\n00:21:50.394 --> 00:21:51.979 align:middle line:100%,end position:50%,middle\n- 好\n- 这种事\n\n294\n00:21:52.145 --> 00:21:53.772 align:middle line:100%,end position:50%,middle\n总会慢慢解决的\n\n295\n00:22:08.871 --> 00:22:10.622 align:middle line:100%,end position:50%,middle\n你为什么开始吃素？\n\n296\n00:22:10.789 --> 00:22:13.041 align:middle line:100%,end position:50%,middle\n有一次看见了宰牛\n\n297\n00:22:13.208 --> 00:22:15.043 align:middle line:100%,end position:50%,middle\n你晚饭几乎没吃\n\n298\n00:22:15.210 --> 00:22:17.546 align:middle line:100%,end position:50%,middle\n他才<i>28</i>岁\n\n299\n00:22:20.382 --> 00:22:23.468 align:middle line:100%,end position:50%,middle\n他很难受吧？你呢？\n\n300\n00:22:23.635 --> 00:22:25.971 align:middle line:100%,end position:50%,middle\n冥想有帮助\n\n301\n00:22:27.264 --> 00:22:28.557 align:middle line:100%,end position:50%,middle\n莉兹\n\n302\n00:22:28.932 --> 00:22:32.019 align:middle line:100%,end position:50%,middle\n记得几年前吗\n你一头扎进\n\n303\n00:22:32.186 --> 00:22:34.855 align:middle line:100%,end position:50%,middle\n厨房装修里\n一心想做\n\n304\n00:22:35.022 --> 00:22:36.940 align:middle line:100%,end position:50%,middle\n完美的妻子和厨娘\n\n305\n00:22:37.107 --> 00:22:38.525 align:middle line:100%,end position:50%,middle\n我是想经营好婚姻\n\n306\n00:22:38.692 --> 00:22:41.570 align:middle line:100%,end position:50%,middle\n我觉得你现在唱诵 冥想\n\n307\n00:22:41.737 --> 00:22:43.405 align:middle line:100%,end position:50%,middle\n也只是换了个形式而已\n\n308\n00:22:47.034 --> 00:22:48.744 align:middle line:100%,end position:50%,middle\n那部纪录片一定给我看看\n\n309\n00:22:48.911 --> 00:22:50.871 align:middle line:100%,end position:50%,middle\n我也在考虑吃素\n\n310\n00:22:51.038 --> 00:22:52.998 align:middle line:100%,end position:50%,middle\n我的甘油三酯都高上天了\n\n311\n00:22:53.165 --> 00:22:54.499 align:middle line:100%,end position:50%,middle\n好 谢谢你们招待\n\n312\n00:22:54.666 --> 00:22:56.710 align:middle line:100%,end position:50%,middle\n很高兴认识你\n\n313\n00:23:01.089 --> 00:23:04.968 align:middle line:100%,end position:50%,middle\n- 怎么了？\n- 没什么 就是\n\n314\n00:23:05.135 --> 00:23:07.095 align:middle line:100%,end position:50%,middle\n你以前有点像史蒂芬\n\n315\n00:23:07.262 --> 00:23:09.598 align:middle line:100%,end position:50%,middle\n现在又有点像大卫\n\n316\n00:23:09.765 --> 00:23:11.391 align:middle line:100%,end position:50%,middle\n你懂吧？\n\n317\n00:23:12.184 --> 00:23:16.939 align:middle line:100%,end position:50%,middle\n就像人养狗养久了\n会跟自己的狗越来越像\n\n318\n00:23:19.441 --> 00:23:21.902 align:middle line:100%,end position:50%,middle\n他为什么说我俩像同一只狗？\n\n319\n00:23:22.069 --> 00:23:23.612 align:middle line:100%,end position:50%,middle\n- 他在开玩笑\n- 不好笑\n\n320\n00:23:23.779 --> 00:23:26.323 align:middle line:100%,end position:50%,middle\n他喝了<i>5</i>瓶喜力 早醉了\n\n321\n00:23:26.490 --> 00:23:28.700 align:middle line:100%,end position:50%,middle\n还是不好笑\n\n322\n00:23:28.867 --> 00:23:31.328 align:middle line:100%,end position:50%,middle\n我们才不像同一只狗\n\n323\n00:23:32.120 --> 00:23:37.584 align:middle line:100%,end position:50%,middle\n硬要说的话 你像柯利犬\n我像藏獒\n\n324\n00:23:47.719 --> 00:23:50.764 align:middle line:100%,end position:50%,middle\n你就不能给我个想你的机会吗？\n\n325\n00:24:46.361 --> 00:24:47.738 align:middle line:100%,end position:50%,middle\n<i>你要离开1年？</i>\n\n326\n00:24:47.905 --> 00:24:50.032 align:middle line:100%,end position:50%,middle\n<i>迪莉娅 知道我醒来时什么感觉吗？</i>\n\n327\n00:24:50.199 --> 00:24:54.786 align:middle line:100%,end position:50%,middle\n什么都没有 没激情 没火花\n没信念 没热情 什么都没有\n\n328\n00:24:54.953 --> 00:24:58.165 align:middle line:100%,end position:50%,middle\n这早就不能说只是一时低谷了\n\n329\n00:24:58.332 --> 00:25:01.668 align:middle line:100%,end position:50%,middle\n我害怕得要命 这比死还可怕\n\n330\n00:25:01.835 --> 00:25:04.671 align:middle line:100%,end position:50%,middle\n一想到自己以后就要这样过下去\n\n331\n00:25:04.838 --> 00:25:06.131 align:middle line:100%,end position:50%,middle\n很多人都这样\n\n332\n00:25:06.298 --> 00:25:08.383 align:middle line:100%,end position:50%,middle\n<i>20</i>多岁恋爱 结婚\n\n333\n00:25:08.550 --> 00:25:11.512 align:middle line:100%,end position:50%,middle\n<i>30</i>多岁置办花岗岩台面和白栅栏\n\n334\n00:25:11.678 --> 00:25:14.056 align:middle line:100%,end position:50%,middle\n然后突然发现“这不是我要的”\n\n335\n00:25:14.223 --> 00:25:17.726 align:middle line:100%,end position:50%,middle\n于是失败 跌倒 痛得要命\n再振作起来\n\n336\n00:25:17.893 --> 00:25:20.145 align:middle line:100%,end position:50%,middle\n乖乖去看心理医生\n\n337\n00:25:20.312 --> 00:25:23.815 align:middle line:100%,end position:50%,middle\n- 可不能一走了之\n- 我不是一走了之\n\n338\n00:25:23.982 --> 00:25:25.484 align:middle line:100%,end position:50%,middle\n我需要改变\n\n339\n00:25:25.651 --> 00:25:27.903 align:middle line:100%,end position:50%,middle\n莉兹 这里有人支持你\n\n340\n00:25:28.070 --> 00:25:29.905 align:middle line:100%,end position:50%,middle\n有爱你的亲友\n\n341\n00:25:30.072 --> 00:25:33.742 align:middle line:100%,end position:50%,middle\n可你感觉到我对你的爱和支持吗？\n没有\n\n342\n00:25:33.909 --> 00:25:36.411 align:middle line:100%,end position:50%,middle\n我什么也感觉不到 像没了心跳\n\n343\n00:25:38.956 --> 00:25:41.375 align:middle line:100%,end position:50%,middle\n- 我要去意大利\n- 意大利？为什么？\n\n344\n00:25:41.542 --> 00:25:44.002 align:middle line:100%,end position:50%,middle\n- 你午饭吃了什么？\n- 不记得了 沙拉吧\n\n345\n00:25:44.169 --> 00:25:49.383 align:middle line:100%,end position:50%,middle\n就是啊 我以前对食物 对生活\n都充满了渴望\n\n346\n00:25:49.550 --> 00:25:50.676 align:middle line:100%,end position:50%,middle\n现在全没了\n\n347\n00:25:52.261 --> 00:25:56.557 align:middle line:100%,end position:50%,middle\n我想去个能让我惊叹的地方\n\n348\n00:25:56.723 --> 00:26:00.143 align:middle line:100%,end position:50%,middle\n语言 冰激凌 意大利面 随便什么\n\n349\n00:26:00.310 --> 00:26:03.230 align:middle line:100%,end position:50%,middle\n- 你说话像个大学生\n- 我的行为也一样\n\n350\n00:26:03.397 --> 00:26:06.942 align:middle line:100%,end position:50%,middle\n从<i>15</i>岁起\n我不是在恋爱 就是在分手\n\n351\n00:26:07.109 --> 00:26:10.070 align:middle line:100%,end position:50%,middle\n连<i>2</i>周喘息的时间都没给自己\n\n352\n00:26:10.237 --> 00:26:13.532 align:middle line:100%,end position:50%,middle\n好好面对一下自己\n\n353\n00:26:15.868 --> 00:26:17.744 align:middle line:100%,end position:50%,middle\n你和大卫怎么了？\n\n354\n00:26:26.378 --> 00:26:27.462 align:middle line:100%,end position:50%,middle\n怎么了 吵架了？\n\n355\n00:26:27.796 --> 00:26:29.840 align:middle line:100%,end position:50%,middle\n我不知道该怎么待在这里\n\n356\n00:26:30.007 --> 00:26:33.635 align:middle line:100%,end position:50%,middle\n想知道吗？\n别总等着什么就行了\n\n357\n00:26:38.307 --> 00:26:43.020 align:middle line:100%,end position:50%,middle\n我要去意大利\n再去大卫那位导师在印度的修行院\n\n358\n00:26:43.187 --> 00:26:46.607 align:middle line:100%,end position:50%,middle\n最后在巴厘岛结束这一年的旅行\n\n359\n00:26:49.776 --> 00:26:51.153 align:middle line:100%,end position:50%,middle\n我就这么决定了\n\n360\n00:26:51.320 --> 00:26:53.989 align:middle line:100%,end position:50%,middle\n这倒比较难反驳 海滩是很美\n可为什么要去？\n\n361\n00:26:54.156 --> 00:26:56.158 align:middle line:100%,end position:50%,middle\n- 凯图说我会去\n- 那个没牙的老头？\n\n362\n00:26:56.325 --> 00:26:57.409 align:middle line:100%,end position:50%,middle\n人在绝望的时候\n\n363\n00:26:57.576 --> 00:27:00.078 align:middle line:100%,end position:50%,middle\n要是有个家伙\n没错 长得有点像尤达\n\n364\n00:27:00.245 --> 00:27:03.498 align:middle line:100%,end position:50%,middle\n给你一个预言 你总得回应\n\n365\n00:27:03.665 --> 00:27:05.834 align:middle line:100%,end position:50%,middle\n- 要来片Xanax吗？\n- 随时都要\n\n366\n00:27:06.835 --> 00:27:10.172 align:middle line:100%,end position:50%,middle\n好 我就直说了\n说完就算了\n\n367\n00:27:10.339 --> 00:27:11.423 align:middle line:100%,end position:50%,middle\n要是没用呢？\n\n368\n00:27:15.928 --> 00:27:18.764 align:middle line:100%,end position:50%,middle\n我的全部人生\n就装在边长<i>12</i>英尺的箱子里\n\n369\n00:27:20.516 --> 00:27:23.185 align:middle line:100%,end position:50%,middle\n知道我每天听多少遍这句话吗？\n\n370\n00:27:23.352 --> 00:27:25.646 align:middle line:100%,end position:50%,middle\n大多数人一辈子都不回来取\n\n371\n00:27:30.526 --> 00:27:31.693 align:middle line:100%,end position:50%,middle\n- 喂？\n<i>- 莉兹</i>\n\n372\n00:27:31.860 --> 00:27:34.821 align:middle line:100%,end position:50%,middle\n好消息 史蒂芬刚签了离婚协议\n\n373\n00:27:43.539 --> 00:27:47.751 align:middle line:100%,end position:50%,middle\n说不定<i>1</i>周后我就身无分文\n还得着痢疾回来了\n\n374\n00:27:47.918 --> 00:27:49.795 align:middle line:100%,end position:50%,middle\n你是我的英雄\n\n375\n00:28:03.517 --> 00:28:04.893 align:middle line:100%,end position:50%,middle\n嘿\n\n376\n00:28:06.478 --> 00:28:09.022 align:middle line:100%,end position:50%,middle\n留下的话 我们每晚都去吃印度菜\n\n377\n00:28:11.108 --> 00:28:12.985 align:middle line:100%,end position:50%,middle\n你从没开口叫我留下\n\n378\n00:28:19.283 --> 00:28:21.159 align:middle line:100%,end position:50%,middle\n走吧 走吧 走吧\n\n379\n00:28:43.432 --> 00:28:45.309 align:middle line:100%,end position:50%,middle\n<i>意大利有个很妙的老笑话</i>\n\n380\n00:28:45.475 --> 00:28:47.811 align:middle line:100%,end position:50%,middle\n<i>有个穷人每天去教堂</i>\n\n381\n00:28:47.978 --> 00:28:52.316 align:middle line:100%,end position:50%,middle\n<i>在一位大圣人的雕像前祈祷</i>\n\n382\n00:28:53.108 --> 00:28:59.114 align:middle line:100%,end position:50%,middle\n<i>“圣人啊 求求您 求求您\n让我中彩票吧”</i>\n\n383\n00:28:59.948 --> 00:29:02.743 align:middle line:100%,end position:50%,middle\n<i>终于 雕像忍无可忍 活了过来</i>\n\n384\n00:29:02.910 --> 00:29:05.120 align:middle line:100%,end position:50%,middle\n<i>低头看着苦苦哀求的人 说道</i>\n\n385\n00:29:05.287 --> 00:29:10.709 align:middle line:100%,end position:50%,middle\n<i>“孩子啊 求求你 求求你\n先买张彩票吧”</i>\n\n386\n00:29:11.543 --> 00:29:13.337 align:middle line:100%,end position:50%,middle\n<i>现在我懂这个笑话了</i>\n\n387\n00:29:13.504 --> 00:29:16.131 align:middle line:100%,end position:50%,middle\n<i>也买好了3张票</i>\n\n388\n00:29:36.568 --> 00:29:39.613 align:middle line:100%,end position:50%,middle\n水要放在炉子上烧热\n\n389\n00:29:41.532 --> 00:29:43.825 align:middle line:100%,end position:50%,middle\n那我要是想洗澡呢？\n\n390\n00:29:43.992 --> 00:29:48.997 align:middle line:100%,end position:50%,middle\n就把水倒进浴缸里\n\n391\n00:29:51.416 --> 00:29:53.335 align:middle line:100%,end position:50%,middle\n好吧\n\n392\n00:29:53.669 --> 00:30:00.092 align:middle line:100%,end position:50%,middle\n这些水好像不够洗澡啊\n\n393\n00:30:02.177 --> 00:30:04.680 align:middle line:100%,end position:50%,middle\n不够\n\n394\n00:30:04.847 --> 00:30:06.598 align:middle line:100%,end position:50%,middle\n够的\n\n395\n00:30:06.765 --> 00:30:10.143 align:middle line:100%,end position:50%,middle\n多装几次 <i>3</i>次 <i>4</i>次 <i>5</i>次\n\n396\n00:30:10.644 --> 00:30:13.856 align:middle line:100%,end position:50%,middle\n重要的地方洗干净就行了\n\n397\n00:30:30.080 --> 00:30:32.541 align:middle line:100%,end position:50%,middle\n这安全吗？这个...\n\n398\n00:30:33.792 --> 00:30:36.044 align:middle line:100%,end position:50%,middle\n脚手架？脚手...\n\n399\n00:30:36.211 --> 00:30:38.213 align:middle line:100%,end position:50%,middle\n它是撑住天花板的\n\n400\n00:30:38.380 --> 00:30:41.592 align:middle line:100%,end position:50%,middle\n不然就塌了\n\n401\n00:30:42.259 --> 00:30:43.886 align:middle line:100%,end position:50%,middle\n亲爱的 什么都会散架\n\n402\n00:30:44.052 --> 00:30:48.724 align:middle line:100%,end position:50%,middle\n人生里只有家庭是永恒的\n\n403\n00:30:52.811 --> 00:30:54.021 align:middle line:100%,end position:50%,middle\n你没结婚\n\n404\n00:30:55.189 --> 00:30:57.149 align:middle line:100%,end position:50%,middle\n不 我<i>离婚了</i>\n\n405\n00:30:57.566 --> 00:30:59.193 align:middle line:100%,end position:50%,middle\n为什么离婚？\n\n406\n00:31:03.113 --> 00:31:04.531 align:middle line:100%,end position:50%,middle\n我们把婚姻弄坏了\n\n407\n00:31:07.576 --> 00:31:10.078 align:middle line:100%,end position:50%,middle\n现在更开心吗？\n\n408\n00:31:14.458 --> 00:31:16.043 align:middle line:100%,end position:50%,middle\n我只有<i>1</i>条规矩\n\n409\n00:31:16.585 --> 00:31:21.757 align:middle line:100%,end position:50%,middle\n不许带陌生男人过夜\n\n410\n00:31:21.924 --> 00:31:24.635 align:middle line:100%,end position:50%,middle\n你们美国姑娘一来意大利\n\n411\n00:31:24.801 --> 00:31:27.137 align:middle line:100%,end position:50%,middle\n就只想吃意大利面\n\n412\n00:31:27.304 --> 00:31:29.348 align:middle line:100%,end position:50%,middle\n还有香肠\n\n413\n00:31:34.186 --> 00:31:35.270 align:middle line:100%,end position:50%,middle\n我租了\n\n414\n00:31:35.604 --> 00:31:36.897 align:middle line:100%,end position:50%,middle\n很好 选得好\n\n415\n00:32:11.098 --> 00:32:12.140 align:middle line:100%,end position:50%,middle\n卡布奇诺\n\n416\n00:32:12.307 --> 00:32:15.477 align:middle line:100%,end position:50%,middle\n- 这里简直像动物园\n- 我的意大利语又烂\n\n417\n00:32:15.644 --> 00:32:18.146 align:middle line:100%,end position:50%,middle\n- 你来多久了？\n- <i>2</i>周 你呢？\n\n418\n00:32:18.313 --> 00:32:20.232 align:middle line:100%,end position:50%,middle\n<i>6</i>周 你会进步的\n\n419\n00:32:20.899 --> 00:32:22.150 align:middle line:100%,end position:50%,middle\n请来<i>2</i>杯卡布奇诺\n\n420\n00:32:22.317 --> 00:32:24.027 align:middle line:100%,end position:50%,middle\n这次牛奶要温的\n\n421\n00:32:24.194 --> 00:32:26.238 align:middle line:100%,end position:50%,middle\n昨天太烫 把我舌头烫了\n\n422\n00:32:26.864 --> 00:32:28.699 align:middle line:100%,end position:50%,middle\n- 你喜欢千层酥吗？\n- 当然\n\n423\n00:32:28.866 --> 00:32:31.243 align:middle line:100%,end position:50%,middle\n再来<i>2</i>份千层酥 谢谢\n\n424\n00:32:31.994 --> 00:32:34.079 align:middle line:100%,end position:50%,middle\n你的意大利语真棒\n\n425\n00:32:34.246 --> 00:32:37.624 align:middle line:100%,end position:50%,middle\n我的家教很厉害\n你想要的话我给你他的号码\n\n426\n00:32:37.791 --> 00:32:40.377 align:middle line:100%,end position:50%,middle\n- 他很会教 也需要工作\n- 太好了\n\n427\n00:32:40.544 --> 00:32:42.462 align:middle line:100%,end position:50%,middle\n你是荷兰人？德国人？\n\n428\n00:32:42.629 --> 00:32:46.258 align:middle line:100%,end position:50%,middle\n瑞典人 比他们还冷淡\n你想象得到吧\n\n429\n00:32:46.925 --> 00:32:49.803 align:middle line:100%,end position:50%,middle\n- 对了 我叫莉兹\n- 苏菲\n\n430\n00:34:15.556 --> 00:34:16.598 align:middle line:100%,end position:50%,middle\n你可以说\n\n431\n00:34:21.728 --> 00:34:22.855 align:middle line:100%,end position:50%,middle\n那是过去式\n\n432\n00:34:34.616 --> 00:34:35.951 align:middle line:100%,end position:50%,middle\n太快了 不过还行\n\n433\n00:34:36.118 --> 00:34:37.244 align:middle line:100%,end position:50%,middle\n你可以说\n\n434\n00:34:40.080 --> 00:34:41.456 align:middle line:100%,end position:50%,middle\n对\n\n435\n00:34:49.715 --> 00:34:51.132 align:middle line:100%,end position:50%,middle\n多美的一个词\n\n436\n00:34:51.300 --> 00:34:54.636 align:middle line:100%,end position:50%,middle\n不就是“我们过街吧”吗\n很普通啊\n\n437\n00:34:55.469 --> 00:34:59.808 align:middle line:100%,end position:50%,middle\n不 它把意大利语的声音\n完美地结合在了一起\n\n438\n00:34:59.975 --> 00:35:04.146 align:middle line:100%,end position:50%,middle\n惆怅的“啊” 滚动的颤音\n还有轻柔的“丝”\n\n439\n00:35:04.479 --> 00:35:06.315 align:middle line:100%,end position:50%,middle\n- 倒也是\n- 我爱死了\n\n440\n00:35:06.690 --> 00:35:09.026 align:middle line:100%,end position:50%,middle\n好 我来教你一个词\n\n441\n00:35:13.614 --> 00:35:14.656 align:middle line:0%,start position:50%,middle\n心理医生\n\n442\n00:35:17.826 --> 00:35:18.952 align:middle line:100%,end position:50%,middle\n心理医生\n\n443\n00:35:19.119 --> 00:35:20.913 align:middle line:100%,end position:50%,middle\n- 别闹了\n- 不错 你得学会幽默\n\n444\n00:35:21.079 --> 00:35:22.581 align:middle line:100%,end position:50%,middle\n- 不好笑\n- 来 干杯\n\n445\n00:35:31.006 --> 00:35:33.175 align:middle line:100%,end position:50%,middle\n- 周二<i>5</i>点再继续？\n- 好\n\n446\n00:35:33.342 --> 00:35:36.512 align:middle line:100%,end position:50%,middle\n- 再开一瓶“心理医生”？\n- 当然\n\n447\n00:35:36.678 --> 00:35:39.056 align:middle line:100%,end position:50%,middle\n- 你学得很好 莉兹\n- 谢谢\n\n448\n00:35:39.223 --> 00:35:41.391 align:middle line:100%,end position:50%,middle\n而且一定要对自己宽容些\n\n449\n00:35:41.558 --> 00:35:43.060 align:middle line:100%,end position:50%,middle\n尤其是学新东西的时候\n\n450\n00:35:43.227 --> 00:35:45.020 align:middle line:100%,end position:50%,middle\n对 <i>谢谢</i> 我同意\n\n451\n00:35:45.187 --> 00:35:48.732 align:middle line:100%,end position:50%,middle\n可你的英语...\n你怎么能跟我说得这么流利？\n\n452\n00:35:48.899 --> 00:35:51.443 align:middle line:100%,end position:50%,middle\n我看你能教我的 比我教你的还多\n\n453\n00:35:51.610 --> 00:35:53.529 align:middle line:100%,end position:50%,middle\n你的意大利语很好 非常好\n\n454\n00:35:53.862 --> 00:35:55.155 align:middle line:100%,end position:50%,middle\n好吧\n\n455\n00:36:39.241 --> 00:36:41.743 align:middle line:100%,end position:50%,middle\n我独自一人\n\n456\n00:38:00.489 --> 00:38:02.991 align:middle line:100%,end position:50%,middle\n真有罪恶感 来罗马<i>3</i>周了\n\n457\n00:38:03.158 --> 00:38:05.661 align:middle line:100%,end position:50%,middle\n我就学了几个意大利语词 再就是吃\n\n458\n00:38:05.827 --> 00:38:07.663 align:middle line:100%,end position:50%,middle\n你有罪恶感是因为你是美国人\n\n459\n00:38:07.829 --> 00:38:09.706 align:middle line:100%,end position:50%,middle\n你们不懂怎么享受\n\n460\n00:38:09.873 --> 00:38:12.084 align:middle line:100%,end position:50%,middle\n- 你说什么？\n- 真的\n\n461\n00:38:12.251 --> 00:38:15.504 align:middle line:100%,end position:50%,middle\n美国人懂娱乐 却不懂享受\n\n462\n00:38:16.171 --> 00:38:18.924 align:middle line:100%,end position:50%,middle\n对了 这位是卢卡·斯帕盖蒂\n\n463\n00:38:19.508 --> 00:38:21.635 align:middle line:100%,end position:50%,middle\n你叫卢卡·意大利面？\n\n464\n00:38:21.802 --> 00:38:23.679 align:middle line:100%,end position:50%,middle\n对 我们家就姓这个\n\n465\n00:38:23.846 --> 00:38:26.682 align:middle line:100%,end position:50%,middle\n意大利面是我们发明的\n我认真的 听我说\n\n466\n00:38:26.849 --> 00:38:29.226 align:middle line:100%,end position:50%,middle\n想知道你们美国人的问题吗？\n\n467\n00:38:29.560 --> 00:38:31.812 align:middle line:100%,end position:50%,middle\n你们工作太拼 把自己累坏\n\n468\n00:38:31.979 --> 00:38:34.648 align:middle line:100%,end position:50%,middle\n然后回到家 整个周末\n\n469\n00:38:34.815 --> 00:38:37.442 align:middle line:100%,end position:50%,middle\n就穿着睡衣守着电视\n\n470\n00:38:37.609 --> 00:38:39.361 align:middle line:100%,end position:50%,middle\n其实还真差不多\n\n471\n00:38:39.528 --> 00:38:43.699 align:middle line:100%,end position:50%,middle\n可你们不懂享受\n得有人告诉你们“你值得”\n\n472\n00:38:43.866 --> 00:38:46.785 align:middle line:100%,end position:50%,middle\n看到广告说“又到Miller时刻”\n\n473\n00:38:46.952 --> 00:38:51.039 align:middle line:100%,end position:50%,middle\n你们就说“对 该去买个<i>6</i>连包了”\n\n474\n00:38:51.206 --> 00:38:56.044 align:middle line:100%,end position:50%,middle\n全喝光 第二天早上\n醒来难受得要命\n\n475\n00:38:56.211 --> 00:38:59.047 align:middle line:100%,end position:50%,middle\n意大利人就不用别人提醒\n\n476\n00:38:59.214 --> 00:39:03.427 align:middle line:100%,end position:50%,middle\n走过一块招牌\n上面写着“今天该歇歇了”\n\n477\n00:39:03.594 --> 00:39:05.053 align:middle line:100%,end position:50%,middle\n他会说“对 我知道\n\n478\n00:39:05.220 --> 00:39:09.057 align:middle line:100%,end position:50%,middle\n所以我准备中午歇一歇\n\n479\n00:39:09.224 --> 00:39:12.477 align:middle line:100%,end position:50%,middle\n去你家 跟你老婆上床”\n\n480\n00:39:14.062 --> 00:39:16.565 align:middle line:100%,end position:50%,middle\n我们管这叫\n<i>“dolce far niente”</i>\n\n481\n00:39:16.732 --> 00:39:18.150 align:middle line:100%,end position:50%,middle\n意思是\n\n482\n00:39:18.483 --> 00:39:22.237 align:middle line:100%,end position:50%,middle\n“无所事事的甜美”\n这方面我们可是大师\n\n483\n00:39:35.042 --> 00:39:36.960 align:middle line:100%,end position:50%,middle\n他说得对 他说\n\n484\n00:39:37.127 --> 00:39:38.879 align:middle line:100%,end position:50%,middle\n不能这样学意大利语\n\n485\n00:39:39.046 --> 00:39:43.467 align:middle line:100%,end position:50%,middle\n说意大利语不能光靠嘴\n还得靠手\n\n486\n00:39:43.634 --> 00:39:44.676 align:middle line:100%,end position:50%,middle\n这样？\n\n487\n00:39:48.263 --> 00:39:50.933 align:middle line:100%,end position:50%,middle\n好 这就是大喊\n\n488\n00:39:54.937 --> 00:39:56.188 align:middle line:100%,end position:50%,middle\n这顿饭太棒了\n\n489\n00:40:06.406 --> 00:40:07.783 align:middle line:100%,end position:50%,middle\n吃屎去吧\n\n490\n00:40:09.952 --> 00:40:11.745 align:middle line:100%,end position:50%,middle\n看得我胃疼\n\n491\n00:40:12.913 --> 00:40:14.164 align:middle line:100%,end position:50%,middle\n去你的\n\n492\n00:40:15.040 --> 00:40:17.960 align:middle line:100%,end position:50%,middle\n- 那好像是我邻居洛伦佐\n- 真迷人\n\n493\n00:40:21.463 --> 00:40:23.924 align:middle line:100%,end position:50%,middle\n另一种说“去你的”的方式\n\n494\n00:40:34.852 --> 00:40:37.271 align:middle line:100%,end position:50%,middle\n那开胃菜我想就来...\n\n495\n00:40:37.437 --> 00:40:39.106 align:middle line:100%,end position:50%,middle\n不好意思\n\n496\n00:40:39.648 --> 00:40:40.691 align:middle line:100%,end position:50%,middle\n过来\n\n497\n00:40:43.360 --> 00:40:44.403 align:middle line:100%,end position:50%,middle\n我们这桌要\n\n498\n00:40:44.570 --> 00:40:47.656 align:middle line:100%,end position:50%,middle\n一大盘犹太式炸朝鲜蓟\n\n499\n00:40:47.990 --> 00:40:49.324 align:middle line:100%,end position:50%,middle\n意式生火腿配蜜瓜\n\n500\n00:40:49.491 --> 00:40:51.869 align:middle line:100%,end position:50%,middle\n还有茄子配烟熏里科塔奶酪\n\n501\n00:40:52.786 --> 00:40:54.746 align:middle line:100%,end position:50%,middle\n然后是卡尔博纳拉意面\n\n502\n00:40:55.414 --> 00:40:57.499 align:middle line:100%,end position:50%,middle\n兔肉酱宽面\n\n503\n00:40:57.666 --> 00:40:59.626 align:middle line:100%,end position:50%,middle\n还有蛤蜊扁面\n\n504\n00:40:59.793 --> 00:41:02.004 align:middle line:100%,end position:50%,middle\n再来罗马式炖牛肚\n\n505\n00:41:02.171 --> 00:41:03.172 align:middle line:100%,end position:50%,middle\n火腿小牛肉\n\n506\n00:41:03.338 --> 00:41:06.341 align:middle line:100%,end position:50%,middle\n真扎诺的散装葡萄酒再来<i>2</i>升\n\n507\n00:41:06.508 --> 00:41:07.801 align:middle line:100%,end position:50%,middle\n谢谢\n\n508\n00:41:10.220 --> 00:41:13.015 align:middle line:100%,end position:50%,middle\n你做到了 太好了\n\n509\n00:41:13.182 --> 00:41:15.184 align:middle line:100%,end position:50%,middle\n莉兹·吉尔伯特\n你现在是罗马女人了\n\n510\n00:41:15.350 --> 00:41:17.644 align:middle line:100%,end position:50%,middle\n哪有 只是名誉称号\n\n511\n00:41:17.811 --> 00:41:19.771 align:middle line:100%,end position:50%,middle\n那才是真正的罗马女人\n\n512\n00:41:23.317 --> 00:41:26.153 align:middle line:100%,end position:50%,middle\n没错 还有很多国际友人\n\n513\n00:41:26.320 --> 00:41:27.863 align:middle line:100%,end position:50%,middle\n这个我倒想咬一口\n\n514\n00:41:29.364 --> 00:41:31.575 align:middle line:100%,end position:50%,middle\n也许你和罗马的关键词不一样\n\n515\n00:41:31.742 --> 00:41:33.368 align:middle line:100%,end position:50%,middle\n- 关键词？\n- 对\n\n516\n00:41:33.535 --> 00:41:37.206 align:middle line:100%,end position:50%,middle\n仔细想想 每个城市都有个关键词\n\n517\n00:41:37.372 --> 00:41:40.209 align:middle line:100%,end position:50%,middle\n比如伦敦的是什么？\n\n518\n00:41:40.375 --> 00:41:42.836 align:middle line:100%,end position:50%,middle\n- 我觉得是“古板”\n- 我同意\n\n519\n00:41:43.212 --> 00:41:46.381 align:middle line:100%,end position:50%,middle\n- 斯德哥尔摩呢？\n- 还用问？“从众”\n\n520\n00:41:46.548 --> 00:41:47.841 align:middle line:100%,end position:50%,middle\n纽约呢？\n\n521\n00:41:48.008 --> 00:41:51.386 align:middle line:100%,end position:50%,middle\n“野心”或者“煤灰”\n\n522\n00:41:51.720 --> 00:41:53.889 align:middle line:100%,end position:50%,middle\n罗马的关键词呢？\n\n523\n00:41:54.306 --> 00:41:56.141 align:middle line:100%,end position:50%,middle\n这可有点难想\n\n524\n00:41:56.308 --> 00:41:57.518 align:middle line:100%,end position:50%,middle\n很经典的\n\n525\n00:41:57.684 --> 00:41:59.186 align:middle line:100%,end position:50%,middle\n“性”\n\n526\n00:42:01.772 --> 00:42:03.398 align:middle line:100%,end position:50%,middle\n那当然\n\n527\n00:42:29.758 --> 00:42:33.428 align:middle line:100%,end position:50%,middle\n莉兹 那你的关键词呢？\n真好奇 我可猜不透\n\n528\n00:42:33.595 --> 00:42:35.264 align:middle line:100%,end position:50%,middle\n这个...\n\n529\n00:42:37.975 --> 00:42:40.102 align:middle line:100%,end position:50%,middle\n也许是...\n\n530\n00:42:40.894 --> 00:42:45.774 align:middle line:100%,end position:50%,middle\n最早是“女儿” 我当得不错\n然后是\n\n531\n00:42:46.233 --> 00:42:49.111 align:middle line:100%,end position:50%,middle\n“妻子” 就不太行了\n\n532\n00:42:49.278 --> 00:42:51.113 align:middle line:100%,end position:50%,middle\n“女朋友”\n\n533\n00:42:52.114 --> 00:42:53.782 align:middle line:100%,end position:50%,middle\n也不太行\n\n534\n00:42:53.949 --> 00:42:55.409 align:middle line:100%,end position:50%,middle\n我的关键词是“作家”\n\n535\n00:42:55.576 --> 00:42:59.079 align:middle line:100%,end position:50%,middle\n可那是你的职业\n不代表你这个人 不是吗？\n\n536\n00:42:59.580 --> 00:43:01.748 align:middle line:100%,end position:50%,middle\n也许你是个在寻找关键词的女人\n\n537\n00:43:15.012 --> 00:43:19.308 align:middle line:100%,end position:50%,middle\n<i>苏菲 我是莉兹 去那不勒斯吧\n也许我的关键词是“披萨”</i>\n\n538\n00:43:33.822 --> 00:43:37.409 align:middle line:100%,end position:50%,middle\n听着 女士 我虽然才<i>7</i>岁\n也看得出你是个大傻瓜\n\n539\n00:43:37.576 --> 00:43:39.912 align:middle line:100%,end position:50%,middle\n因为我是那不勒斯人\n\n540\n00:43:40.495 --> 00:43:42.789 align:middle line:100%,end position:50%,middle\n我喜欢这里 可乔瓦尼叫我小心\n\n541\n00:43:42.956 --> 00:43:45.501 align:middle line:100%,end position:50%,middle\n他表亲在这里的博物馆遭过抢劫\n\n542\n00:43:45.667 --> 00:43:48.170 align:middle line:100%,end position:50%,middle\n- 真的假的？\n- 小心摩托车 真的\n\n543\n00:44:02.017 --> 00:44:05.687 align:middle line:100%,end position:50%,middle\n我恋爱了 我和披萨谈起恋爱了\n\n544\n00:44:06.063 --> 00:44:09.149 align:middle line:100%,end position:50%,middle\n你倒像要跟披萨分手 怎么了？\n\n545\n00:44:09.316 --> 00:44:10.526 align:middle line:100%,end position:50%,middle\n我吃不了\n\n546\n00:44:10.692 --> 00:44:13.153 align:middle line:100%,end position:50%,middle\n什么叫吃不了？\n这可是那不勒斯的披萨\n\n547\n00:44:13.320 --> 00:44:15.489 align:middle line:100%,end position:50%,middle\n吃这块披萨是你的道德义务\n\n548\n00:44:15.864 --> 00:44:19.993 align:middle line:100%,end position:50%,middle\n我也想吃 可我大概胖了<i>10</i>磅\n\n549\n00:44:20.160 --> 00:44:22.162 align:middle line:100%,end position:50%,middle\n你看 我有了这个...\n\n550\n00:44:22.329 --> 00:44:24.540 align:middle line:100%,end position:50%,middle\n就在这儿 这叫什么来着？\n\n551\n00:44:24.831 --> 00:44:27.042 align:middle line:100%,end position:50%,middle\n游泳圈\n\n552\n00:44:27.876 --> 00:44:29.545 align:middle line:100%,end position:50%,middle\n我也有啊\n\n553\n00:44:29.711 --> 00:44:32.464 align:middle line:100%,end position:50%,middle\n光看着这块披萨\n<i>5</i>分钟前我就解开牛仔裤扣子了\n\n554\n00:44:32.631 --> 00:44:33.924 align:middle line:100%,end position:50%,middle\n我问你个问题\n\n555\n00:44:34.091 --> 00:44:37.177 align:middle line:100%,end position:50%,middle\n这些年来 你在男人面前脱衣服时\n\n556\n00:44:37.678 --> 00:44:41.014 align:middle line:100%,end position:50%,middle\n- 也没那么多年\n- 好吧 那\n\n557\n00:44:41.431 --> 00:44:43.058 align:middle line:100%,end position:50%,middle\n有谁叫你走过吗？\n\n558\n00:44:43.225 --> 00:44:46.019 align:middle line:100%,end position:50%,middle\n- 有谁转身走人过吗？\n- 没有\n\n559\n00:44:46.395 --> 00:44:47.855 align:middle line:100%,end position:50%,middle\n因为他根本不在乎\n\n560\n00:44:48.021 --> 00:44:50.732 align:middle line:100%,end position:50%,middle\n跟一个裸女共处一室\n他简直像中了彩票\n\n561\n00:44:50.899 --> 00:44:54.736 align:middle line:100%,end position:50%,middle\n我厌倦了老是说不能吃\n然后每天早上醒来\n\n562\n00:44:54.903 --> 00:44:57.865 align:middle line:100%,end position:50%,middle\n回想前一天吃下的每一样东西\n\n563\n00:44:58.031 --> 00:45:00.075 align:middle line:100%,end position:50%,middle\n计算每一卡路里 就为了知道\n\n564\n00:45:00.242 --> 00:45:03.203 align:middle line:100%,end position:50%,middle\n洗澡时到底该有多嫌弃自己\n\n565\n00:45:03.579 --> 00:45:05.247 align:middle line:100%,end position:50%,middle\n我不管了\n\n566\n00:45:05.414 --> 00:45:08.750 align:middle line:100%,end position:50%,middle\n我没想把自己吃成胖子\n只是不想再内疚了\n\n567\n00:45:09.084 --> 00:45:11.712 align:middle line:100%,end position:50%,middle\n我要把这块披萨吃完\n\n568\n00:45:11.879 --> 00:45:14.715 align:middle line:100%,end position:50%,middle\n然后我们去看足球赛\n\n569\n00:45:14.882 --> 00:45:17.301 align:middle line:100%,end position:50%,middle\n明天再来个小约会\n\n570\n00:45:17.467 --> 00:45:20.888 align:middle line:100%,end position:50%,middle\n给咱俩买大一点的牛仔裤\n\n571\n00:45:22.097 --> 00:45:24.558 align:middle line:100%,end position:50%,middle\n乔瓦尼就喜欢有点肉的\n\n572\n00:45:27.769 --> 00:45:28.937 align:middle line:100%,end position:50%,middle\n这才对嘛\n\n573\n00:45:43.285 --> 00:45:45.621 align:middle line:100%,end position:50%,middle\n他在说“你是为谁踢球的？”\n\n574\n00:45:45.787 --> 00:45:47.039 align:middle line:100%,end position:50%,middle\n<i>“Per chi”</i>就是“为谁”\n\n575\n00:45:53.754 --> 00:45:56.840 align:middle line:100%,end position:50%,middle\n拉 使劲拉 我在收肚子了\n\n576\n00:45:58.592 --> 00:46:00.260 align:middle line:100%,end position:50%,middle\n拿出你们瑞典人的力气来\n\n577\n00:46:04.640 --> 00:46:06.642 align:middle line:100%,end position:50%,middle\n你说索菲娅·罗兰也这样过吗？\n\n578\n00:46:06.808 --> 00:46:08.268 align:middle line:100%,end position:50%,middle\n动了 就快拉上了\n\n579\n00:46:10.145 --> 00:46:12.147 align:middle line:100%,end position:50%,middle\n快 快 快 你都没使劲\n\n580\n00:46:14.107 --> 00:46:16.777 align:middle line:100%,end position:50%,middle\n快拉上了 快拉上了\n成功了\n\n581\n00:46:40.008 --> 00:46:42.803 align:middle line:100%,end position:50%,middle\n真漂亮 你该买下来\n\n582\n00:46:44.429 --> 00:46:46.098 align:middle line:100%,end position:50%,middle\n买给谁？\n\n583\n00:46:46.557 --> 00:46:49.351 align:middle line:100%,end position:50%,middle\n给你自己 莉兹 就给自己\n\n584\n00:46:52.604 --> 00:46:55.691 align:middle line:100%,end position:50%,middle\n不用 有这条大号裤我就满足了\n\n585\n00:47:13.125 --> 00:47:15.127 align:middle line:100%,end position:50%,middle\n谢谢你陪我这一天\n还给我的腿腾出了空间\n\n586\n00:47:16.753 --> 00:47:18.046 align:middle line:100%,end position:50%,middle\n很开心\n\n587\n00:47:20.048 --> 00:47:21.842 align:middle line:100%,end position:50%,middle\n我们去吃东西 你来吗？\n\n588\n00:47:22.009 --> 00:47:24.553 align:middle line:100%,end position:50%,middle\n不了 我就不去了\n\n589\n00:48:25.864 --> 00:48:28.408 align:middle line:100%,end position:50%,middle\n无所事事的甜美\n\n590\n00:48:41.713 --> 00:48:43.465 align:middle line:100%,end position:50%,middle\n<i>求你了 别躺在地上</i>\n\n591\n00:48:50.889 --> 00:48:54.768 align:middle line:100%,end position:50%,middle\n求你能不能...\n上床来好吗？\n\n592\n00:49:04.611 --> 00:49:09.241 align:middle line:100%,end position:50%,middle\n不如我们就承认\n这段感情一团糟\n\n593\n00:49:09.408 --> 00:49:12.286 align:middle line:100%,end position:50%,middle\n可还是一起撑下去呢？\n\n594\n00:49:13.453 --> 00:49:16.832 align:middle line:100%,end position:50%,middle\n接受我们总吵架\n\n595\n00:49:16.999 --> 00:49:19.835 align:middle line:100%,end position:50%,middle\n也几乎不再做爱\n\n596\n00:49:20.002 --> 00:49:23.755 align:middle line:100%,end position:50%,middle\n但还是离不开彼此\n\n597\n00:49:24.214 --> 00:49:27.384 align:middle line:100%,end position:50%,middle\n这样我们就能一辈子在一起\n\n598\n00:49:27.551 --> 00:49:29.595 align:middle line:100%,end position:50%,middle\n很痛苦\n\n599\n00:49:30.721 --> 00:49:33.682 align:middle line:100%,end position:50%,middle\n却庆幸不用分开\n\n600\n00:49:41.690 --> 00:49:43.483 align:middle line:100%,end position:50%,middle\n<i>亲爱的大卫</i>\n\n601\n00:49:43.650 --> 00:49:45.694 align:middle line:100%,end position:50%,middle\n<i>我们有一阵子没联系了</i>\n\n602\n00:49:45.861 --> 00:49:48.864 align:middle line:100%,end position:50%,middle\n<i>也给了我时间好好想一想</i>\n\n603\n00:49:49.323 --> 00:49:52.618 align:middle line:100%,end position:50%,middle\n<i>记得你说过吗\n我们该不开心地过下去</i>\n\n604\n00:49:52.784 --> 00:49:54.119 align:middle line:100%,end position:50%,middle\n<i>这样就能开心</i>\n\n605\n00:49:54.286 --> 00:49:56.538 align:middle line:100%,end position:50%,middle\n<i>我有多爱你</i>\n\n606\n00:49:56.705 --> 00:49:59.374 align:middle line:100%,end position:50%,middle\n<i>从我花了那么久反复琢磨你的提议</i>\n\n607\n00:49:59.541 --> 00:50:01.710 align:middle line:100%,end position:50%,middle\n<i>努力想让它行得通 就能看出来</i>\n\n608\n00:50:02.085 --> 00:50:05.047 align:middle line:100%,end position:50%,middle\n<i>前几天 有个朋友\n带我去了个很奇妙的地方</i>\n\n609\n00:50:05.214 --> 00:50:06.715 align:middle line:100%,end position:50%,middle\n<i>叫奥古斯都陵</i>\n\n610\n00:50:07.216 --> 00:50:10.636 align:middle line:100%,end position:50%,middle\n<i>屋大维·奥古斯都修建它\n用来安放自己的遗骸</i>\n\n611\n00:50:10.802 --> 00:50:14.223 align:middle line:100%,end position:50%,middle\n<i>蛮族来了 把它和其他一切都毁了</i>\n\n612\n00:50:14.389 --> 00:50:17.893 align:middle line:100%,end position:50%,middle\n<i>伟大的奥古斯都\n罗马第1位真正伟大的皇帝</i>\n\n613\n00:50:18.101 --> 00:50:20.020 align:middle line:100%,end position:50%,middle\n<i>他怎么会想到 罗马</i>\n\n614\n00:50:20.187 --> 00:50:23.732 align:middle line:100%,end position:50%,middle\n<i>这个在他眼中代表全世界的地方\n有朝一日也会化作废墟？</i>\n\n615\n00:50:23.899 --> 00:50:27.653 align:middle line:100%,end position:50%,middle\n黑暗时代 甚至有人\n把皇帝的骨灰偷走了\n\n616\n00:50:27.819 --> 00:50:30.322 align:middle line:100%,end position:50%,middle\n<i>12</i>世纪 这里变成了一座堡垒\n\n617\n00:50:30.489 --> 00:50:31.865 align:middle line:100%,end position:50%,middle\n后来又成了斗牛场\n\n618\n00:50:32.032 --> 00:50:34.034 align:middle line:100%,end position:50%,middle\n之后还被用来存放烟花\n\n619\n00:50:35.244 --> 00:50:37.412 align:middle line:100%,end position:50%,middle\n现在成了流浪汉的厕所\n\n620\n00:50:37.621 --> 00:50:40.415 align:middle line:100%,end position:50%,middle\n所以下去时得小心脚下\n\n621\n00:50:43.043 --> 00:50:47.422 align:middle line:100%,end position:50%,middle\n<i>这是罗马最安静 最寂寞的地方之一</i>\n\n622\n00:50:47.589 --> 00:50:51.051 align:middle line:100%,end position:50%,middle\n<i>几个世纪里 城市在它周围生长</i>\n\n623\n00:50:51.218 --> 00:50:53.220 align:middle line:100%,end position:50%,middle\n<i>它像一道珍贵的伤口</i>\n\n624\n00:50:53.387 --> 00:50:57.099 align:middle line:100%,end position:50%,middle\n<i>像你舍不得放下的心碎\n因为那种痛让你沉醉</i>\n\n625\n00:50:57.266 --> 00:50:59.434 align:middle line:100%,end position:50%,middle\n我喜欢乱一点\n\n626\n00:51:00.018 --> 00:51:02.771 align:middle line:100%,end position:50%,middle\n<i>大卫 我们都希望一切别变</i>\n\n627\n00:51:02.938 --> 00:51:05.607 align:middle line:100%,end position:50%,middle\n看来你前任是个天使吧？\n\n628\n00:51:05.774 --> 00:51:07.109 align:middle line:100%,end position:50%,middle\n<i>宁愿忍受痛苦的生活</i>\n\n629\n00:51:07.276 --> 00:51:10.404 align:middle line:100%,end position:50%,middle\n<i>因为害怕改变 害怕一切崩塌</i>\n\n630\n00:51:10.571 --> 00:51:15.117 align:middle line:100%,end position:50%,middle\n<i>可当我环顾这里\n看到它经历的种种混乱</i>\n\n631\n00:51:15.284 --> 00:51:18.120 align:middle line:100%,end position:50%,middle\n<i>被改建 烧毁 洗劫</i>\n\n632\n00:51:18.287 --> 00:51:22.541 align:middle line:100%,end position:50%,middle\n<i>却总能找到办法重新站起来\n我忽然安心了</i>\n\n633\n00:51:22.708 --> 00:51:25.961 align:middle line:100%,end position:50%,middle\n<i>也许混乱的不是我的人生\n而是这个世界</i>\n\n634\n00:51:26.128 --> 00:51:29.756 align:middle line:100%,end position:50%,middle\n<i>真正困住人的 只是对这一切的执着</i>\n\n635\n00:51:30.966 --> 00:51:32.968 align:middle line:100%,end position:50%,middle\n<i>毁灭是一份礼物</i>\n\n636\n00:51:33.177 --> 00:51:36.305 align:middle line:100%,end position:50%,middle\n<i>也是通向蜕变的路</i>\n\n637\n00:51:36.471 --> 00:51:38.140 align:middle line:100%,end position:50%,middle\n嘿\n\n638\n00:51:38.765 --> 00:51:40.309 align:middle line:100%,end position:50%,middle\n准备好了吗？\n\n639\n00:51:41.393 --> 00:51:43.061 align:middle line:100%,end position:50%,middle\n好了\n\n640\n00:51:49.943 --> 00:51:52.946 align:middle line:100%,end position:50%,middle\n<i>即使在这座永恒之城\n奥古斯都陵也让我明白</i>\n\n641\n00:51:53.113 --> 00:51:57.492 align:middle line:100%,end position:50%,middle\n<i>我们得时刻准备好\n迎接一波又一波的蜕变</i>\n\n642\n00:52:01.997 --> 00:52:04.249 align:middle line:100%,end position:50%,middle\n<i>我们都值得更好的生活</i>\n\n643\n00:52:04.416 --> 00:52:07.628 align:middle line:100%,end position:50%,middle\n<i>不该只因害怕分开就会毁灭\n而勉强在一起</i>\n\n644\n00:53:05.269 --> 00:53:08.438 align:middle line:100%,end position:50%,middle\n我妈妈的填馅配方\n陈面包 核桃 都有了\n\n645\n00:53:08.605 --> 00:53:10.858 align:middle line:100%,end position:50%,middle\n再帮我拿些土豆好吗？\n\n646\n00:53:11.024 --> 00:53:13.068 align:middle line:100%,end position:50%,middle\n我怎么老在帮你拿土豆\n\n647\n00:53:13.485 --> 00:53:16.530 align:middle line:100%,end position:50%,middle\n我一直梦想过个真正的美式感恩节\n\n648\n00:53:17.531 --> 00:53:19.908 align:middle line:100%,end position:50%,middle\n也正好给我们的莉兹送行\n\n649\n00:53:21.368 --> 00:53:23.078 align:middle line:100%,end position:50%,middle\n所以\n\n650\n00:53:24.079 --> 00:53:26.290 align:middle line:100%,end position:50%,middle\n- 你这周就走？\n- 对\n\n651\n00:53:27.165 --> 00:53:29.543 align:middle line:100%,end position:50%,middle\n去哪儿来着 伊朗？\n\n652\n00:53:30.335 --> 00:53:31.420 align:middle line:100%,end position:50%,middle\n印度\n\n653\n00:53:34.298 --> 00:53:36.175 align:middle line:100%,end position:50%,middle\n今晚莉兹给我们做美式大餐\n\n654\n00:53:36.341 --> 00:53:39.303 align:middle line:100%,end position:50%,middle\n- 你没结婚 对吧？\n- 没有\n\n655\n00:53:40.387 --> 00:53:43.223 align:middle line:100%,end position:50%,middle\n你朋友怎么回事？她是女同性恋？\n\n656\n00:53:46.602 --> 00:53:49.271 align:middle line:100%,end position:50%,middle\n妈 她不是\n而且她听得懂意大利语\n\n657\n00:53:49.438 --> 00:53:51.607 align:middle line:100%,end position:50%,middle\n跑去地球另一头\n\n658\n00:53:51.773 --> 00:53:54.443 align:middle line:100%,end position:50%,middle\n还怎么再找个丈夫 成个家？\n\n659\n00:53:54.902 --> 00:54:00.282 align:middle line:100%,end position:50%,middle\n要是一个男人说\n“我要旅行<i>1</i>年 认识美好的人”\n\n660\n00:54:00.449 --> 00:54:01.950 align:middle line:100%,end position:50%,middle\n可她不是男人\n\n661\n00:54:02.492 --> 00:54:07.748 align:middle line:100%,end position:50%,middle\n女人更难觉得\n自己有权做选择\n\n662\n00:54:07.915 --> 00:54:10.626 align:middle line:100%,end position:50%,middle\n- 这需要很大勇气\n- 就是\n\n663\n00:54:11.460 --> 00:54:13.962 align:middle line:100%,end position:50%,middle\n你说是勇气 我说是愚蠢\n\n664\n00:54:14.129 --> 00:54:15.923 align:middle line:100%,end position:50%,middle\n妈 够了\n\n665\n00:54:16.757 --> 00:54:19.343 align:middle line:100%,end position:50%,middle\n我认识不少人 都会同意您的话\n\n666\n00:54:20.469 --> 00:54:21.970 align:middle line:100%,end position:50%,middle\n卢卡？\n\n667\n00:54:22.137 --> 00:54:24.139 align:middle line:100%,end position:50%,middle\n火鸡什么时候能好？\n\n668\n00:54:24.848 --> 00:54:26.433 align:middle line:100%,end position:50%,middle\n火鸡...\n\n669\n00:54:26.642 --> 00:54:27.976 align:middle line:100%,end position:50%,middle\n我还没解冻呢\n\n670\n00:54:31.396 --> 00:54:33.357 align:middle line:100%,end position:50%,middle\n糟了\n\n671\n00:54:34.149 --> 00:54:36.151 align:middle line:100%,end position:50%,middle\n就交给你<i>1</i>件事 还搞砸了\n\n672\n00:54:36.318 --> 00:54:39.613 align:middle line:100%,end position:50%,middle\n我分心了嘛 谁还没忘事的时候！\n\n673\n00:54:39.780 --> 00:54:41.615 align:middle line:100%,end position:50%,middle\n好吃的太多了！\n\n674\n00:54:41.782 --> 00:54:43.617 align:middle line:100%,end position:50%,middle\n女人也太多了！\n\n675\n00:54:43.784 --> 00:54:45.702 align:middle line:100%,end position:50%,middle\n所以我就忘了！\n\n676\n00:54:45.869 --> 00:54:47.996 align:middle line:100%,end position:50%,middle\n各位 开饭之前\n\n677\n00:54:48.163 --> 00:54:51.124 align:middle line:100%,end position:50%,middle\n今天是感恩节 我们来感恩吧\n\n678\n00:54:51.291 --> 00:54:54.002 align:middle line:100%,end position:50%,middle\n- 来 手牵起来\n- 好\n\n679\n00:54:54.169 --> 00:54:56.296 align:middle line:100%,end position:50%,middle\n我们就说说\n\n680\n00:54:56.755 --> 00:55:00.384 align:middle line:100%,end position:50%,middle\n今晚要感谢上帝什么\n苏菲 你先来？\n\n681\n00:55:03.011 --> 00:55:06.181 align:middle line:100%,end position:50%,middle\n莉兹 我要感谢你\n\n682\n00:55:06.765 --> 00:55:10.686 align:middle line:100%,end position:50%,middle\n你让我学会欣赏生活\n\n683\n00:55:11.103 --> 00:55:14.189 align:middle line:100%,end position:50%,middle\n连同生活带来的一切\n\n684\n00:55:14.439 --> 00:55:17.943 align:middle line:100%,end position:50%,middle\n小肚腩也好 糟糕的日子也好\n\n685\n00:55:18.402 --> 00:55:19.653 align:middle line:100%,end position:50%,middle\n还有乔瓦尼\n\n686\n00:55:20.320 --> 00:55:22.781 align:middle line:100%,end position:50%,middle\n谢谢你让我感到\n\n687\n00:55:22.948 --> 00:55:24.533 align:middle line:100%,end position:50%,middle\n被爱 有安全感\n\n688\n00:55:26.326 --> 00:55:28.829 align:middle line:100%,end position:50%,middle\n我感谢上帝赐予我\n\n689\n00:55:30.038 --> 00:55:31.623 align:middle line:100%,end position:50%,middle\n恐惧\n\n690\n00:55:31.790 --> 00:55:35.669 align:middle line:100%,end position:50%,middle\n因为这是我第<i>1</i>次\n\n691\n00:55:36.545 --> 00:55:39.381 align:middle line:100%,end position:50%,middle\n害怕身边的人\n\n692\n00:55:39.923 --> 00:55:42.467 align:middle line:100%,end position:50%,middle\n会成为想要离开的那一个\n\n693\n00:55:48.015 --> 00:55:49.725 align:middle line:100%,end position:50%,middle\n莉兹？\n\n694\n00:55:51.810 --> 00:55:56.481 align:middle line:100%,end position:50%,middle\n眼前的这一切 都让我无比感激\n\n695\n00:55:57.816 --> 00:55:59.860 align:middle line:100%,end position:50%,middle\n看到你们这么幸福\n\n696\n00:56:00.027 --> 00:56:03.572 align:middle line:100%,end position:50%,middle\n懂得相爱 懂得照顾彼此\n\n697\n00:56:05.449 --> 00:56:09.494 align:middle line:100%,end position:50%,middle\n我遇到这么多让我钦佩的出色女人\n\n698\n00:56:09.661 --> 00:56:14.750 align:middle line:100%,end position:50%,middle\n还有这么多好男人 照顾自己的爱人\n\n699\n00:56:14.917 --> 00:56:17.753 align:middle line:100%,end position:50%,middle\n哄孩子入睡\n\n700\n00:56:19.254 --> 00:56:21.590 align:middle line:100%,end position:50%,middle\n看到这些\n\n701\n00:56:22.090 --> 00:56:25.761 align:middle line:100%,end position:50%,middle\n能成为其中的一员 我真开心\n\n702\n00:56:30.516 --> 00:56:33.602 align:middle line:100%,end position:50%,middle\n我是全世界最幸运的女孩\n\n703\n00:58:01.356 --> 00:58:03.859 align:middle line:100%,end position:50%,middle\n早餐不错吧？\n\n704\n00:59:29.027 --> 00:59:31.238 align:middle line:100%,end position:50%,middle\n我替你送到房间去\n\n705\n00:59:36.368 --> 00:59:38.245 align:middle line:100%,end position:50%,middle\n已经开始了\n\n706\n01:00:24.082 --> 01:00:27.252 align:middle line:100%,end position:50%,middle\n- 我睡着了\n- 是啊 真可惜\n\n707\n01:00:27.419 --> 01:00:31.632 align:middle line:100%,end position:50%,middle\n全世界冥想时睡着的\n恐怕就我<i>1</i>个人\n\n708\n01:00:39.264 --> 01:00:42.851 align:middle line:100%,end position:50%,middle\n- 这条路通向冥想花园\n- 导师在这里吗？\n\n709\n01:00:43.018 --> 01:00:46.396 align:middle line:100%,end position:50%,middle\n- 她一直都在\n- 我知道 可她本人在吗？\n\n710\n01:00:46.563 --> 01:00:48.649 align:middle line:100%,end position:50%,middle\n她在纽约的修行院\n\n711\n01:00:48.815 --> 01:00:51.193 align:middle line:100%,end position:50%,middle\n可我就是从纽约过来见她的\n\n712\n01:00:51.360 --> 01:00:54.029 align:middle line:100%,end position:50%,middle\n听着像她的小把戏\n\n713\n01:00:57.658 --> 01:01:00.035 align:middle line:100%,end position:50%,middle\n这里是冥想洞\n\n714\n01:01:00.244 --> 01:01:05.249 align:middle line:100%,end position:50%,middle\n全天候开放 还有空调\n\n715\n01:01:12.881 --> 01:01:14.758 align:middle line:100%,end position:50%,middle\n科雷拉？\n\n716\n01:01:15.050 --> 01:01:18.762 align:middle line:100%,end position:50%,middle\n- 这是莉兹·吉尔伯特\n- 你好 很高兴认识你\n\n717\n01:01:22.391 --> 01:01:25.727 align:middle line:100%,end position:50%,middle\n- 你这徽章哪儿买的？\n- 书店就有卖\n\n718\n01:01:25.894 --> 01:01:29.481 align:middle line:100%,end position:50%,middle\n我也得来一个 我就需要这种\n我根本不会倾听\n\n719\n01:01:29.648 --> 01:01:32.568 align:middle line:100%,end position:50%,middle\n一直都不会 我妈以前\n都叫我“小话痨凯茜”\n\n720\n01:01:32.734 --> 01:01:34.653 align:middle line:100%,end position:50%,middle\n因为我老是说个不停 就爱瞎扯\n\n721\n01:01:34.820 --> 01:01:37.698 align:middle line:100%,end position:50%,middle\n看 我又扯起来了 对不起\n\n722\n01:01:38.407 --> 01:01:40.409 align:middle line:100%,end position:50%,middle\n禁语是很好的灵性修行\n\n723\n01:01:40.576 --> 01:01:44.371 align:middle line:100%,end position:50%,middle\n可要是科雷拉能开口\n她会说这比看起来难\n\n724\n01:01:44.538 --> 01:01:47.416 align:middle line:100%,end position:50%,middle\n- 待久了你就明白了\n- 好\n\n725\n01:01:59.595 --> 01:02:02.431 align:middle line:100%,end position:50%,middle\n谢谢 科雷拉 我一定告诉她\n\n726\n01:02:02.598 --> 01:02:04.933 align:middle line:100%,end position:50%,middle\n- 她说什么？\n- 不知道\n\n727\n01:02:05.100 --> 01:02:07.769 align:middle line:100%,end position:50%,middle\n换上干活的衣服\n我带你去做<i>“塞瓦”</i>\n\n728\n01:02:07.936 --> 01:02:10.606 align:middle line:100%,end position:50%,middle\n印度教里指无私奉献的工作\n\n729\n01:02:10.772 --> 01:02:14.818 align:middle line:100%,end position:50%,middle\n- 住在这里的人都要做\n- 好 谢谢\n\n730\n01:02:41.470 --> 01:02:44.973 align:middle line:100%,end position:50%,middle\n世上还有比印度少年更瘦的吗？\n\n731\n01:02:47.559 --> 01:02:49.436 align:middle line:100%,end position:50%,middle\n- 我叫图尔西\n- 莉兹\n\n732\n01:02:49.978 --> 01:02:51.146 align:middle line:100%,end position:50%,middle\n你从哪儿来？\n\n733\n01:02:51.313 --> 01:02:55.275 align:middle line:100%,end position:50%,middle\n隔壁镇 爸妈追随导师好多年了\n\n734\n01:02:55.442 --> 01:02:56.818 align:middle line:100%,end position:50%,middle\n我们常待在这里\n\n735\n01:02:56.985 --> 01:02:58.654 align:middle line:100%,end position:50%,middle\n不过\n\n736\n01:02:58.862 --> 01:03:02.241 align:middle line:100%,end position:50%,middle\n他们想把我嫁出去 这是习俗\n\n737\n01:03:02.407 --> 01:03:06.787 align:middle line:100%,end position:50%,middle\n- 你不愿意？\n- 才不愿意 糟透了\n\n738\n01:03:11.667 --> 01:03:16.505 align:middle line:100%,end position:50%,middle\n我想学心理学\n就像导师当年上大学一样\n\n739\n01:03:16.880 --> 01:03:19.842 align:middle line:100%,end position:50%,middle\n比起同龄男孩 我更愿意陪着神\n\n740\n01:03:20.008 --> 01:03:23.637 align:middle line:100%,end position:50%,middle\n我家人也不明白\n我为什么大老远跑来印度\n\n741\n01:03:24.179 --> 01:03:28.141 align:middle line:100%,end position:50%,middle\n看着家人时 你会不会想\n“我怎么会生在这个家？”\n\n742\n01:03:29.142 --> 01:03:30.519 align:middle line:100%,end position:50%,middle\n你根本想象不到\n\n743\n01:04:08.557 --> 01:04:10.934 align:middle line:100%,end position:50%,middle\n你能结束婚姻 太值得佩服了\n\n744\n01:04:11.643 --> 01:04:14.021 align:middle line:100%,end position:50%,middle\n你现在看起来多开心 多自由\n\n745\n01:04:14.188 --> 01:04:17.232 align:middle line:100%,end position:50%,middle\n我前夫大概会说我自私\n\n746\n01:04:18.525 --> 01:04:21.904 align:middle line:100%,end position:50%,middle\n你不能生自己的气 也别失望\n\n747\n01:04:22.070 --> 01:04:26.074 align:middle line:100%,end position:50%,middle\n有家人不一定非得结婚生子\n\n748\n01:04:28.076 --> 01:04:30.913 align:middle line:100%,end position:50%,middle\n天哪 这儿的蚊子大得\n\n749\n01:04:31.079 --> 01:04:33.415 align:middle line:100%,end position:50%,middle\n站着就能跟母鸡干上一炮\n\n750\n01:04:34.750 --> 01:04:36.919 align:middle line:100%,end position:50%,middle\n- 我爱你\n- 莉兹 你见过\n\n751\n01:04:37.085 --> 01:04:39.421 align:middle line:100%,end position:50%,middle\n- 得州的理查德吗？\n- 你好 得州的理查德\n\n752\n01:04:39.588 --> 01:04:41.924 align:middle line:100%,end position:50%,middle\n- 幸会 吃货\n- 吃货？\n\n753\n01:04:42.090 --> 01:04:45.260 align:middle line:100%,end position:50%,middle\n对 还没看见你 就听到你吃东西\n\n754\n01:04:45.469 --> 01:04:48.263 align:middle line:100%,end position:50%,middle\n从没见过谁一顿吃这么多\n\n755\n01:04:48.472 --> 01:04:50.766 align:middle line:100%,end position:50%,middle\n你可真爱吃\n\n756\n01:04:51.517 --> 01:04:55.562 align:middle line:100%,end position:50%,middle\n今天过得挺糟 大家别介意\n\n757\n01:04:55.729 --> 01:04:59.566 align:middle line:100%,end position:50%,middle\n我想端着这顿大餐\n去别处安静吃完\n\n758\n01:04:59.733 --> 01:05:01.902 align:middle line:100%,end position:50%,middle\n别 你留下 我不说了\n\n759\n01:05:06.281 --> 01:05:08.408 align:middle line:100%,end position:50%,middle\n今天早上看你好像\n\n760\n01:05:08.575 --> 01:05:11.245 align:middle line:100%,end position:50%,middle\n在跟什么难熬的事较劲\n\n761\n01:05:11.411 --> 01:05:13.288 align:middle line:100%,end position:50%,middle\n是你前夫的事？\n\n762\n01:05:14.122 --> 01:05:16.250 align:middle line:100%,end position:50%,middle\n我也有个前妻\n\n763\n01:05:16.875 --> 01:05:19.920 align:middle line:100%,end position:50%,middle\n她以为我改名叫“狗娘养的”了\n\n764\n01:05:23.298 --> 01:05:25.133 align:middle line:100%,end position:50%,middle\n我...\n\n765\n01:05:25.634 --> 01:05:30.639 align:middle line:100%,end position:50%,middle\n我刚在罗马待了一阵\n来这里时感觉好极了\n\n766\n01:05:30.806 --> 01:05:34.268 align:middle line:100%,end position:50%,middle\n如今到了这里 到了源头\n\n767\n01:05:34.434 --> 01:05:37.312 align:middle line:100%,end position:50%,middle\n却比以前更加疏离\n\n768\n01:05:38.146 --> 01:05:39.773 align:middle line:100%,end position:50%,middle\n你为什么来这儿？\n\n769\n01:05:41.316 --> 01:05:42.651 align:middle line:100%,end position:50%,middle\n我只想找到一点平静\n\n770\n01:05:43.235 --> 01:05:44.987 align:middle line:100%,end position:50%,middle\n平静？\n\n771\n01:05:46.613 --> 01:05:49.283 align:middle line:100%,end position:50%,middle\n吃货 想进城堡\n\n772\n01:05:49.449 --> 01:05:51.034 align:middle line:100%,end position:50%,middle\n就得游过护城河\n\n773\n01:05:54.329 --> 01:05:57.332 align:middle line:100%,end position:50%,middle\n这个给你 我知道你吃得下\n\n774\n01:06:03.755 --> 01:06:04.840 align:middle line:100%,end position:50%,middle\n<i>好吧</i>\n\n775\n01:06:05.340 --> 01:06:09.052 align:middle line:100%,end position:50%,middle\n<i>只要放空头脑</i>\n\n776\n01:06:09.553 --> 01:06:10.679 align:middle line:100%,end position:50%,middle\n<i>呼吸</i>\n\n777\n01:06:12.681 --> 01:06:16.143 align:middle line:100%,end position:50%,middle\n<i>这一年结束后 我该做什么？</i>\n\n778\n01:06:16.310 --> 01:06:18.020 align:middle line:100%,end position:50%,middle\n<i>我该住在哪里？</i>\n\n779\n01:06:18.187 --> 01:06:19.479 align:middle line:100%,end position:50%,middle\n<i>也许去芝加哥</i>\n\n780\n01:06:20.564 --> 01:06:24.151 align:middle line:100%,end position:50%,middle\n<i>天哪 我可以弄间冥想室</i>\n\n781\n01:06:24.318 --> 01:06:28.322 align:middle line:100%,end position:50%,middle\n<i>不 别想了 怎么这么难？</i>\n\n782\n01:06:33.994 --> 01:06:36.496 align:middle line:100%,end position:50%,middle\n<i>科雷拉 去你的\n她到底怎么做到的？</i>\n\n783\n01:06:36.663 --> 01:06:39.291 align:middle line:100%,end position:50%,middle\n<i>简直就像特蕾莎修女</i>\n\n784\n01:06:41.585 --> 01:06:44.213 align:middle line:100%,end position:50%,middle\n<i>天哪 杀了我吧</i>\n\n785\n01:06:47.299 --> 01:06:48.884 align:middle line:100%,end position:50%,middle\n- 今天谁困在护城河里了？\n- 闭嘴\n\n786\n01:06:49.092 --> 01:06:51.220 align:middle line:100%,end position:50%,middle\n听着像跟大鳄鱼搏斗了一场\n\n787\n01:06:51.386 --> 01:06:54.640 align:middle line:100%,end position:50%,middle\n你这么他妈的聪明\n又跑这儿干什么？\n\n788\n01:06:54.806 --> 01:06:56.725 align:middle line:100%,end position:50%,middle\n能来这里 就已经够聪明了\n\n789\n01:06:56.892 --> 01:07:00.187 align:middle line:100%,end position:50%,middle\n- 想不想谈谈...\n- 不想跟你聊 谢谢\n\n790\n01:07:00.354 --> 01:07:03.398 align:middle line:100%,end position:50%,middle\n这里就我<i>1</i>个人 你迟早得说\n\n791\n01:07:03.607 --> 01:07:04.691 align:middle line:100%,end position:50%,middle\n我在里面根本没法专心\n\n792\n01:07:04.858 --> 01:07:09.112 align:middle line:100%,end position:50%,middle\n满脑子都是我的冥想室\n想着该怎么装修\n\n793\n01:07:11.073 --> 01:07:12.241 align:middle line:100%,end position:50%,middle\n你他妈逗我呢？\n\n794\n01:07:13.075 --> 01:07:14.076 align:middle line:100%,end position:50%,middle\n你开玩笑吧？\n\n795\n01:07:14.243 --> 01:07:17.579 align:middle line:100%,end position:50%,middle\n冥想室在心里 吃货\n装修那儿去\n\n796\n01:07:17.746 --> 01:07:19.540 align:middle line:100%,end position:50%,middle\n你说话怎么净是标语？\n\n797\n01:07:19.706 --> 01:07:21.083 align:middle line:100%,end position:50%,middle\n就是啊 再送你一句\n\n798\n01:07:21.250 --> 01:07:24.253 align:middle line:100%,end position:50%,middle\n你得学会挑选自己的念头\n\n799\n01:07:24.419 --> 01:07:27.256 align:middle line:100%,end position:50%,middle\n就像每天挑衣服\n这种能力可以练出来\n\n800\n01:07:27.422 --> 01:07:30.676 align:middle line:100%,end position:50%,middle\n你这么想掌控自己的人生\n就得在心念上下功夫\n\n801\n01:07:30.843 --> 01:07:32.719 align:middle line:100%,end position:50%,middle\n这才是唯一该掌控的东西\n\n802\n01:07:32.886 --> 01:07:35.556 align:middle line:100%,end position:50%,middle\n管不住念头 你就麻烦了\n\n803\n01:07:35.722 --> 01:07:36.765 align:middle line:100%,end position:50%,middle\n我在努力啊\n\n804\n01:07:36.932 --> 01:07:39.935 align:middle line:100%,end position:50%,middle\n问题就在这儿\n别使劲了 学会臣服\n\n805\n01:07:40.143 --> 01:07:43.605 align:middle line:100%,end position:50%,middle\n去花园坐着 让心静下来\n\n806\n01:07:43.772 --> 01:07:45.274 align:middle line:100%,end position:50%,middle\n看看会发生什么\n\n807\n01:07:45.440 --> 01:07:47.276 align:middle line:100%,end position:50%,middle\n为什么不顺其自然呢？\n\n808\n01:07:49.278 --> 01:07:51.780 align:middle line:100%,end position:50%,middle\n有人说过你像詹姆斯·泰勒吗？\n\n809\n01:07:56.410 --> 01:07:57.661 align:middle line:100%,end position:50%,middle\n天天有人说\n\n810\n01:08:04.668 --> 01:08:06.837 align:middle line:100%,end position:50%,middle\n天哪 还真像\n\n811\n01:08:11.967 --> 01:08:13.635 align:middle line:100%,end position:50%,middle\n我的祈祷总是一样\n\n812\n01:08:13.802 --> 01:08:17.973 align:middle line:100%,end position:50%,middle\n“上帝啊 求求您 打开我的心\n给我一个指引\n\n813\n01:08:18.182 --> 01:08:21.894 align:middle line:100%,end position:50%,middle\n您也知道 我这人不怎么聪明”\n\n814\n01:08:23.645 --> 01:08:25.981 align:middle line:100%,end position:50%,middle\n瞧你 像飘过加尔各答似的\n\n815\n01:08:26.648 --> 01:08:28.774 align:middle line:100%,end position:50%,middle\n看来刚才冥想得不错\n\n816\n01:08:28.942 --> 01:08:30.652 align:middle line:100%,end position:50%,middle\n我现在大概得疟疾了\n\n817\n01:08:30.903 --> 01:08:32.279 align:middle line:100%,end position:50%,middle\n蚊子包会消的\n\n818\n01:08:32.821 --> 01:08:34.656 align:middle line:100%,end position:50%,middle\n到头来 什么都会消失\n\n819\n01:08:34.823 --> 01:08:37.492 align:middle line:100%,end position:50%,middle\n吃货 你也这样过吗？\n求一个指引？\n\n820\n01:08:39.493 --> 01:08:40.828 align:middle line:100%,end position:50%,middle\n听起来有点耳熟\n\n821\n01:08:40.996 --> 01:08:43.457 align:middle line:100%,end position:50%,middle\n许愿要小心 说不定真会实现\n\n822\n01:08:43.624 --> 01:08:44.832 align:middle line:100%,end position:50%,middle\n你到底怎么回事？\n\n823\n01:08:45.000 --> 01:08:48.837 align:middle line:100%,end position:50%,middle\n爱错女人了还是怎么了？\n\n824\n01:08:49.505 --> 01:08:51.006 align:middle line:100%,end position:50%,middle\n打扰一下 吉尔伯特小姐\n\n825\n01:08:51.215 --> 01:08:53.341 align:middle line:100%,end position:50%,middle\n有你的电话\n\n826\n01:08:54.593 --> 01:08:57.011 align:middle line:100%,end position:50%,middle\n跟<i>古鲁吉塔</i>相处得怎么样？\n\n827\n01:08:57.679 --> 01:09:00.849 align:middle line:100%,end position:50%,middle\n还好 你会喜欢她的\n\n828\n01:09:02.017 --> 01:09:04.435 align:middle line:100%,end position:50%,middle\n收到我的邮件了吗？\n\n829\n01:09:05.145 --> 01:09:09.107 align:middle line:100%,end position:50%,middle\n<i>收到了 抱歉没早点打来</i>\n\n830\n01:09:09.274 --> 01:09:10.692 align:middle line:100%,end position:50%,middle\n为什么没有？\n\n831\n01:09:10.859 --> 01:09:12.194 align:middle line:100%,end position:50%,middle\n<i>因为只要不回复</i>\n\n832\n01:09:12.361 --> 01:09:16.365 align:middle line:100%,end position:50%,middle\n我们的对话就还没结束\n我就还在这段关系里\n\n833\n01:09:18.742 --> 01:09:22.746 align:middle line:100%,end position:50%,middle\n对不起 我们只是时机不对\n\n834\n01:09:24.747 --> 01:09:29.377 align:middle line:100%,end position:50%,middle\n我只是想轻松一点\n事情轻松时 我们也很好\n\n835\n01:09:29.545 --> 01:09:33.881 align:middle line:100%,end position:50%,middle\n我现在不求轻松\n只是不能再这么艰难\n\n836\n01:09:36.176 --> 01:09:37.261 align:middle line:100%,end position:50%,middle\n你听起来不错\n\n837\n01:09:38.136 --> 01:09:39.555 align:middle line:100%,end position:50%,middle\n<i>更坚强了</i>\n\n838\n01:09:39.763 --> 01:09:41.055 align:middle line:100%,end position:50%,middle\n你也是\n\n839\n01:09:42.765 --> 01:09:44.393 align:middle line:100%,end position:50%,middle\n莉兹 我是演员嘛\n\n840\n01:09:47.813 --> 01:09:49.773 align:middle line:100%,end position:50%,middle\n我接到个角色\n\n841\n01:09:51.774 --> 01:09:54.903 align:middle line:100%,end position:50%,middle\n<i>是外百老汇 不过挺不错</i>\n\n842\n01:09:55.070 --> 01:09:57.239 align:middle line:100%,end position:50%,middle\n真替你高兴\n\n843\n01:09:59.199 --> 01:10:00.909 align:middle line:100%,end position:50%,middle\n好吧\n\n844\n01:10:01.076 --> 01:10:03.579 align:middle line:100%,end position:50%,middle\n那回头见了 姑娘\n\n845\n01:10:30.522 --> 01:10:31.607 align:middle line:100%,end position:50%,middle\n瞧瞧你\n\n846\n01:10:31.815 --> 01:10:34.818 align:middle line:100%,end position:50%,middle\n我还从没见你这么专注过\n\n847\n01:10:46.830 --> 01:10:47.956 align:middle line:100%,end position:50%,middle\n你需要来瓶Thums Up\n\n848\n01:10:51.335 --> 01:10:54.630 align:middle line:100%,end position:50%,middle\n别 别让嘴碰到瓶口\n\n849\n01:10:54.838 --> 01:10:57.591 align:middle line:100%,end position:50%,middle\n在印度第<i>1</i>条规矩\n除了自己 什么都别碰\n\n850\n01:11:01.845 --> 01:11:06.266 align:middle line:100%,end position:50%,middle\n天哪 这比可乐甜了<i>5</i>倍吧\n\n851\n01:11:10.312 --> 01:11:13.148 align:middle line:100%,end position:50%,middle\n里面怕不是加了冰毒\n\n852\n01:11:13.982 --> 01:11:15.901 align:middle line:100%,end position:50%,middle\n但愿如此\n\n853\n01:11:19.488 --> 01:11:20.822 align:middle line:100%,end position:50%,middle\n我知道你难受\n\n854\n01:11:22.324 --> 01:11:24.618 align:middle line:100%,end position:50%,middle\n可你的人生正在改变\n\n855\n01:11:24.785 --> 01:11:26.995 align:middle line:100%,end position:50%,middle\n这并不是坏事\n\n856\n01:11:27.162 --> 01:11:30.791 align:middle line:100%,end position:50%,middle\n这里正适合改变\n你四周充满恩典\n\n857\n01:11:31.750 --> 01:11:35.963 align:middle line:100%,end position:50%,middle\n我以为已经放下他了 可是\n\n858\n01:11:36.630 --> 01:11:37.673 align:middle line:100%,end position:50%,middle\n我还爱他\n\n859\n01:11:38.131 --> 01:11:39.174 align:middle line:100%,end position:50%,middle\n那又怎样\n\n860\n01:11:39.383 --> 01:11:41.844 align:middle line:100%,end position:50%,middle\n- 不就是爱上了个人\n- 我真的很想他\n\n861\n01:11:42.010 --> 01:11:43.512 align:middle line:100%,end position:50%,middle\n那就想啊\n\n862\n01:11:43.679 --> 01:11:47.391 align:middle line:100%,end position:50%,middle\n每次想他 就送上光明和爱\n然后放下\n\n863\n01:11:48.183 --> 01:11:51.937 align:middle line:100%,end position:50%,middle\n如果你能清空脑子里\n\n864\n01:11:52.104 --> 01:11:54.189 align:middle line:100%,end position:50%,middle\n对这个男人念念不忘的那部分\n\n865\n01:11:54.398 --> 01:11:57.693 align:middle line:100%,end position:50%,middle\n再放下失败的婚姻\n就能腾出空白 留出一扇门\n\n866\n01:11:57.901 --> 01:12:01.029 align:middle line:100%,end position:50%,middle\n你知道宇宙会拿那扇门做什么吗？\n\n867\n01:12:02.322 --> 01:12:05.701 align:middle line:100%,end position:50%,middle\n涌进来 上帝就会涌进来\n\n868\n01:12:05.909 --> 01:12:11.039 align:middle line:100%,end position:50%,middle\n用超乎你想象的爱填满你\n\n869\n01:12:15.169 --> 01:12:17.045 align:middle line:100%,end position:50%,middle\n吃货\n\n870\n01:12:17.212 --> 01:12:21.550 align:middle line:100%,end position:50%,middle\n我觉得总有一天\n你能爱上整个世界\n\n871\n01:12:26.930 --> 01:12:29.057 align:middle line:100%,end position:50%,middle\n那边卖什么？\n\n872\n01:12:34.563 --> 01:12:38.066 align:middle line:100%,end position:50%,middle\n象头神迦尼萨 能扫除障碍\n\n873\n01:12:40.819 --> 01:12:42.613 align:middle line:100%,end position:50%,middle\n那我得买一大堆\n\n874\n01:12:42.779 --> 01:12:47.409 align:middle line:100%,end position:50%,middle\n说起大象 附近有头大象逃出来了\n\n875\n01:12:47.743 --> 01:12:49.077 align:middle line:100%,end position:50%,middle\n原来属于一个游乐团\n\n876\n01:12:49.244 --> 01:12:52.873 align:middle line:100%,end position:50%,middle\n听说它喜怒无常 非常暴躁\n\n877\n01:12:53.040 --> 01:12:55.125 align:middle line:100%,end position:50%,middle\n那她就更喜欢了\n\n878\n01:12:55.292 --> 01:12:58.253 align:middle line:100%,end position:50%,middle\n你怎么这么聪明？\n一定吃了不少苦吧\n\n879\n01:12:58.420 --> 01:12:59.630 align:middle line:100%,end position:50%,middle\n别转移话题\n\n880\n01:13:00.380 --> 01:13:04.510 align:middle line:100%,end position:50%,middle\n我到底什么时候才能不难过？\n\n881\n01:13:04.676 --> 01:13:07.012 align:middle line:100%,end position:50%,middle\n要我给你个日期圈在日历上？\n\n882\n01:13:07.179 --> 01:13:10.098 align:middle line:100%,end position:50%,middle\n- 能给我一个吗？\n- 不能 你得自己下功夫\n\n883\n01:13:10.265 --> 01:13:12.935 align:middle line:100%,end position:50%,middle\n冥想 做<i>塞瓦</i>\n\n884\n01:13:13.101 --> 01:13:16.313 align:middle line:100%,end position:50%,middle\n最重要的是每天早上\n乖乖去唱诵《古鲁吉塔》\n\n885\n01:13:16.480 --> 01:13:17.773 align:middle line:100%,end position:50%,middle\n事情就会有所改变\n\n886\n01:13:17.940 --> 01:13:21.944 align:middle line:100%,end position:50%,middle\n可<i>《古鲁吉塔》</i>我就是念不下去\n找不到虔诚奉献的感觉\n\n887\n01:13:22.110 --> 01:13:26.198 align:middle line:100%,end position:50%,middle\n奉献就是爱\n找个人或一件事 把爱献给它\n\n888\n01:13:26.365 --> 01:13:29.618 align:middle line:100%,end position:50%,middle\n不一定非得是导师 她都一样看待\n\n889\n01:13:29.785 --> 01:13:31.995 align:middle line:100%,end position:50%,middle\n这关乎你自己\n\n890\n01:13:33.539 --> 01:13:38.293 align:middle line:100%,end position:50%,middle\n吃货 我直说吧\n你的控制欲可真不轻\n\n891\n01:13:38.460 --> 01:13:40.295 align:middle line:100%,end position:50%,middle\n很明显吗？\n\n892\n01:13:40.462 --> 01:13:44.424 align:middle line:100%,end position:50%,middle\n好了 理查德 快从我脑子里出去\n\n893\n01:13:44.591 --> 01:13:45.634 align:middle line:100%,end position:50%,middle\n把门带上\n\n894\n01:13:48.095 --> 01:13:50.806 align:middle line:100%,end position:50%,middle\n- 就是他？\n- 就是他\n\n895\n01:13:51.306 --> 01:13:55.978 align:middle line:100%,end position:50%,middle\n- 他丑死了\n- 哪有 很可爱啊\n\n896\n01:13:56.144 --> 01:13:57.521 align:middle line:100%,end position:50%,middle\n他是射手座\n\n897\n01:13:58.146 --> 01:14:00.107 align:middle line:100%,end position:50%,middle\n在德里学计算机编程\n\n898\n01:14:00.274 --> 01:14:02.109 align:middle line:100%,end position:50%,middle\n成绩很好\n\n899\n01:14:02.276 --> 01:14:05.654 align:middle line:100%,end position:50%,middle\n家里非常非常有钱\n\n900\n01:14:06.321 --> 01:14:11.660 align:middle line:100%,end position:50%,middle\n他一定自大又专横\n\n901\n01:14:12.828 --> 01:14:14.663 align:middle line:100%,end position:50%,middle\n我的人生<i>17</i>岁就结束了\n\n902\n01:14:21.670 --> 01:14:23.547 align:middle line:100%,end position:50%,middle\n图尔西\n\n903\n01:16:59.661 --> 01:17:01.997 align:middle line:100%,end position:50%,middle\n<i>各位来宾 请欢迎</i>\n\n904\n01:17:02.164 --> 01:17:05.334 align:middle line:100%,end position:50%,middle\n莉兹和史蒂芬上场\n跳他们的第<i>1</i>支双人舞\n\n905\n01:17:17.846 --> 01:17:19.723 align:middle line:100%,end position:50%,middle\n各位亲朋好友\n\n906\n01:17:20.349 --> 01:17:21.725 align:middle line:100%,end position:50%,middle\n- 准备好了吗？\n- 准备好了\n\n907\n01:17:24.144 --> 01:17:26.188 align:middle line:100%,end position:50%,middle\n- 你真美\n- 谢谢\n\n908\n01:17:26.355 --> 01:17:28.690 align:middle line:100%,end position:50%,middle\n我娶了个大美人\n\n909\n01:17:31.068 --> 01:17:34.112 align:middle line:100%,end position:50%,middle\n- 什么情况？这不是我们的歌\n- 没错 不是\n\n910\n01:17:34.279 --> 01:17:35.864 align:middle line:100%,end position:50%,middle\n宝贝 这不是我们的歌\n\n911\n01:17:36.031 --> 01:17:38.534 align:middle line:100%,end position:50%,middle\n- 完全不是\n- 大家都看着呢\n\n912\n01:17:38.742 --> 01:17:41.995 align:middle line:100%,end position:50%,middle\n没事 我去跟他聊聊\n马上就好\n\n913\n01:17:53.382 --> 01:17:55.843 align:middle line:100%,end position:50%,middle\n- 就说我会搞定吧\n- 这样算搞定了？\n\n914\n01:18:53.942 --> 01:18:57.905 align:middle line:100%,end position:50%,middle\n我还欠你一份结婚礼物\n不知道送什么合适\n\n915\n01:19:00.449 --> 01:19:03.327 align:middle line:100%,end position:50%,middle\n我想告诉你 最近我一直\n\n916\n01:19:03.702 --> 01:19:05.829 align:middle line:100%,end position:50%,middle\n把<i>《古鲁吉塔》</i>的唱诵献给你\n\n917\n01:19:07.873 --> 01:19:11.627 align:middle line:100%,end position:50%,middle\n想象你幸福的样子\n我才坚持念下来了\n\n918\n01:19:14.630 --> 01:19:16.798 align:middle line:100%,end position:50%,middle\n我幸福时\n\n919\n01:19:16.965 --> 01:19:19.134 align:middle line:100%,end position:50%,middle\n是什么样子的？\n\n920\n01:19:22.763 --> 01:19:26.058 align:middle line:100%,end position:50%,middle\n我想象你和里朱尔\n\n921\n01:19:26.225 --> 01:19:29.228 align:middle line:100%,end position:50%,middle\n微笑着望着彼此\n\n922\n01:19:30.145 --> 01:19:32.606 align:middle line:100%,end position:50%,middle\n眼里满是爱意与温柔\n\n923\n01:19:33.398 --> 01:19:36.151 align:middle line:100%,end position:50%,middle\n感觉特别真实\n\n924\n01:19:38.570 --> 01:19:40.989 align:middle line:100%,end position:50%,middle\n莉兹 太谢谢你了\n\n925\n01:19:41.990 --> 01:19:44.952 align:middle line:100%,end position:50%,middle\n这让我也愿意相信了\n\n926\n01:20:01.301 --> 01:20:03.679 align:middle line:100%,end position:50%,middle\n在想自己的婚礼？\n\n927\n01:20:04.429 --> 01:20:06.181 align:middle line:100%,end position:50%,middle\n是啊 我也是\n\n928\n01:20:06.390 --> 01:20:10.185 align:middle line:100%,end position:50%,middle\n婚礼真奇妙\n总让人想到自己\n\n929\n01:20:11.061 --> 01:20:15.983 align:middle line:100%,end position:50%,middle\n你那次排场很大吧？\n穿着蓬蓬的白婚纱？\n\n930\n01:20:16.608 --> 01:20:22.364 align:middle line:100%,end position:50%,middle\n是啊 都是我自己安排的\n没人逼我做任何事\n\n931\n01:20:22.531 --> 01:20:24.992 align:middle line:100%,end position:50%,middle\n所以现在你原谅不了自己\n\n932\n01:20:25.158 --> 01:20:29.538 align:middle line:100%,end position:50%,middle\n其实 我在等他原谅我\n\n933\n01:20:29.705 --> 01:20:31.206 align:middle line:100%,end position:50%,middle\n让我解脱\n\n934\n01:20:31.415 --> 01:20:34.501 align:middle line:100%,end position:50%,middle\n吃货 等他原谅你\n简直是在浪费时间\n\n935\n01:20:34.668 --> 01:20:36.545 align:middle line:100%,end position:50%,middle\n原谅自己吧\n\n936\n01:20:37.838 --> 01:20:40.048 align:middle line:100%,end position:50%,middle\n没那么容易\n\n937\n01:20:41.383 --> 01:20:42.885 align:middle line:100%,end position:50%,middle\n是啊\n\n938\n01:20:58.567 --> 01:20:59.860 align:middle line:100%,end position:50%,middle\n晚安 理查德\n\n939\n01:21:00.194 --> 01:21:02.529 align:middle line:100%,end position:50%,middle\n- 跟我来\n- 我累了\n\n940\n01:21:02.905 --> 01:21:04.198 align:middle line:100%,end position:50%,middle\n快上来\n\n941\n01:21:31.183 --> 01:21:33.602 align:middle line:100%,end position:50%,middle\n这故事不好听\n\n942\n01:21:34.561 --> 01:21:36.730 align:middle line:100%,end position:50%,middle\n不过也很常见\n\n943\n01:21:37.481 --> 01:21:42.903 align:middle line:100%,end position:50%,middle\n酗酒 吸毒 毫无顾忌地出轨\n\n944\n01:21:44.696 --> 01:21:46.573 align:middle line:100%,end position:50%,middle\n只剩悔恨\n\n945\n01:21:49.201 --> 01:21:51.453 align:middle line:100%,end position:50%,middle\n无穷无尽的悔恨\n\n946\n01:21:53.789 --> 01:21:56.124 align:middle line:100%,end position:50%,middle\n我失去了一切\n\n947\n01:21:56.875 --> 01:21:59.294 align:middle line:100%,end position:50%,middle\n自尊 工作\n\n948\n01:22:00.087 --> 01:22:01.964 align:middle line:100%,end position:50%,middle\n还有家人\n\n949\n01:22:04.633 --> 01:22:06.760 align:middle line:100%,end position:50%,middle\n我失去了家人\n\n950\n01:22:18.647 --> 01:22:23.151 align:middle line:100%,end position:50%,middle\n有天下班后 我去了酒吧\n喝得烂醉\n\n951\n01:22:23.819 --> 01:22:26.238 align:middle line:100%,end position:50%,middle\n我以前跟你很像\n\n952\n01:22:26.405 --> 01:22:29.992 align:middle line:100%,end position:50%,middle\n就是...我也说不好\n想得太多 感受太...\n\n953\n01:22:31.535 --> 01:22:34.037 align:middle line:100%,end position:50%,middle\n我只想什么都感觉不到\n\n954\n01:22:37.124 --> 01:22:38.959 align:middle line:100%,end position:50%,middle\n本该叫出租车的 可我没有\n\n955\n01:22:39.126 --> 01:22:42.379 align:middle line:100%,end position:50%,middle\n上了车 就自己开回家\n\n956\n01:22:46.341 --> 01:22:48.260 align:middle line:100%,end position:50%,middle\n我儿子...\n\n957\n01:22:53.265 --> 01:22:56.310 align:middle line:100%,end position:50%,middle\n当时他才<i>8</i>岁 他在玩...\n\n958\n01:23:00.981 --> 01:23:05.944 align:middle line:100%,end position:50%,middle\n坐在车道上 摆着风火轮小车\n等他那个迷失的\n\n959\n01:23:06.111 --> 01:23:08.530 align:middle line:100%,end position:50%,middle\n醉醺醺 又可悲的爸爸\n\n960\n01:23:09.698 --> 01:23:12.492 align:middle line:100%,end position:50%,middle\n回家陪他玩\n\n961\n01:23:14.077 --> 01:23:16.079 align:middle line:100%,end position:50%,middle\n我没看见他\n\n962\n01:23:16.997 --> 01:23:22.377 align:middle line:100%,end position:50%,middle\n我就那么冲进车道\n完全没看见我儿子\n\n963\n01:23:23.837 --> 01:23:26.465 align:middle line:100%,end position:50%,middle\n可他...不 他...\n\n964\n01:23:27.883 --> 01:23:30.010 align:middle line:100%,end position:50%,middle\n他躲开了\n\n965\n01:23:34.723 --> 01:23:37.643 align:middle line:100%,end position:50%,middle\n我在的时候 他早就习惯躲开了\n\n966\n01:23:38.977 --> 01:23:40.687 align:middle line:100%,end position:50%,middle\n而我...你知道 我...\n\n967\n01:23:40.854 --> 01:23:42.648 align:middle line:100%,end position:50%,middle\n我不知道 什么都不记得\n\n968\n01:23:42.814 --> 01:23:45.526 align:middle line:100%,end position:50%,middle\n第二天醒来 他们都走了\n\n969\n01:23:47.152 --> 01:23:52.074 align:middle line:100%,end position:50%,middle\n我妻子从窗户里 看到了这一切\n\n970\n01:23:52.908 --> 01:23:54.743 align:middle line:100%,end position:50%,middle\n她不愿意再...\n\n971\n01:23:56.578 --> 01:23:59.122 align:middle line:100%,end position:50%,middle\n她再也不愿过这种日子了\n\n972\n01:24:00.249 --> 01:24:01.917 align:middle line:100%,end position:50%,middle\n所以...\n\n973\n01:24:06.588 --> 01:24:08.340 align:middle line:100%,end position:50%,middle\n他现在<i>18</i>岁了\n\n974\n01:24:08.507 --> 01:24:12.135 align:middle line:100%,end position:50%,middle\n在上学 天哪 他可聪明了\n\n975\n01:24:17.391 --> 01:24:20.394 align:middle line:100%,end position:50%,middle\n他特别有趣 而且...\n\n976\n01:24:22.938 --> 01:24:24.940 align:middle line:100%,end position:50%,middle\n他很贴心\n\n977\n01:24:31.280 --> 01:24:33.198 align:middle line:100%,end position:50%,middle\n我全错过了\n\n978\n01:24:33.365 --> 01:24:35.242 align:middle line:100%,end position:50%,middle\n我错过了\n\n979\n01:24:37.119 --> 01:24:40.539 align:middle line:100%,end position:50%,middle\n儿子的成长 全都错过了\n\n980\n01:24:53.552 --> 01:24:55.304 align:middle line:100%,end position:50%,middle\n明白吗？\n\n981\n01:24:57.931 --> 01:24:59.474 align:middle line:100%,end position:50%,middle\n过来\n\n982\n01:25:07.482 --> 01:25:08.483 align:middle line:100%,end position:50%,middle\n听好了\n\n983\n01:25:09.318 --> 01:25:12.154 align:middle line:100%,end position:50%,middle\n你得待在这里 直到原谅自己\n\n984\n01:25:12.321 --> 01:25:14.198 align:middle line:100%,end position:50%,middle\n听见了吗？\n\n985\n01:25:15.324 --> 01:25:18.202 align:middle line:100%,end position:50%,middle\n其他的事自然会解决\n\n986\n01:25:19.494 --> 01:25:22.331 align:middle line:100%,end position:50%,middle\n你就是在这里原谅自己的吗？\n\n987\n01:25:25.667 --> 01:25:28.337 align:middle line:100%,end position:50%,middle\n伊丽莎白 我在努力\n\n988\n01:25:28.504 --> 01:25:30.714 align:middle line:100%,end position:50%,middle\n我在努力\n\n989\n01:26:19.388 --> 01:26:20.973 align:middle line:100%,end position:50%,middle\n嘿\n\n990\n01:26:23.642 --> 01:26:27.563 align:middle line:100%,end position:50%,middle\n这应该才是\n我们婚礼上原本要放的歌\n\n991\n01:27:04.016 --> 01:27:06.560 align:middle line:100%,end position:50%,middle\n史蒂芬 我确实爱过你\n\n992\n01:27:13.317 --> 01:27:15.110 align:middle line:100%,end position:50%,middle\n我知道\n\n993\n01:27:17.571 --> 01:27:20.073 align:middle line:100%,end position:50%,middle\n可我还爱着你\n\n994\n01:27:29.458 --> 01:27:31.543 align:middle line:100%,end position:50%,middle\n那就爱吧\n\n995\n01:27:37.132 --> 01:27:39.301 align:middle line:100%,end position:50%,middle\n可我想你\n\n996\n01:27:42.763 --> 01:27:45.057 align:middle line:100%,end position:50%,middle\n那就想吧\n\n997\n01:27:46.058 --> 01:27:50.395 align:middle line:100%,end position:50%,middle\n每次想到我 就送上爱和光明\n\n998\n01:27:50.562 --> 01:27:51.813 align:middle line:100%,end position:50%,middle\n然后放下\n\n999\n01:28:10.374 --> 01:28:12.960 align:middle line:100%,end position:50%,middle\n这不会永远持续下去\n\n1000\n01:28:14.628 --> 01:28:16.755 align:middle line:100%,end position:50%,middle\n没有什么会永远持续\n\n1001\n01:28:36.066 --> 01:28:38.151 align:middle line:100%,end position:50%,middle\n- 再见\n- 再见 理查德先生\n\n1002\n01:28:38.318 --> 01:28:40.195 align:middle line:100%,end position:50%,middle\n回头见\n\n1003\n01:28:41.071 --> 01:28:44.533 align:middle line:100%,end position:50%,middle\n你走了以后 谁每天教训我啊？\n\n1004\n01:28:44.700 --> 01:28:48.537 align:middle line:100%,end position:50%,middle\n要是可以 我真想待到季风\n把我卷走那天 再见\n\n1005\n01:28:48.704 --> 01:28:50.956 align:middle line:100%,end position:50%,middle\n可你还得付账单 还得盖房子\n\n1006\n01:28:51.123 --> 01:28:54.209 align:middle line:100%,end position:50%,middle\n继续下功夫 好好过你的人生\n知道吗？\n\n1007\n01:28:54.376 --> 01:28:57.045 align:middle line:100%,end position:50%,middle\n都要上飞机了 还在指挥我\n\n1008\n01:28:57.212 --> 01:29:02.676 align:middle line:100%,end position:50%,middle\n你开的单子我都记着\n往前走 用驱蚊水 还有...\n\n1009\n01:29:02.843 --> 01:29:06.013 align:middle line:100%,end position:50%,middle\n还有什么来着 我都写下来了\n\n1010\n01:29:10.642 --> 01:29:13.353 align:middle line:100%,end position:50%,middle\n回得州去吧 理查德\n\n1011\n01:29:22.321 --> 01:29:25.240 align:middle line:100%,end position:50%,middle\n再站下去 我也不会变好看\n\n1012\n01:29:27.659 --> 01:29:28.869 align:middle line:100%,end position:50%,middle\n那我走了\n\n1013\n01:29:38.921 --> 01:29:40.881 align:middle line:100%,end position:50%,middle\n吃货\n\n1014\n01:29:41.381 --> 01:29:42.591 align:middle line:100%,end position:50%,middle\n重新相信爱情吧\n\n1015\n01:30:06.490 --> 01:30:08.951 align:middle line:100%,end position:50%,middle\n莉兹 我今天刚把徽章摘了\n\n1016\n01:30:09.117 --> 01:30:12.120 align:middle line:100%,end position:50%,middle\n我真厉害 禁语坚持了<i>4</i>周\n无聊死了\n\n1017\n01:30:12.287 --> 01:30:14.665 align:middle line:100%,end position:50%,middle\n不过像做了拉皮 因为脸部\n\n1018\n01:30:14.831 --> 01:30:19.545 align:middle line:100%,end position:50%,middle\n完全放松 喉咙也舒展开了\n简直赚到了\n\n1019\n01:30:19.711 --> 01:30:21.296 align:middle line:100%,end position:50%,middle\n我们可有太多话要聊了\n\n1020\n01:30:24.550 --> 01:30:30.097 align:middle line:100%,end position:50%,middle\n天哪 真不错\n你一定会收获很多\n\n1021\n01:30:30.639 --> 01:30:34.101 align:middle line:100%,end position:50%,middle\n脖子也会变得很好看\n\n1022\n01:30:38.063 --> 01:30:39.273 align:middle line:100%,end position:50%,middle\n打扰一下 伊丽莎白\n\n1023\n01:30:39.439 --> 01:30:42.317 align:middle line:100%,end position:50%,middle\n晚饭后 请你去一趟<i>塞瓦</i>办公室\n\n1024\n01:30:42.526 --> 01:30:43.819 align:middle line:100%,end position:50%,middle\n如果你方便的话\n\n1025\n01:30:44.444 --> 01:30:46.822 align:middle line:100%,end position:50%,middle\n你不用再刷地板了\n\n1026\n01:30:47.030 --> 01:30:50.492 align:middle line:100%,end position:50%,middle\n明天有大约<i>50</i>名修行者\n从世界各地赶来\n\n1027\n01:30:50.659 --> 01:30:54.162 align:middle line:100%,end position:50%,middle\n参加为期<i>10</i>天的闭修\n我们想请你负责接待\n\n1028\n01:30:54.663 --> 01:30:57.833 align:middle line:100%,end position:50%,middle\n冥想时 请你不要参加\n\n1029\n01:30:58.041 --> 01:31:02.838 align:middle line:100%,end position:50%,middle\n需要你照看大家\n确保每个人都没事\n\n1030\n01:31:03.172 --> 01:31:07.134 align:middle line:100%,end position:50%,middle\n做这份工作的人\n我们叫她“奶油奶酪小苏西”\n\n1031\n01:31:07.634 --> 01:31:11.847 align:middle line:100%,end position:50%,middle\n你得善于交际 活泼热情\n一直面带微笑\n\n1032\n01:31:15.350 --> 01:31:17.186 align:middle line:100%,end position:50%,middle\n女士\n\n1033\n01:31:17.644 --> 01:31:19.688 align:middle line:100%,end position:50%,middle\n这活儿就交给我吧\n\n1034\n01:31:34.870 --> 01:31:37.706 align:middle line:100%,end position:50%,middle\n找到自己的行李 应该就在这儿\n\n1035\n01:31:37.873 --> 01:31:40.083 align:middle line:100%,end position:50%,middle\n然后沿小路走去房间\n\n1036\n01:31:41.126 --> 01:31:46.590 align:middle line:100%,end position:50%,middle\n<i>这趟印度之旅的神圣真谛\n其实就1句话</i>\n\n1037\n01:31:46.965 --> 01:31:50.469 align:middle line:100%,end position:50%,middle\n<i>神以你的样子 存在于你心中</i>\n\n1038\n01:31:50.636 --> 01:31:52.888 align:middle line:100%,end position:50%,middle\n<i>神不想看你表演</i>\n\n1039\n01:31:53.096 --> 01:31:55.390 align:middle line:100%,end position:50%,middle\n<i>一个灵性之人该有的言行举止</i>\n\n1040\n01:31:55.557 --> 01:31:58.477 align:middle line:100%,end position:50%,middle\n<i>那个安安静静飘过这里的女孩</i>\n\n1041\n01:31:58.644 --> 01:32:02.481 align:middle line:100%,end position:50%,middle\n<i>面带温柔空灵的微笑 她是谁？</i>\n\n1042\n01:32:02.648 --> 01:32:06.902 align:middle line:100%,end position:50%,middle\n<i>那是</i>《圣玛丽的钟声》<i>里的\n英格丽·褒曼 不是我</i>\n\n1043\n01:32:07.110 --> 01:32:11.406 align:middle line:100%,end position:50%,middle\n<i>神以我的样子 存在于我心中</i>\n\n1044\n01:33:20.684 --> 01:33:22.978 align:middle line:100%,end position:50%,middle\n孩子被恶魔缠上了\n\n1045\n01:33:29.985 --> 01:33:31.737 align:middle line:100%,end position:50%,middle\n看着像是在长牙\n\n1046\n01:33:31.904 --> 01:33:33.822 align:middle line:100%,end position:50%,middle\n一回事\n\n1047\n01:33:37.201 --> 01:33:38.827 align:middle line:100%,end position:50%,middle\n到你了\n\n1048\n01:33:44.708 --> 01:33:46.001 align:middle line:100%,end position:50%,middle\n你好 凯图\n\n1049\n01:33:46.793 --> 01:33:48.295 align:middle line:100%,end position:50%,middle\n很高兴认识你\n\n1050\n01:33:49.713 --> 01:33:51.340 align:middle line:100%,end position:50%,middle\n你是个周游世界的人\n\n1051\n01:33:52.424 --> 01:33:54.676 align:middle line:100%,end position:50%,middle\n不是 大约<i>1</i>年前我来见过你\n\n1052\n01:33:55.344 --> 01:33:58.680 align:middle line:100%,end position:50%,middle\n- 你是加州来的姑娘？\n- 不 我是纽约来的\n\n1053\n01:33:59.848 --> 01:34:01.183 align:middle line:100%,end position:50%,middle\n不记得了\n\n1054\n01:34:04.937 --> 01:34:07.189 align:middle line:100%,end position:50%,middle\n你说我应该再回巴厘岛来\n\n1055\n01:34:07.356 --> 01:34:09.483 align:middle line:100%,end position:50%,middle\n我可以帮你练英语\n\n1056\n01:34:09.650 --> 01:34:12.027 align:middle line:100%,end position:50%,middle\n你会把自己知道的教给我\n\n1057\n01:34:15.614 --> 01:34:17.366 align:middle line:100%,end position:50%,middle\n你送过我这个\n\n1058\n01:34:18.242 --> 01:34:20.035 align:middle line:100%,end position:50%,middle\n好吧\n\n1059\n01:34:25.374 --> 01:34:28.544 align:middle line:100%,end position:50%,middle\n你 是你 我想起你了\n\n1060\n01:34:28.710 --> 01:34:30.879 align:middle line:100%,end position:50%,middle\n- 太好了\n- 纽约来的伤心姑娘\n\n1061\n01:34:31.046 --> 01:34:33.674 align:middle line:100%,end position:50%,middle\n- 对\n- 你是莉兹 你回来了\n\n1062\n01:34:33.841 --> 01:34:35.884 align:middle line:100%,end position:50%,middle\n- 我回来了\n- 你 你 你\n\n1063\n01:34:36.051 --> 01:34:37.177 align:middle line:100%,end position:50%,middle\n我 我 我\n\n1064\n01:34:37.469 --> 01:34:39.388 align:middle line:100%,end position:50%,middle\n我们上次见面是好久以前了\n\n1065\n01:34:39.555 --> 01:34:44.726 align:middle line:100%,end position:50%,middle\n上次你忧愁太多 烦恼太多\n\n1066\n01:34:44.893 --> 01:34:47.855 align:middle line:100%,end position:50%,middle\n看着像个伤心的老太婆\n\n1067\n01:34:48.981 --> 01:34:51.650 align:middle line:100%,end position:50%,middle\n现在漂亮了\n\n1068\n01:34:51.817 --> 01:34:54.319 align:middle line:100%,end position:50%,middle\n- 怎么差这么多？\n- 这个\n\n1069\n01:34:54.486 --> 01:34:56.738 align:middle line:100%,end position:50%,middle\n原因很多 真的\n\n1070\n01:34:56.905 --> 01:34:59.741 align:middle line:100%,end position:50%,middle\n我在罗马待了<i>4</i>个月\n就是好好吃东西\n\n1071\n01:34:59.908 --> 01:35:02.369 align:middle line:100%,end position:50%,middle\n然后去了印度的修行院\n\n1072\n01:35:02.536 --> 01:35:04.913 align:middle line:100%,end position:50%,middle\n现在 把两者合在一起\n\n1073\n01:35:05.080 --> 01:35:06.582 align:middle line:100%,end position:50%,middle\n正是 所以我才来这里\n\n1074\n01:35:06.748 --> 01:35:09.084 align:middle line:100%,end position:50%,middle\n- 凯图最擅长这个\n- 你给他什么了？\n\n1075\n01:35:12.588 --> 01:35:15.090 align:middle line:100%,end position:50%,middle\n还要我帮你练英语吗？\n\n1076\n01:35:15.257 --> 01:35:17.384 align:middle line:100%,end position:50%,middle\n英语晚点再说 莉兹\n\n1077\n01:35:17.551 --> 01:35:20.762 align:middle line:100%,end position:50%,middle\n先做件更好的事\n\n1078\n01:35:25.225 --> 01:35:27.269 align:middle line:100%,end position:50%,middle\n这些有多少年了？\n\n1079\n01:35:27.436 --> 01:35:30.105 align:middle line:100%,end position:50%,middle\n祖父传下来的 都是重要的咒语\n\n1080\n01:35:30.272 --> 01:35:32.774 align:middle line:100%,end position:50%,middle\n还有真言和药方\n\n1081\n01:35:32.941 --> 01:35:35.194 align:middle line:100%,end position:50%,middle\n积累了<i>1000</i>年\n\n1082\n01:35:35.360 --> 01:35:38.906 align:middle line:100%,end position:50%,middle\n我的一切 我知道的 全在这里\n\n1083\n01:35:39.072 --> 01:35:40.240 align:middle line:100%,end position:50%,middle\n帮我抄下来好吗？\n\n1084\n01:35:40.407 --> 01:35:42.451 align:middle line:100%,end position:50%,middle\n当然 我可以拿去镇上...\n\n1085\n01:35:42.618 --> 01:35:44.453 align:middle line:100%,end position:50%,middle\n不 不能拿走\n\n1086\n01:35:47.706 --> 01:35:50.125 align:middle line:100%,end position:50%,middle\n在这里抄更好 莉兹\n\n1087\n01:35:50.292 --> 01:35:52.836 align:middle line:100%,end position:50%,middle\n我要睡个午觉 太老了\n\n1088\n01:35:54.963 --> 01:35:56.298 align:middle line:100%,end position:50%,middle\n凯图 你到底多大了？\n\n1089\n01:35:56.465 --> 01:35:58.091 align:middle line:100%,end position:50%,middle\n<i>101</i>岁\n\n1090\n01:35:58.258 --> 01:36:01.470 align:middle line:100%,end position:50%,middle\n或者<i>64</i>岁吧\n\n1091\n01:36:01.637 --> 01:36:03.972 align:middle line:100%,end position:50%,middle\n不记得了\n\n1092\n01:36:11.980 --> 01:36:14.149 align:middle line:100%,end position:50%,middle\n我这辈子都要耗在这里了\n\n1093\n01:36:14.316 --> 01:36:17.986 align:middle line:100%,end position:50%,middle\n他让你漂亮 帮你找丈夫\n你得为他好好干活\n\n1094\n01:36:18.153 --> 01:36:20.280 align:middle line:100%,end position:50%,middle\n这跟我来这里的目的完全相反\n\n1095\n01:36:20.447 --> 01:36:22.866 align:middle line:100%,end position:50%,middle\n每个人都需要丈夫\n\n1096\n01:36:28.872 --> 01:36:30.499 align:middle line:100%,end position:50%,middle\n能帮我拿点水吗？\n\n1097\n01:36:30.666 --> 01:36:32.167 align:middle line:100%,end position:50%,middle\n不行\n\n1098\n01:36:32.376 --> 01:36:37.005 align:middle line:100%,end position:50%,middle\n好吧 继续抄 我去拿水\n\n1099\n01:36:50.853 --> 01:36:54.189 align:middle line:100%,end position:50%,middle\n莉兹 巴厘岛人认为\n这里是宇宙的中心\n\n1100\n01:36:54.356 --> 01:36:56.024 align:middle line:100%,end position:50%,middle\n我们现在就在巴厘岛的中心\n\n1101\n01:36:56.191 --> 01:36:58.527 align:middle line:100%,end position:50%,middle\n<i>1</i>间卧室 还有你的鱼池\n\n1102\n01:36:58.694 --> 01:37:00.404 align:middle line:100%,end position:50%,middle\n还有专属的冥想神庙\n\n1103\n01:37:00.696 --> 01:37:03.323 align:middle line:100%,end position:50%,middle\n爆炸案之后 游客少了很多\n\n1104\n01:37:03.490 --> 01:37:06.952 align:middle line:100%,end position:50%,middle\n所以现在这地方\n可以给你非常优惠的价格\n\n1105\n01:37:07.119 --> 01:37:09.037 align:middle line:100%,end position:50%,middle\n人间天堂\n\n1106\n01:37:11.790 --> 01:37:14.001 align:middle line:100%,end position:50%,middle\n- 我租了\n- 巴厘岛人懂得\n\n1107\n01:37:14.168 --> 01:37:17.212 align:middle line:100%,end position:50%,middle\n想要保持快乐 就要知道自己身在何处\n\n1108\n01:37:17.421 --> 01:37:18.881 align:middle line:100%,end position:50%,middle\n每时每刻都知道\n\n1109\n01:37:19.047 --> 01:37:23.677 align:middle line:100%,end position:50%,middle\n这里就是完美的平衡\n在天与地的交汇之处\n\n1110\n01:37:24.887 --> 01:37:27.639 align:middle line:100%,end position:50%,middle\n不要过于沉迷神 也别过于自我\n\n1111\n01:37:27.806 --> 01:37:30.893 align:middle line:100%,end position:50%,middle\n不然生活就太疯狂了\n\n1112\n01:37:31.059 --> 01:37:34.521 align:middle line:100%,end position:50%,middle\n失去平衡 就失去力量\n\n1113\n01:37:34.688 --> 01:37:38.066 align:middle line:100%,end position:50%,middle\n早上 做你在印度学的冥想\n\n1114\n01:37:38.567 --> 01:37:40.569 align:middle line:100%,end position:50%,middle\n<i>认真 非常认真</i>\n\n1115\n01:37:40.736 --> 01:37:42.863 align:middle line:100%,end position:50%,middle\n白天就好好享受巴厘岛\n\n1116\n01:37:52.748 --> 01:37:55.751 align:middle line:100%,end position:50%,middle\n下午来找我\n\n1117\n01:38:02.966 --> 01:38:05.719 align:middle line:100%,end position:50%,middle\n一天结束时 做一种新的冥想\n\n1118\n01:38:05.886 --> 01:38:06.929 align:middle line:100%,end position:50%,middle\n很简单\n\n1119\n01:38:07.095 --> 01:38:10.766 align:middle line:100%,end position:50%,middle\n静静坐着 微笑\n\n1120\n01:38:12.017 --> 01:38:13.393 align:middle line:100%,end position:50%,middle\n我已经觉得很平衡了\n\n1121\n01:38:13.560 --> 01:38:14.937 align:middle line:100%,end position:50%,middle\n没那么容易 莉兹\n\n1122\n01:38:15.103 --> 01:38:19.775 align:middle line:100%,end position:50%,middle\n用脸微笑 用心微笑\n\n1123\n01:38:19.983 --> 01:38:22.986 align:middle line:100%,end position:50%,middle\n连肝脏都要微笑\n\n1124\n01:38:24.905 --> 01:38:27.282 align:middle line:100%,end position:50%,middle\n回头见 小鳄鱼\n\n1125\n01:39:40.189 --> 01:39:41.815 align:middle line:100%,end position:50%,middle\n天哪\n\n1126\n01:39:41.982 --> 01:39:44.193 align:middle line:100%,end position:50%,middle\n- 你没事吧？\n- 你瞎了吗？\n\n1127\n01:39:44.359 --> 01:39:49.198 align:middle line:100%,end position:50%,middle\n- 我带你去看医生吧\n- 我没事 只是...\n\n1128\n01:39:52.868 --> 01:39:54.536 align:middle line:100%,end position:50%,middle\n看着很严重\n\n1129\n01:39:54.703 --> 01:39:56.371 align:middle line:100%,end position:50%,middle\n很严重 莉兹\n\n1130\n01:39:56.580 --> 01:39:59.708 align:middle line:100%,end position:50%,middle\n- 怎么回事？\n- 一个白痴把我挤出路面了\n\n1131\n01:39:59.917 --> 01:40:01.710 align:middle line:100%,end position:50%,middle\n男人？有钱吗？\n\n1132\n01:40:03.045 --> 01:40:04.505 align:middle line:100%,end position:50%,middle\n这里很烫\n\n1133\n01:40:05.005 --> 01:40:08.050 align:middle line:100%,end position:50%,middle\n- 你得找个治疗师\n- 不是有你吗？你不就是医师\n\n1134\n01:40:08.217 --> 01:40:11.845 align:middle line:100%,end position:50%,middle\n- 不 你得找瓦杨\n- 好吧\n\n1135\n01:40:21.772 --> 01:40:25.400 align:middle line:100%,end position:50%,middle\n佳穆 喝了它 比抗生素好\n\n1136\n01:40:31.740 --> 01:40:33.700 align:middle line:100%,end position:50%,middle\n她也让你喝这个了？\n\n1137\n01:40:33.867 --> 01:40:35.911 align:middle line:100%,end position:50%,middle\n- 我叫莉兹 你呢？\n- 图蒂\n\n1138\n01:40:36.119 --> 01:40:38.247 align:middle line:100%,end position:50%,middle\n很高兴认识你 图蒂\n\n1139\n01:40:38.413 --> 01:40:41.250 align:middle line:100%,end position:50%,middle\n- 你结婚了吗？\n- 没有\n\n1140\n01:40:47.256 --> 01:40:49.132 align:middle line:100%,end position:50%,middle\n确定？连<i>1</i>次都没有？\n\n1141\n01:40:49.591 --> 01:40:51.510 align:middle line:100%,end position:50%,middle\n好吧 是结过<i>1</i>次\n\n1142\n01:40:51.677 --> 01:40:55.556 align:middle line:100%,end position:50%,middle\n可我发现跟巴厘岛人说离过婚\n总让他们不高兴\n\n1143\n01:40:55.722 --> 01:40:57.933 align:middle line:100%,end position:50%,middle\n我也离婚了\n\n1144\n01:40:58.141 --> 01:41:02.271 align:middle line:100%,end position:50%,middle\n离婚让人伤心 还会被人排斥\n\n1145\n01:41:04.398 --> 01:41:07.276 align:middle line:100%,end position:50%,middle\n宝贝 你很久没做爱了\n\n1146\n01:41:07.442 --> 01:41:08.944 align:middle line:100%,end position:50%,middle\n从膝盖就看得出来\n\n1147\n01:41:09.152 --> 01:41:13.115 align:middle line:100%,end position:50%,middle\n软骨很干 性爱产生的激素\n能润滑关节\n\n1148\n01:41:13.282 --> 01:41:15.075 align:middle line:100%,end position:50%,middle\n- 好吧\n- 我会为你祈祷\n\n1149\n01:41:15.242 --> 01:41:17.870 align:middle line:100%,end position:50%,middle\n我们是姐妹\n\n1150\n01:41:18.328 --> 01:41:20.747 align:middle line:100%,end position:50%,middle\n阿梅尼娅！\n\n1151\n01:41:23.166 --> 01:41:24.793 align:middle line:100%,end position:50%,middle\n阿梅尼娅 从巴西来的\n\n1152\n01:41:24.960 --> 01:41:26.753 align:middle line:100%,end position:50%,middle\n这是纽约来的莉兹\n\n1153\n01:41:26.920 --> 01:41:29.131 align:middle line:100%,end position:50%,middle\n- 你好\n- 莉兹 很高兴认识你\n\n1154\n01:41:29.298 --> 01:41:31.049 align:middle line:100%,end position:50%,middle\n该做香蕉根护发了？\n\n1155\n01:41:31.216 --> 01:41:34.303 align:middle line:100%,end position:50%,middle\n- 当然\n- 能让头发又长又亮\n\n1156\n01:41:34.469 --> 01:41:38.640 align:middle line:100%,end position:50%,middle\n就像<i>1975</i>年左右的雪儿\n\n1157\n01:41:39.766 --> 01:41:41.435 align:middle line:100%,end position:50%,middle\n你有漂亮裙子吗？\n\n1158\n01:41:41.810 --> 01:41:42.811 align:middle line:100%,end position:50%,middle\n<i>1</i>条\n\n1159\n01:41:42.978 --> 01:41:44.980 align:middle line:100%,end position:50%,middle\n今晚穿上 来海滩小屋\n\n1160\n01:41:45.189 --> 01:41:48.066 align:middle line:100%,end position:50%,middle\n我给你介绍大家\n旅居者和本地人\n\n1161\n01:41:48.233 --> 01:41:50.152 align:middle line:100%,end position:50%,middle\n跳跳舞 你一定喜欢\n\n1162\n01:41:50.319 --> 01:41:52.946 align:middle line:100%,end position:50%,middle\n我的腿这样 恐怕跳不了\n\n1163\n01:41:53.113 --> 01:41:55.782 align:middle line:100%,end position:50%,middle\n当然可以 腿没问题\n\n1164\n01:41:56.158 --> 01:41:57.951 align:middle line:100%,end position:50%,middle\n你看\n\n1165\n01:41:58.577 --> 01:42:00.704 align:middle line:100%,end position:50%,middle\n这下必须来了\n\n1166\n01:42:53.382 --> 01:42:57.010 align:middle line:100%,end position:50%,middle\n来杯龙舌兰加冰 多放青柠 谢谢\n\n1167\n01:42:57.177 --> 01:42:58.887 align:middle line:100%,end position:50%,middle\n马上就好\n\n1168\n01:43:04.518 --> 01:43:06.019 align:middle line:100%,end position:50%,middle\n能请你喝一杯吗？\n\n1169\n01:43:06.186 --> 01:43:07.729 align:middle line:100%,end position:50%,middle\n不了 谢谢 我不用\n\n1170\n01:43:07.896 --> 01:43:09.898 align:middle line:100%,end position:50%,middle\n我...差点害死你\n\n1171\n01:43:10.065 --> 01:43:13.068 align:middle line:100%,end position:50%,middle\n真的很对不起\n\n1172\n01:43:14.027 --> 01:43:16.405 align:middle line:100%,end position:50%,middle\n- 你好\n- 你好\n\n1173\n01:43:16.572 --> 01:43:18.824 align:middle line:100%,end position:50%,middle\n真的很抱歉\n\n1174\n01:43:20.909 --> 01:43:22.411 align:middle line:100%,end position:50%,middle\n嗯\n\n1175\n01:43:33.130 --> 01:43:35.591 align:middle line:100%,end position:50%,middle\n抱歉 我忍不住笑 太巧了\n\n1176\n01:43:35.799 --> 01:43:39.428 align:middle line:100%,end position:50%,middle\n当时车里就放着这首歌\n结果磁带卡了\n\n1177\n01:43:39.595 --> 01:43:42.931 align:middle line:100%,end position:50%,middle\n我探身去弄 就把你挤出路面了\n\n1178\n01:43:43.682 --> 01:43:47.895 align:middle line:100%,end position:50%,middle\n- 你让他们放的？\n- 没有 我帮他们录混音带\n\n1179\n01:43:48.103 --> 01:43:49.188 align:middle line:100%,end position:50%,middle\n主要是巴西音乐\n\n1180\n01:43:49.354 --> 01:43:53.609 align:middle line:100%,end position:50%,middle\n不过我也很爱菲尔·柯林斯\n和空中补给乐队\n\n1181\n01:43:54.568 --> 01:43:57.946 align:middle line:100%,end position:50%,middle\n这种话 还是别大声说出来了\n\n1182\n01:44:00.490 --> 01:44:01.533 align:middle line:100%,end position:50%,middle\n莉兹！\n\n1183\n01:44:02.326 --> 01:44:05.913 align:middle line:100%,end position:50%,middle\n- 嗨\n- 你已经认识费利佩了\n\n1184\n01:44:07.623 --> 01:44:11.960 align:middle line:100%,end position:50%,middle\n对啊 都伤心地离过婚\n共同点可多了\n\n1185\n01:44:15.547 --> 01:44:18.133 align:middle line:100%,end position:50%,middle\n我有个男人特别适合你\n\n1186\n01:44:18.717 --> 01:44:22.137 align:middle line:100%,end position:50%,middle\n就来段小艳遇嘛\n来巴厘岛谁不来段艳遇\n\n1187\n01:44:24.765 --> 01:44:26.350 align:middle line:100%,end position:50%,middle\n他多迷人啊 伊恩\n\n1188\n01:44:27.226 --> 01:44:28.477 align:middle line:100%,end position:50%,middle\n像不像斯汀？\n\n1189\n01:44:28.644 --> 01:44:31.146 align:middle line:100%,end position:50%,middle\n是啊 我还录过一盘很棒的斯汀歌带\n\n1190\n01:44:37.653 --> 01:44:39.613 align:middle line:100%,end position:50%,middle\n你该跟他跳舞\n\n1191\n01:45:25.617 --> 01:45:27.160 align:middle line:100%,end position:50%,middle\n接住你了 来 我接住你了\n\n1192\n01:45:27.327 --> 01:45:29.705 align:middle line:100%,end position:50%,middle\n明天肯定会疼\n\n1193\n01:45:29.872 --> 01:45:32.374 align:middle line:100%,end position:50%,middle\n好吧 知道吗？\n\n1194\n01:45:32.541 --> 01:45:37.171 align:middle line:100%,end position:50%,middle\n- 走 咱们去游泳\n- 可我连...我...\n\n1195\n01:45:37.337 --> 01:45:40.340 align:middle line:100%,end position:50%,middle\n你没带...没带...\n\n1196\n01:45:41.508 --> 01:45:42.718 align:middle line:100%,end position:50%,middle\n你都脱光了\n\n1197\n01:45:42.926 --> 01:45:45.721 align:middle line:100%,end position:50%,middle\n对啊 我脱光了\n\n1198\n01:45:46.054 --> 01:45:48.515 align:middle line:100%,end position:50%,middle\n阿梅尼娅说 人人都该来段艳遇\n\n1199\n01:45:48.682 --> 01:45:52.144 align:middle line:100%,end position:50%,middle\n这里是巴厘岛\n谁来巴厘岛都该有段艳遇\n\n1200\n01:45:52.311 --> 01:45:53.729 align:middle line:100%,end position:50%,middle\n是啊 可是...\n\n1201\n01:45:53.896 --> 01:45:55.898 align:middle line:100%,end position:50%,middle\n天哪 不 不 不\n\n1202\n01:45:56.064 --> 01:45:58.442 align:middle line:100%,end position:50%,middle\n- 艳遇很棒的 哥们儿\n- 是很棒 我只是...\n\n1203\n01:45:58.609 --> 01:46:00.235 align:middle line:100%,end position:50%,middle\n<i>15</i>年前 我就跟你这种人交往过\n\n1204\n01:46:00.444 --> 01:46:04.531 align:middle line:100%,end position:50%,middle\n<i>6</i>个月前 又交往过一次\n\n1205\n01:46:04.698 --> 01:46:06.575 align:middle line:100%,end position:50%,middle\n所以我得走了\n\n1206\n01:46:06.742 --> 01:46:08.744 align:middle line:100%,end position:50%,middle\n你不会...你真的...\n你要走啊\n\n1207\n01:46:08.911 --> 01:46:10.746 align:middle line:100%,end position:50%,middle\n不过你很可爱\n\n1208\n01:46:13.582 --> 01:46:15.083 align:middle line:100%,end position:50%,middle\n我也觉得自己挺好看\n\n1209\n01:46:18.086 --> 01:46:19.129 align:middle line:100%,end position:50%,middle\n等等\n\n1210\n01:46:19.296 --> 01:46:20.881 align:middle line:100%,end position:50%,middle\n抱歉 给你\n\n1211\n01:46:22.758 --> 01:46:24.426 align:middle line:100%,end position:50%,middle\n- 谢谢\n- 需要搭车吗？\n\n1212\n01:46:25.844 --> 01:46:27.763 align:middle line:100%,end position:50%,middle\n这样我就不会再撞你了\n\n1213\n01:46:37.564 --> 01:46:39.691 align:middle line:100%,end position:50%,middle\n你好\n\n1214\n01:46:39.858 --> 01:46:42.694 align:middle line:100%,end position:50%,middle\n- 几点了？\n- 凌晨<i>5</i>点\n\n1215\n01:46:43.237 --> 01:46:45.781 align:middle line:100%,end position:50%,middle\n你玩得可真疯\n\n1216\n01:46:45.948 --> 01:46:47.616 align:middle line:100%,end position:50%,middle\n真的\n\n1217\n01:46:47.783 --> 01:46:50.953 align:middle line:100%,end position:50%,middle\n谢谢你...\n\n1218\n01:46:51.119 --> 01:46:52.120 align:middle line:100%,end position:50%,middle\n- 送你回来？\n- 对\n\n1219\n01:46:52.287 --> 01:46:54.623 align:middle line:100%,end position:50%,middle\n不客气 要帮你搬自行车吗？\n\n1220\n01:46:54.790 --> 01:46:55.958 align:middle line:100%,end position:50%,middle\n你留着吧\n\n1221\n01:46:56.124 --> 01:46:58.126 align:middle line:100%,end position:50%,middle\n留着？可这上面有个篮子\n\n1222\n01:46:59.002 --> 01:47:01.004 align:middle line:100%,end position:50%,middle\n还有车铃呢\n\n1223\n01:47:20.899 --> 01:47:23.110 align:middle line:100%,end position:50%,middle\n下午好 你怎么样？\n\n1224\n01:47:23.277 --> 01:47:24.319 align:middle line:100%,end position:50%,middle\n你怎么在这儿？\n\n1225\n01:47:24.528 --> 01:47:28.490 align:middle line:100%,end position:50%,middle\n给你送来了瓦杨有名的解酒药\n\n1226\n01:47:28.657 --> 01:47:31.785 align:middle line:100%,end position:50%,middle\n因为你昨晚喝得有点多\n\n1227\n01:47:31.952 --> 01:47:35.998 align:middle line:100%,end position:50%,middle\n就是这个 看着就很美味\n\n1228\n01:47:36.164 --> 01:47:37.499 align:middle line:100%,end position:50%,middle\n味道也好\n\n1229\n01:47:37.666 --> 01:47:40.169 align:middle line:100%,end position:50%,middle\n你习惯这样随便进别人家？\n\n1230\n01:47:40.335 --> 01:47:43.297 align:middle line:100%,end position:50%,middle\n那你习惯敞着大门睡觉？\n\n1231\n01:47:48.260 --> 01:47:49.803 align:middle line:100%,end position:50%,middle\n来电话了 等一下\n\n1232\n01:47:51.346 --> 01:47:54.516 align:middle line:100%,end position:50%,middle\n- 喂 宝贝 你好吗？\n- 咖啡机弄不动了\n\n1233\n01:47:54.683 --> 01:47:57.019 align:middle line:100%,end position:50%,middle\n教过你<i>50</i>遍了 很简单\n\n1234\n01:47:57.186 --> 01:47:59.188 align:middle line:100%,end position:50%,middle\n换滤纸 放咖啡\n\n1235\n01:47:59.354 --> 01:48:02.482 align:middle line:100%,end position:50%,middle\n加水 就行了\n你怎么考上大学的？\n\n1236\n01:48:02.649 --> 01:48:05.527 align:middle line:100%,end position:50%,middle\n- 怎么才能煮得跟你一样？\n- 听着 我煮咖啡\n\n1237\n01:48:05.694 --> 01:48:09.698 align:middle line:100%,end position:50%,middle\n已经煮了<i>40</i>年 宝贝\n所以对自己耐心点 好吗？\n\n1238\n01:48:09.865 --> 01:48:13.368 align:middle line:100%,end position:50%,middle\n<i>好吧 那你在干什么？</i>\n\n1239\n01:48:13.535 --> 01:48:16.830 align:middle line:100%,end position:50%,middle\n- 没什么 现在不方便说\n- 靠 你跟女人在一起\n\n1240\n01:48:16.997 --> 01:48:18.874 align:middle line:100%,end position:50%,middle\n- 我得挂了\n- 她是谁？漂亮吗？\n\n1241\n01:48:19.041 --> 01:48:20.876 align:middle line:100%,end position:50%,middle\n- 天哪 她很漂亮\n<i>- 爸 你敢挂</i>\n\n1242\n01:48:21.084 --> 01:48:23.337 align:middle line:100%,end position:50%,middle\n我就再打来 让你出丑\n\n1243\n01:48:23.504 --> 01:48:24.671 align:middle line:100%,end position:50%,middle\n爸 别...\n\n1244\n01:48:26.840 --> 01:48:29.218 align:middle line:100%,end position:50%,middle\n“宝贝”可真多啊 宝贝\n\n1245\n01:48:29.384 --> 01:48:30.886 align:middle line:100%,end position:50%,middle\n刚才那个“宝贝”是我儿子\n\n1246\n01:48:31.303 --> 01:48:34.389 align:middle line:100%,end position:50%,middle\n孩子从小我就都叫他们“宝贝”\n\n1247\n01:48:34.598 --> 01:48:37.559 align:middle line:100%,end position:50%,middle\n后来孩子和宠物一多\n\n1248\n01:48:37.726 --> 01:48:40.395 align:middle line:100%,end position:50%,middle\n我都搞糊涂了\n干脆全叫“宝贝”\n\n1249\n01:48:40.646 --> 01:48:42.147 align:middle line:100%,end position:50%,middle\n好了 你得休息\n\n1250\n01:48:42.314 --> 01:48:44.816 align:middle line:100%,end position:50%,middle\n这是我的号码和住址\n\n1251\n01:48:44.983 --> 01:48:49.238 align:middle line:100%,end position:50%,middle\n我放在桌上 以防你需要导游\n\n1252\n01:48:49.696 --> 01:48:51.406 align:middle line:100%,end position:50%,middle\n导游\n\n1253\n01:48:51.615 --> 01:48:55.827 align:middle line:100%,end position:50%,middle\n记得把它喝完 真能帮大忙\n\n1254\n01:48:55.994 --> 01:48:58.121 align:middle line:100%,end position:50%,middle\n因为你现在看着真是...\n\n1255\n01:48:58.705 --> 01:49:02.251 align:middle line:100%,end position:50%,middle\n- 迷人？\n- 惊人\n\n1256\n01:49:02.417 --> 01:49:05.087 align:middle line:100%,end position:50%,middle\n- 快走吧 求你了\n- 好 把它喝了\n\n1257\n01:49:05.254 --> 01:49:06.421 align:middle line:100%,end position:50%,middle\n会有帮助的\n\n1258\n01:49:14.012 --> 01:49:15.389 align:middle line:100%,end position:50%,middle\n导游先生\n\n1259\n01:49:16.640 --> 01:49:18.100 align:middle line:100%,end position:50%,middle\n能先带我喝杯咖啡吗？\n\n1260\n01:49:21.520 --> 01:49:22.938 align:middle line:100%,end position:50%,middle\n好啊\n\n1261\n01:49:23.146 --> 01:49:24.606 align:middle line:100%,end position:50%,middle\n<i>这些是什么？</i>\n\n1262\n01:49:24.773 --> 01:49:26.608 align:middle line:100%,end position:50%,middle\n红毛丹 很好吃\n\n1263\n01:49:26.775 --> 01:49:30.362 align:middle line:100%,end position:50%,middle\n像橙子和李子做爱生出来的\n要来点吗？\n\n1264\n01:49:30.529 --> 01:49:33.282 align:middle line:100%,end position:50%,middle\n听你这么说 好吧 谢谢\n\n1265\n01:49:33.949 --> 01:49:35.784 align:middle line:100%,end position:50%,middle\n不好意思\n\n1266\n01:49:37.160 --> 01:49:38.287 align:middle line:100%,end position:50%,middle\n那是什么？\n\n1267\n01:49:39.371 --> 01:49:41.248 align:middle line:100%,end position:50%,middle\n不 不 不\n\n1268\n01:49:41.415 --> 01:49:43.125 align:middle line:100%,end position:50%,middle\n吃着像臭脚丫\n\n1269\n01:49:43.292 --> 01:49:44.585 align:middle line:100%,end position:50%,middle\n- 真的？\n- 臭脚丫\n\n1270\n01:49:44.751 --> 01:49:46.295 align:middle line:100%,end position:50%,middle\n味道就像脚\n\n1271\n01:49:46.461 --> 01:49:49.631 align:middle line:100%,end position:50%,middle\n小心 不错 你去过多少地方？\n\n1272\n01:49:49.798 --> 01:49:53.969 align:middle line:100%,end position:50%,middle\n我护照上有<i>46</i>个戳\n\n1273\n01:49:54.178 --> 01:49:58.265 align:middle line:100%,end position:50%,middle\n巧了 我有<i>49</i>个\n\n1274\n01:49:58.432 --> 01:50:00.475 align:middle line:100%,end position:50%,middle\n- <i>49</i>个？我就知道\n- 对\n\n1275\n01:50:00.684 --> 01:50:02.186 align:middle line:100%,end position:50%,middle\n- 知道什么？\n- 我就知道\n\n1276\n01:50:03.562 --> 01:50:05.939 align:middle line:100%,end position:50%,middle\n亲爱的 我们都是<i>“安特瓦辛”</i>\n\n1277\n01:50:06.106 --> 01:50:07.149 align:middle line:100%,end position:50%,middle\n什么意思？\n\n1278\n01:50:07.316 --> 01:50:09.484 align:middle line:100%,end position:50%,middle\n<i>“安特瓦辛”</i>就是...\n\n1279\n01:50:10.319 --> 01:50:12.571 align:middle line:100%,end position:50%,middle\n处于两者之间的人\n\n1280\n01:50:12.738 --> 01:50:14.823 align:middle line:100%,end position:50%,middle\n住在边界上的人\n\n1281\n01:50:14.990 --> 01:50:18.410 align:middle line:100%,end position:50%,middle\n他们舍弃家庭生活的安逸\n\n1282\n01:50:18.577 --> 01:50:21.580 align:middle line:100%,end position:50%,middle\n去寻找“enlightment”\n也就是开悟\n\n1283\n01:50:21.747 --> 01:50:23.665 align:middle line:100%,end position:50%,middle\n我喜欢你选的这个词\n\n1284\n01:50:23.832 --> 01:50:25.959 align:middle line:100%,end position:50%,middle\n也喜欢你说\n“enlightment”的发音\n\n1285\n01:50:26.126 --> 01:50:27.503 align:middle line:100%,end position:50%,middle\n“Enlightment” 我尽力了\n\n1286\n01:50:27.711 --> 01:50:30.964 align:middle line:100%,end position:50%,middle\n少了<i>1</i>个音节 不过我喜欢\n\n1287\n01:50:31.715 --> 01:50:33.342 align:middle line:100%,end position:50%,middle\n很美吧？\n\n1288\n01:50:33.509 --> 01:50:37.012 align:middle line:100%,end position:50%,middle\n这是梅兰汀寺\n意思是“繁荣之寺”\n\n1289\n01:50:37.804 --> 01:50:39.515 align:middle line:100%,end position:50%,middle\n- 真美\n- 是啊\n\n1290\n01:50:40.015 --> 01:50:42.684 align:middle line:100%,end position:50%,middle\n- 该去下个景点了？\n- 对\n\n1291\n01:50:42.851 --> 01:50:44.770 align:middle line:100%,end position:50%,middle\n- 品尝巴厘岛美食\n- 太好了 我饿死了\n\n1292\n01:50:44.937 --> 01:50:47.356 align:middle line:100%,end position:50%,middle\n- 去哪儿吃？\n- 镇上最好的餐厅\n\n1293\n01:50:47.523 --> 01:50:49.858 align:middle line:100%,end position:50%,middle\n- 当然\n- 我家\n\n1294\n01:50:52.277 --> 01:50:53.654 align:middle line:100%,end position:50%,middle\n真含蓄\n\n1295\n01:50:54.530 --> 01:50:57.032 align:middle line:100%,end position:50%,middle\n来巴厘岛之前 你一直住巴西吗？\n\n1296\n01:50:57.241 --> 01:50:58.534 align:middle line:100%,end position:50%,middle\n不 只住了<i>20</i>年\n\n1297\n01:50:58.700 --> 01:51:02.955 align:middle line:100%,end position:50%,middle\n后来认识了我妻子\n就跟她搬去了澳大利亚\n\n1298\n01:51:03.121 --> 01:51:06.166 align:middle line:100%,end position:50%,middle\n她经常出差\n\n1299\n01:51:06.333 --> 01:51:09.878 align:middle line:100%,end position:50%,middle\n- 我在家带孩子\n- 支持女权的好丈夫\n\n1300\n01:51:10.045 --> 01:51:13.549 align:middle line:100%,end position:50%,middle\n是啊 可惜那不是她想要的\n\n1301\n01:51:13.757 --> 01:51:15.217 align:middle line:100%,end position:50%,middle\n- 后来呢？\n- 后来？\n\n1302\n01:51:15.384 --> 01:51:16.718 align:middle line:100%,end position:50%,middle\n孩子们都长大了\n\n1303\n01:51:16.885 --> 01:51:22.558 align:middle line:100%,end position:50%,middle\n我做珠宝进出口生意\n住在哪里都行\n\n1304\n01:51:22.766 --> 01:51:27.563 align:middle line:100%,end position:50%,middle\n觉得巴厘岛很适合\n疗愈离婚的伤痛\n\n1305\n01:51:29.690 --> 01:51:32.693 align:middle line:100%,end position:50%,middle\n所以就来了 就在这里\n\n1306\n01:51:32.860 --> 01:51:34.528 align:middle line:100%,end position:50%,middle\n- 你呢？\n- 我的没那么悲惨\n\n1307\n01:51:34.695 --> 01:51:40.242 align:middle line:100%,end position:50%,middle\n我们太年轻 太不成熟\n不该那么早结婚 后来渐行渐远\n\n1308\n01:51:40.409 --> 01:51:41.910 align:middle line:100%,end position:50%,middle\n都伤了心\n\n1309\n01:51:42.536 --> 01:51:44.413 align:middle line:100%,end position:50%,middle\n是啊\n\n1310\n01:51:44.580 --> 01:51:46.665 align:middle line:100%,end position:50%,middle\n那就一样了\n\n1311\n01:51:52.296 --> 01:51:53.714 align:middle line:100%,end position:50%,middle\n这真是完美\n\n1312\n01:51:54.298 --> 01:51:56.175 align:middle line:100%,end position:50%,middle\n你也是\n\n1313\n01:51:56.341 --> 01:51:59.219 align:middle line:100%,end position:50%,middle\n知道你是什么吗？<i>“假瘦子”</i>\n\n1314\n01:51:59.386 --> 01:52:01.263 align:middle line:100%,end position:50%,middle\n- 知道什么意思吗？\n- 什么？\n\n1315\n01:52:01.430 --> 01:52:04.933 align:middle line:100%,end position:50%,middle\n远看纤细优雅\n\n1316\n01:52:05.100 --> 01:52:08.604 align:middle line:100%,end position:50%,middle\n凑近看 却圆润有肉\n\n1317\n01:52:10.272 --> 01:52:12.316 align:middle line:100%,end position:50%,middle\n真感谢上帝创造了巴西人\n\n1318\n01:52:16.236 --> 01:52:18.113 align:middle line:100%,end position:50%,middle\n别闹！\n\n1319\n01:52:24.369 --> 01:52:26.455 align:middle line:100%,end position:50%,middle\n你是个周游世界的人\n\n1320\n01:52:26.622 --> 01:52:27.956 align:middle line:100%,end position:50%,middle\n见谁他都这么说\n\n1321\n01:52:28.916 --> 01:52:30.250 align:middle line:100%,end position:50%,middle\n你已经赚够钱了\n\n1322\n01:52:31.084 --> 01:52:34.087 align:middle line:100%,end position:50%,middle\n没有年轻人的野心了\n\n1323\n01:52:34.922 --> 01:52:39.259 align:middle line:100%,end position:50%,middle\n- 他挺准啊\n- 你有<i>3</i>个孩子\n\n1324\n01:52:39.426 --> 01:52:41.637 align:middle line:100%,end position:50%,middle\n<i>2</i>个 那是个茧\n\n1325\n01:52:44.264 --> 01:52:45.599 align:middle line:100%,end position:50%,middle\n你还离过婚\n\n1326\n01:52:46.850 --> 01:52:48.101 align:middle line:100%,end position:50%,middle\n很艰难\n\n1327\n01:52:48.268 --> 01:52:51.271 align:middle line:100%,end position:50%,middle\n你曾经很爱她\n\n1328\n01:52:52.314 --> 01:52:53.857 align:middle line:100%,end position:50%,middle\n那个伤口还没愈合\n\n1329\n01:52:54.650 --> 01:52:58.862 align:middle line:100%,end position:50%,middle\n现在你害怕敞开心扉\n\n1330\n01:52:59.821 --> 01:53:03.158 align:middle line:100%,end position:50%,middle\n怕自己再受一次伤\n\n1331\n01:53:03.867 --> 01:53:05.786 align:middle line:100%,end position:50%,middle\n想要疗伤\n\n1332\n01:53:05.953 --> 01:53:08.497 align:middle line:100%,end position:50%,middle\n唯一的办法就是信任\n\n1333\n01:53:10.374 --> 01:53:14.628 align:middle line:100%,end position:50%,middle\n没关系 心碎过\n说明你曾经为某件事努力过\n\n1334\n01:53:18.715 --> 01:53:21.844 align:middle line:100%,end position:50%,middle\n还会再碎一次吗？\n\n1335\n01:53:22.010 --> 01:53:24.179 align:middle line:100%,end position:50%,middle\n莉兹 他是个好男人\n你需要一个好男人\n\n1336\n01:53:26.682 --> 01:53:28.350 align:middle line:100%,end position:50%,middle\n谢谢\n\n1337\n01:53:28.517 --> 01:53:31.103 align:middle line:100%,end position:50%,middle\n真的 凯图知道\n\n1338\n01:53:35.440 --> 01:53:38.318 align:middle line:100%,end position:50%,middle\n我烦透了人人都说我需要男人\n\n1339\n01:53:38.485 --> 01:53:42.531 align:middle line:100%,end position:50%,middle\n你需要的不是男人 莉兹\n是一个站在你这边的人\n\n1340\n01:53:48.537 --> 01:53:51.874 align:middle line:100%,end position:50%,middle\n- 这春假可真不一般\n- 快点 像乌龟一样\n\n1341\n01:53:52.040 --> 01:53:53.709 align:middle line:100%,end position:50%,middle\n他这热情可真让人累\n\n1342\n01:53:53.876 --> 01:53:56.211 align:middle line:100%,end position:50%,middle\n你试试<i>10</i>岁时\n让爸爸送你去上学\n\n1343\n01:53:56.378 --> 01:53:58.547 align:middle line:100%,end position:50%,middle\n还当众亲你的嘴\n\n1344\n01:53:58.714 --> 01:54:00.299 align:middle line:100%,end position:50%,middle\n现在还这样\n\n1345\n01:54:00.465 --> 01:54:04.178 align:middle line:100%,end position:50%,middle\n这在巴西肯定很正常\n可我又不是在巴西长大的\n\n1346\n01:54:04.344 --> 01:54:06.138 align:middle line:100%,end position:50%,middle\n朋友们都把我笑话惨了\n\n1347\n01:54:06.305 --> 01:54:07.806 align:middle line:100%,end position:50%,middle\n怎么不叫他别亲了？\n\n1348\n01:54:07.973 --> 01:54:10.434 align:middle line:100%,end position:50%,middle\n一开始说过 后来才发现\n\n1349\n01:54:10.601 --> 01:54:13.395 align:middle line:100%,end position:50%,middle\n老头子这么做有多开心\n我就随他去了\n\n1350\n01:54:13.562 --> 01:54:18.358 align:middle line:100%,end position:50%,middle\n我奶奶爬山都比你俩快\n\n1351\n01:54:18.525 --> 01:54:20.986 align:middle line:100%,end position:50%,middle\n可她已经去世了\n\n1352\n01:54:21.153 --> 01:54:23.906 align:middle line:100%,end position:50%,middle\n去 找他去\n\n1353\n01:54:24.072 --> 01:54:27.242 align:middle line:100%,end position:50%,middle\n不如你来背会儿包吧？\n\n1354\n01:54:27.492 --> 01:54:30.037 align:middle line:100%,end position:50%,middle\n过来 看看这里\n\n1355\n01:54:30.412 --> 01:54:32.331 align:middle line:100%,end position:50%,middle\n美吧？\n\n1356\n01:54:32.873 --> 01:54:33.916 align:middle line:100%,end position:50%,middle\n宝贝\n\n1357\n01:54:34.917 --> 01:54:37.002 align:middle line:100%,end position:50%,middle\n走在最后啊\n\n1358\n01:54:46.762 --> 01:54:49.515 align:middle line:100%,end position:50%,middle\n- 跟她睡过了没？\n- 你说什么？\n\n1359\n01:54:49.681 --> 01:54:51.058 align:middle line:100%,end position:50%,middle\n跟她睡过了没？\n\n1360\n01:54:51.225 --> 01:54:52.935 align:middle line:100%,end position:50%,middle\n越界了啊\n\n1361\n01:54:53.101 --> 01:54:56.897 align:middle line:100%,end position:50%,middle\n爸 都<i>10</i>年了 是时候了\n\n1362\n01:55:09.368 --> 01:55:11.745 align:middle line:100%,end position:50%,middle\n离那些漂亮女孩远一点\n\n1363\n01:55:11.912 --> 01:55:14.289 align:middle line:100%,end position:50%,middle\n她们可危险了\n\n1364\n01:55:19.127 --> 01:55:20.879 align:middle line:100%,end position:50%,middle\n- <i>1</i>周太短了\n- 是啊\n\n1365\n01:55:21.046 --> 01:55:23.966 align:middle line:100%,end position:50%,middle\n- <i>1</i>周太短了\n- 对\n\n1366\n01:55:24.550 --> 01:55:27.928 align:middle line:100%,end position:50%,middle\n我给你录了盘混音带\n\n1367\n01:55:28.637 --> 01:55:31.139 align:middle line:100%,end position:50%,middle\n还给你准备了一份礼物 给你\n\n1368\n01:55:33.308 --> 01:55:34.518 align:middle line:100%,end position:50%,middle\n谢谢\n\n1369\n01:55:34.685 --> 01:55:37.479 align:middle line:100%,end position:50%,middle\n我已经开始想你了\n\n1370\n01:55:45.320 --> 01:55:47.072 align:middle line:100%,end position:50%,middle\n再见 莉兹\n\n1371\n01:55:49.324 --> 01:55:51.785 align:middle line:100%,end position:50%,middle\n- 注意安全\n- 你也是\n\n1372\n01:55:54.288 --> 01:55:55.831 align:middle line:100%,end position:50%,middle\n不亲一下吗？\n\n1373\n01:55:56.039 --> 01:55:57.833 align:middle line:100%,end position:50%,middle\n我不知道\n\n1374\n01:56:00.294 --> 01:56:02.921 align:middle line:100%,end position:50%,middle\n- 我爱你 爸\n- 我也爱你\n\n1375\n01:56:17.186 --> 01:56:19.855 align:middle line:100%,end position:50%,middle\n我知道 挺傻的\n\n1376\n01:56:20.439 --> 01:56:25.360 align:middle line:100%,end position:50%,middle\n他都<i>19</i>岁了 已经这么成熟了\n\n1377\n01:56:27.154 --> 01:56:28.989 align:middle line:100%,end position:50%,middle\n很可爱\n\n1378\n01:56:29.323 --> 01:56:31.200 align:middle line:100%,end position:50%,middle\n你很可爱\n\n1379\n01:58:05.460 --> 01:58:07.254 align:middle line:100%,end position:50%,middle\n宝贝\n\n1380\n01:58:07.421 --> 01:58:09.298 align:middle line:100%,end position:50%,middle\n时候到了\n\n1381\n01:59:02.267 --> 01:59:03.310 align:middle line:100%,end position:50%,middle\n- 莉兹\n- 什么？\n\n1382\n01:59:03.477 --> 01:59:06.855 align:middle line:100%,end position:50%,middle\n莉兹 过来 我有话告诉你\n\n1383\n01:59:13.028 --> 01:59:15.697 align:middle line:100%,end position:50%,middle\n不行 我真的真的该去冥想了\n\n1384\n01:59:17.032 --> 01:59:19.159 align:middle line:100%,end position:50%,middle\n去吧 去吧\n\n1385\n01:59:25.749 --> 01:59:28.168 align:middle line:100%,end position:50%,middle\n我都<i>2</i>周没去见凯图了\n\n1386\n01:59:28.335 --> 01:59:29.378 align:middle line:100%,end position:50%,middle\n- 真的？\n- 对\n\n1387\n01:59:29.545 --> 01:59:31.755 align:middle line:100%,end position:50%,middle\n- 好 去吧 去吧\n- 好\n\n1388\n01:59:35.133 --> 01:59:39.054 align:middle line:100%,end position:50%,middle\n可你比凯图可爱太多了\n\n1389\n01:59:41.890 --> 01:59:46.061 align:middle line:100%,end position:50%,middle\n不行 我得走了 得走了\n\n1390\n01:59:53.235 --> 01:59:55.028 align:middle line:100%,end position:50%,middle\n为什么？\n\n1391\n02:00:07.291 --> 02:00:09.710 align:middle line:100%,end position:50%,middle\n你有膀胱感染\n\n1392\n02:00:09.877 --> 02:00:14.423 align:middle line:100%,end position:50%,middle\n太久没做爱 突然做太多\n很常见的\n\n1393\n02:00:14.590 --> 02:00:18.177 align:middle line:100%,end position:50%,middle\n我们<i>2</i>周来连<i>1</i>分钟都没分开过\n\n1394\n02:00:23.515 --> 02:00:25.934 align:middle line:100%,end position:50%,middle\n你现在害怕了 对吧？\n\n1395\n02:00:26.101 --> 02:00:27.436 align:middle line:100%,end position:50%,middle\n我明白\n\n1396\n02:00:27.603 --> 02:00:29.730 align:middle line:100%,end position:50%,middle\n你不想迷失自己\n\n1397\n02:00:30.105 --> 02:00:33.275 align:middle line:100%,end position:50%,middle\n爱情很可怕 很危险\n\n1398\n02:00:33.442 --> 02:00:34.943 align:middle line:100%,end position:50%,middle\n我也经历过\n\n1399\n02:00:36.278 --> 02:00:39.948 align:middle line:100%,end position:50%,middle\n我天天祈祷 可丈夫对我不好\n\n1400\n02:00:40.449 --> 02:00:42.326 align:middle line:100%,end position:50%,middle\n我必须离开他\n\n1401\n02:00:43.619 --> 02:00:46.914 align:middle line:100%,end position:50%,middle\n这里就是他拿东西打的\n\n1402\n02:00:47.080 --> 02:00:48.624 align:middle line:100%,end position:50%,middle\n拿摩托车头盔打的\n\n1403\n02:00:49.625 --> 02:00:51.919 align:middle line:100%,end position:50%,middle\n后来 我女儿\n\n1404\n02:00:52.794 --> 02:00:54.922 align:middle line:100%,end position:50%,middle\n求我离开他\n\n1405\n02:00:55.088 --> 02:00:56.632 align:middle line:100%,end position:50%,middle\n是这样吗 宝贝？\n\n1406\n02:00:56.840 --> 02:00:59.635 align:middle line:100%,end position:50%,middle\n我说“妈妈 我觉得你该离婚”\n\n1407\n02:00:59.843 --> 02:01:03.430 align:middle line:100%,end position:50%,middle\n她说这话时 才<i>4</i>岁\n\n1408\n02:01:08.602 --> 02:01:11.563 align:middle line:100%,end position:50%,middle\n别为费利佩的事内疚\n\n1409\n02:01:11.730 --> 02:01:14.316 align:middle line:100%,end position:50%,middle\n宝贝 谁都需要爱\n\n1410\n02:01:14.483 --> 02:01:16.485 align:middle line:100%,end position:50%,middle\n爱会让人做出奇怪的事\n\n1411\n02:01:16.652 --> 02:01:19.988 align:middle line:100%,end position:50%,middle\n刚开始恋爱时 大家都这样\n\n1412\n02:01:20.155 --> 02:01:23.784 align:middle line:100%,end position:50%,middle\n想要太多幸福 太多欢愉\n\n1413\n02:01:23.951 --> 02:01:26.954 align:middle line:100%,end position:50%,middle\n直到把自己弄病\n\n1414\n02:01:27.371 --> 02:01:31.667 align:middle line:100%,end position:50%,middle\n就连我瓦杨 恋爱刚开始也这样\n\n1415\n02:01:31.875 --> 02:01:34.670 align:middle line:100%,end position:50%,middle\n我迷失了自己 莉兹\n\n1416\n02:01:36.380 --> 02:01:37.965 align:middle line:100%,end position:50%,middle\n<i>亲爱的朋友和家人</i>\n\n1417\n02:01:38.131 --> 02:01:39.842 align:middle line:100%,end position:50%,middle\n<i>我的生日就快到了</i>\n\n1418\n02:01:40.008 --> 02:01:42.511 align:middle line:100%,end position:50%,middle\n<i>如果在家 我现在一定在筹备</i>\n\n1419\n02:01:42.678 --> 02:01:46.640 align:middle line:100%,end position:50%,middle\n<i>一场傻乎乎又昂贵的生日派对\n你们则给我买礼物 买酒</i>\n\n1420\n02:01:46.807 --> 02:01:49.810 align:middle line:100%,end position:50%,middle\n<i>其实有个更省钱 也更美好的庆祝方式</i>\n\n1421\n02:01:49.977 --> 02:01:52.729 align:middle line:100%,end position:50%,middle\n<i>就是捐款帮一位治疗师\n瓦杨·努里雅西</i>\n\n1422\n02:01:52.896 --> 02:01:55.023 align:middle line:100%,end position:50%,middle\n<i>在印度尼西亚买栋房子</i>\n\n1423\n02:01:55.190 --> 02:01:58.360 align:middle line:100%,end position:50%,middle\n<i>她是位单身母亲 在巴厘岛离婚后</i>\n\n1424\n02:01:58.527 --> 02:02:01.280 align:middle line:100%,end position:50%,middle\n<i>女人什么都拿不到 连孩子都没有</i>\n\n1425\n02:02:01.446 --> 02:02:05.492 align:middle line:100%,end position:50%,middle\n<i>为争取女儿图蒂的抚养权\n瓦杨变卖了一切</i>\n\n1426\n02:02:05.659 --> 02:02:08.203 align:middle line:100%,end position:50%,middle\n<i>连浴室脚垫都卖了 只为请律师</i>\n\n1427\n02:02:09.204 --> 02:02:11.206 align:middle line:100%,end position:50%,middle\n<i>多年来 她们不断搬家</i>\n\n1428\n02:02:11.415 --> 02:02:15.043 align:middle line:100%,end position:50%,middle\n<i>每搬一次 瓦杨就会失去病人\n图蒂也得转学</i>\n\n1429\n02:02:15.961 --> 02:02:19.882 align:middle line:100%,end position:50%,middle\n<i>巴厘岛的这群人 已经成了我的家人</i>\n\n1430\n02:02:20.048 --> 02:02:23.552 align:middle line:100%,end position:50%,middle\n<i>无论在哪里遇到家人\n我们都该照顾他们</i>\n\n1431\n02:02:23.719 --> 02:02:27.055 align:middle line:100%,end position:50%,middle\n<i>今天看见图蒂在玩一块蓝色瓷砖</i>\n\n1432\n02:02:27.222 --> 02:02:29.892 align:middle line:100%,end position:50%,middle\n<i>是她在路边的酒店工地附近捡的\n她告诉我</i>\n\n1433\n02:02:30.058 --> 02:02:32.728 align:middle line:100%,end position:50%,middle\n也许有一天 我们有了自己的家\n\n1434\n02:02:32.936 --> 02:02:35.731 align:middle line:100%,end position:50%,middle\n地上也能铺这样漂亮的蓝色瓷砖\n\n1435\n02:02:36.565 --> 02:02:38.358 align:middle line:100%,end position:50%,middle\n<i>在意大利时 我学会了一个词</i>\n\n1436\n02:02:38.525 --> 02:02:39.776 align:middle line:100%,end position:50%,middle\n拼作<i>“tutti”</i> 中间<i>2</i>个T连着\n\n1437\n02:02:40.736 --> 02:02:45.199 align:middle line:100%,end position:50%,middle\n<i>意大利语的意思是“每个人”\n所以这就是我学到的道理吧</i>\n\n1438\n02:02:45.365 --> 02:02:47.910 align:middle line:100%,end position:50%,middle\n<i>当你走向世界 想让自己好过</i>\n\n1439\n02:02:48.076 --> 02:02:50.370 align:middle line:100%,end position:50%,middle\n<i>有时却是在帮助“图蒂”\n也帮助了“每个人”</i>\n\n1440\n02:02:53.707 --> 02:02:56.919 align:middle line:100%,end position:50%,middle\n- 再说一遍\n- <i>18000</i>美元\n\n1441\n02:02:57.085 --> 02:02:59.755 align:middle line:100%,end position:50%,middle\n邮件都带来给你看了\n\n1442\n02:03:02.216 --> 02:03:03.425 align:middle line:100%,end position:50%,middle\n天哪\n\n1443\n02:03:03.592 --> 02:03:04.885 align:middle line:100%,end position:50%,middle\n我们有房子了\n\n1444\n02:03:05.052 --> 02:03:08.263 align:middle line:100%,end position:50%,middle\n可以做所有人的家！\n\n1445\n02:03:10.265 --> 02:03:13.602 align:middle line:100%,end position:50%,middle\n我能开药房 还能开图书馆！\n\n1446\n02:03:14.770 --> 02:03:17.439 align:middle line:100%,end position:50%,middle\n- 好吧 天哪\n- 再闭上 闭上眼睛\n\n1447\n02:03:17.606 --> 02:03:19.942 align:middle line:100%,end position:50%,middle\n小心 可别磕坏牙了\n\n1448\n02:03:20.108 --> 02:03:22.945 align:middle line:100%,end position:50%,middle\n- 别担心 闭上眼\n- 要带我去哪儿？\n\n1449\n02:03:23.111 --> 02:03:24.112 align:middle line:100%,end position:50%,middle\n你马上就知道\n\n1450\n02:03:24.279 --> 02:03:26.782 align:middle line:100%,end position:50%,middle\n- 你帮瓦杨买了房子\n- 我知道\n\n1451\n02:03:26.949 --> 02:03:28.450 align:middle line:100%,end position:50%,middle\n所以我们得庆祝一下\n\n1452\n02:03:28.617 --> 02:03:30.244 align:middle line:100%,end position:50%,middle\n- 这边 这边\n- 好\n\n1453\n02:03:30.410 --> 02:03:32.913 align:middle line:100%,end position:50%,middle\n- 转个弯 转弯\n- 我知道在海滩了\n\n1454\n02:03:33.080 --> 02:03:34.957 align:middle line:100%,end position:50%,middle\n好了\n\n1455\n02:03:36.124 --> 02:03:38.085 align:middle line:100%,end position:50%,middle\n我们坐船去玩一趟\n\n1456\n02:03:39.294 --> 02:03:40.295 align:middle line:100%,end position:50%,middle\n去哪儿？\n\n1457\n02:03:40.504 --> 02:03:43.465 align:middle line:100%,end position:50%,middle\n去哪儿？附近一座小岛\n\n1458\n02:03:43.632 --> 02:03:47.135 align:middle line:100%,end position:50%,middle\n我最喜欢的地方\n<i>2</i>个人的行李都收拾好了\n\n1459\n02:03:47.302 --> 02:03:52.140 align:middle line:100%,end position:50%,middle\n可以待到下周二\n我还找好了绝佳的露营地\n\n1460\n02:03:52.641 --> 02:03:56.311 align:middle line:100%,end position:50%,middle\n只有你和我 还有<i>400</i>只鹦鹉\n\n1461\n02:03:59.147 --> 02:04:01.275 align:middle line:100%,end position:50%,middle\n喜欢吗？\n\n1462\n02:04:03.318 --> 02:04:07.990 align:middle line:100%,end position:50%,middle\n本想留到今晚再说\n不过我觉得现在正好\n\n1463\n02:04:08.156 --> 02:04:10.951 align:middle line:100%,end position:50%,middle\n我得待在巴厘岛 因为生意在这里\n\n1464\n02:04:11.118 --> 02:04:12.828 align:middle line:100%,end position:50%,middle\n你得待在纽约\n\n1465\n02:04:12.995 --> 02:04:15.664 align:middle line:100%,end position:50%,middle\n因为你的生活在那里 对吧？\n\n1466\n02:04:16.164 --> 02:04:20.127 align:middle line:100%,end position:50%,middle\n不如试着创造一种\n在<i>2</i>个地方轮流生活的日子？\n\n1467\n02:04:25.299 --> 02:04:27.050 align:middle line:100%,end position:50%,middle\n你为什么想这么做？\n\n1468\n02:04:27.551 --> 02:04:29.678 align:middle line:100%,end position:50%,middle\n因为我爱上你了\n\n1469\n02:04:35.309 --> 02:04:37.561 align:middle line:100%,end position:50%,middle\n- 走吧 走吧\n- 不 我...\n\n1470\n02:04:38.687 --> 02:04:40.814 align:middle line:100%,end position:50%,middle\n- 怎么了？\n- 我不行 对不起\n\n1471\n02:04:41.356 --> 02:04:42.524 align:middle line:100%,end position:50%,middle\n- 我只是...\n- 不行？\n\n1472\n02:04:42.691 --> 02:04:44.193 align:middle line:100%,end position:50%,middle\n- 对不起 我不行\n- 什么不行？\n\n1473\n02:04:44.359 --> 02:04:49.198 align:middle line:100%,end position:50%,middle\n我现在不能去旅行 好吗？我...\n\n1474\n02:04:49.364 --> 02:04:53.202 align:middle line:100%,end position:50%,middle\n我<i>5</i>天没回家了\n也好几周没见凯图了\n\n1475\n02:04:53.368 --> 02:04:55.871 align:middle line:100%,end position:50%,middle\n- 这太多了\n- 一点都不多\n\n1476\n02:04:58.540 --> 02:05:00.209 align:middle line:100%,end position:50%,middle\n出去玩\n\n1477\n02:05:00.375 --> 02:05:01.877 align:middle line:100%,end position:50%,middle\n只有我们俩\n\n1478\n02:05:02.044 --> 02:05:06.381 align:middle line:100%,end position:50%,middle\n抛开其他一切 去玩几天\n对你来说就这么过分吗？\n\n1479\n02:05:06.590 --> 02:05:09.635 align:middle line:100%,end position:50%,middle\n莉兹 <i>我不明白</i> 到底怎么了？\n\n1480\n02:05:09.801 --> 02:05:13.472 align:middle line:100%,end position:50%,middle\n我也有跟你一样的恐惧和伤痕\n\n1481\n02:05:13.639 --> 02:05:15.682 align:middle line:100%,end position:50%,middle\n而我都给你看了\n\n1482\n02:05:15.849 --> 02:05:19.478 align:middle line:100%,end position:50%,middle\n可我们之间唯一的区别大概就是\n\n1483\n02:05:19.853 --> 02:05:21.563 align:middle line:100%,end position:50%,middle\n你害怕再爱一次\n\n1484\n02:05:21.730 --> 02:05:23.106 align:middle line:100%,end position:50%,middle\n亲爱的 就是现在\n\n1485\n02:05:23.482 --> 02:05:26.401 align:middle line:100%,end position:50%,middle\n看着我的眼睛 告诉我实话\n\n1486\n02:05:27.027 --> 02:05:30.864 align:middle line:100%,end position:50%,middle\n求你了 你爱我 还是不爱？\n\n1487\n02:05:34.910 --> 02:05:36.495 align:middle line:100%,end position:50%,middle\n看着我的眼睛 告诉我\n\n1488\n02:05:36.662 --> 02:05:40.123 align:middle line:100%,end position:50%,middle\n你到底爱不爱我？很简单\n\n1489\n02:05:40.707 --> 02:05:43.252 align:middle line:100%,end position:50%,middle\n我知道你也有同样的感觉\n为什么就说不出口？\n\n1490\n02:05:43.418 --> 02:05:45.504 align:middle line:100%,end position:50%,middle\n我不知道为什么\n\n1491\n02:05:47.548 --> 02:05:48.757 align:middle line:100%,end position:50%,middle\n为什么说不出口？\n\n1492\n02:05:48.924 --> 02:05:52.261 align:middle line:100%,end position:50%,middle\n因为你怕极了 宝贝\n没关系 我也一样\n\n1493\n02:05:52.636 --> 02:05:55.597 align:middle line:100%,end position:50%,middle\n可我还是想和你一起上那条船\n\n1494\n02:05:55.764 --> 02:05:58.267 align:middle line:100%,end position:50%,middle\n- 不 好吧 听我说\n- 什么？\n\n1495\n02:05:58.433 --> 02:06:01.436 align:middle line:100%,end position:50%,middle\n我不明白你怎么就不懂\n\n1496\n02:06:01.645 --> 02:06:05.190 align:middle line:100%,end position:50%,middle\n我好不容易找到了一些东西\n不能就这样放弃\n\n1497\n02:06:05.357 --> 02:06:09.611 align:middle line:100%,end position:50%,middle\n相信我 真放弃了\n你也不会再这么爱我\n\n1498\n02:06:09.778 --> 02:06:13.282 align:middle line:100%,end position:50%,middle\n好 平衡 你环游世界寻找平衡\n\n1499\n02:06:13.448 --> 02:06:15.951 align:middle line:100%,end position:50%,middle\n那你以为自己找到了什么平衡？\n\n1500\n02:06:16.159 --> 02:06:20.080 align:middle line:100%,end position:50%,middle\n冥想<i>20</i>分钟\n再去见个老医师？\n\n1501\n02:06:20.247 --> 02:06:23.959 align:middle line:100%,end position:50%,middle\n听着 宝贝 所谓平衡\n就是别人给你的爱\n\n1502\n02:06:24.168 --> 02:06:27.129 align:middle line:100%,end position:50%,middle\n- 不能比你爱自己还少\n- 你知道吗？你知道吗？\n\n1503\n02:06:27.296 --> 02:06:31.216 align:middle line:100%,end position:50%,middle\n别替我评判这一年学会了什么\n没学会什么\n\n1504\n02:06:31.383 --> 02:06:33.802 align:middle line:100%,end position:50%,middle\n也别说你自己多平衡 多睿智\n\n1505\n02:06:33.969 --> 02:06:36.305 align:middle line:100%,end position:50%,middle\n我又多么不会表达自己\n\n1506\n02:06:36.471 --> 02:06:40.142 align:middle line:100%,end position:50%,middle\n别再叫我“宝贝” 我会发疯的\n\n1507\n02:06:40.309 --> 02:06:44.605 align:middle line:100%,end position:50%,middle\n听我说！我不需要靠爱你\n来证明我爱自己\n\n1508\n02:06:51.570 --> 02:06:53.488 align:middle line:100%,end position:50%,middle\n你以为在逃离我？\n\n1509\n02:06:54.156 --> 02:06:59.620 align:middle line:100%,end position:50%,middle\n你是在逃离自己人生中\n所有美好的可能\n\n1510\n02:07:03.457 --> 02:07:05.834 align:middle line:100%,end position:50%,middle\n我要上那条船了\n\n1511\n02:08:33.088 --> 02:08:34.256 align:middle line:100%,end position:50%,middle\n给你\n\n1512\n02:08:34.423 --> 02:08:36.758 align:middle line:100%,end position:50%,middle\n临别礼物\n\n1513\n02:08:45.100 --> 02:08:46.602 align:middle line:100%,end position:50%,middle\n凯图\n\n1514\n02:08:57.613 --> 02:08:59.448 align:middle line:100%,end position:50%,middle\n莉兹\n\n1515\n02:08:59.823 --> 02:09:02.075 align:middle line:100%,end position:50%,middle\n你治愈了我\n\n1516\n02:09:04.244 --> 02:09:06.747 align:middle line:100%,end position:50%,middle\n你也治愈了我 凯图\n\n1517\n02:09:09.374 --> 02:09:12.377 align:middle line:100%,end position:50%,middle\n要不是你 我不会再回巴厘岛\n\n1518\n02:09:12.544 --> 02:09:15.297 align:middle line:100%,end position:50%,middle\n也不会重新找回自己\n\n1519\n02:09:15.464 --> 02:09:17.758 align:middle line:100%,end position:50%,middle\n要咖啡吗？烤猪肉？\n\n1520\n02:09:19.218 --> 02:09:20.802 align:middle line:100%,end position:50%,middle\n咖啡\n\n1521\n02:09:20.969 --> 02:09:22.262 align:middle line:100%,end position:50%,middle\n我去给你拿\n\n1522\n02:09:22.429 --> 02:09:24.306 align:middle line:100%,end position:50%,middle\n你很快就要飞回美国了？\n\n1523\n02:09:24.473 --> 02:09:26.642 align:middle line:100%,end position:50%,middle\n<i>2</i>小时后\n\n1524\n02:09:26.808 --> 02:09:28.644 align:middle line:100%,end position:50%,middle\n凯图 你坐过飞机吗？\n\n1525\n02:09:29.353 --> 02:09:32.147 align:middle line:100%,end position:50%,middle\n凯图不能坐飞机\n\n1526\n02:09:33.482 --> 02:09:35.984 align:middle line:100%,end position:50%,middle\n凯图没牙\n\n1527\n02:09:39.655 --> 02:09:42.824 align:middle line:100%,end position:50%,middle\n你是我的好朋友\n\n1528\n02:09:42.991 --> 02:09:44.660 align:middle line:100%,end position:50%,middle\n就像我女儿\n\n1529\n02:09:45.786 --> 02:09:47.913 align:middle line:100%,end position:50%,middle\n等我死了\n\n1530\n02:09:48.080 --> 02:09:51.458 align:middle line:100%,end position:50%,middle\n你会回巴厘岛吗？来参加我的火葬？\n\n1531\n02:09:52.376 --> 02:09:54.878 align:middle line:100%,end position:50%,middle\n巴厘岛的火葬仪式可好玩了\n\n1532\n02:09:55.671 --> 02:09:57.673 align:middle line:100%,end position:50%,middle\n- 你会喜欢的\n- 好\n\n1533\n02:09:59.132 --> 02:10:04.137 align:middle line:100%,end position:50%,middle\n还像我说的那样\n让肝脏微笑吗？\n\n1534\n02:10:04.304 --> 02:10:05.347 align:middle line:100%,end position:50%,middle\n是的\n\n1535\n02:10:05.514 --> 02:10:09.518 align:middle line:100%,end position:50%,middle\n还在按印度导师教的方式冥想吗？\n\n1536\n02:10:09.893 --> 02:10:11.895 align:middle line:100%,end position:50%,middle\n- 是的\n- 现在跟神相处得开心吗？\n\n1537\n02:10:12.980 --> 02:10:16.817 align:middle line:100%,end position:50%,middle\n- 是的\n- 你爱你的新男朋友吗？\n\n1538\n02:10:22.698 --> 02:10:24.616 align:middle line:100%,end position:50%,middle\n我结束了这段关系\n\n1539\n02:10:26.410 --> 02:10:28.662 align:middle line:100%,end position:50%,middle\n不明白 为什么要这样？\n\n1540\n02:10:32.541 --> 02:10:35.544 align:middle line:100%,end position:50%,middle\n我没法保持平衡\n\n1541\n02:10:37.045 --> 02:10:41.133 align:middle line:100%,end position:50%,middle\n莉兹 听凯图说\n\n1542\n02:10:41.300 --> 02:10:45.470 align:middle line:100%,end position:50%,middle\n有时为了爱情失去平衡\n\n1543\n02:10:45.637 --> 02:10:49.933 align:middle line:100%,end position:50%,middle\n也是平衡人生的一部分\n\n1544\n02:11:04.072 --> 02:11:05.908 align:middle line:100%,end position:50%,middle\n<i>到最后</i>\n\n1545\n02:11:06.074 --> 02:11:10.871 align:middle line:100%,end position:50%,middle\n<i>我开始相信一种东西\n我叫它“追寻物理学”</i>\n\n1546\n02:11:12.915 --> 02:11:17.753 align:middle line:100%,end position:50%,middle\n<i>自然界的一种力量\n受如引力般真实的法则支配</i>\n\n1547\n02:11:18.253 --> 02:11:21.757 align:middle line:100%,end position:50%,middle\n<i>追寻物理学的法则 大概是这样</i>\n\n1548\n02:11:21.965 --> 02:11:26.053 align:middle line:100%,end position:50%,middle\n<i>如果你有勇气\n抛开一切熟悉又舒适的东西</i>\n\n1549\n02:11:26.220 --> 02:11:29.723 align:middle line:100%,end position:50%,middle\n<i>无论是你的房子\n还是那些苦涩陈旧的怨恨</i>\n\n1550\n02:11:29.890 --> 02:11:32.434 align:middle line:100%,end position:50%,middle\n<i>踏上寻找真相的旅程</i>\n\n1551\n02:11:32.601 --> 02:11:35.562 align:middle line:100%,end position:50%,middle\n<i>无论向外探索 还是向内探寻</i>\n\n1552\n02:11:35.729 --> 02:11:38.273 align:middle line:100%,end position:50%,middle\n<i>如果你真心愿意</i>\n\n1553\n02:11:38.440 --> 02:11:41.443 align:middle line:100%,end position:50%,middle\n<i>把途中发生的一切都视作线索</i>\n\n1554\n02:11:41.610 --> 02:11:46.114 align:middle line:100%,end position:50%,middle\n<i>把沿途遇到的每个人都视作老师</i>\n\n1555\n02:11:50.619 --> 02:11:53.121 align:middle line:100%,end position:50%,middle\n<i>最重要的是 你已准备好</i>\n\n1556\n02:11:53.288 --> 02:11:57.626 align:middle line:100%,end position:50%,middle\n<i>面对并原谅自己身上\n那些难以接受的真实</i>\n\n1557\n02:11:57.793 --> 02:12:00.128 align:middle line:100%,end position:50%,middle\n<i>那么真相就不会对你隐瞒</i>\n\n1558\n02:12:00.796 --> 02:12:02.548 align:middle line:100%,end position:50%,middle\n费利佩？\n\n1559\n02:12:15.352 --> 02:12:18.272 align:middle line:100%,end position:50%,middle\n<i>凭我的亲身经历 我不能不相信</i>\n\n1560\n02:12:50.512 --> 02:12:53.056 align:middle line:100%,end position:50%,middle\n我想好自己的关键词了\n\n1561\n02:13:01.190 --> 02:13:03.192 align:middle line:100%,end position:50%,middle\n它的意思是\n\n1562\n02:13:05.027 --> 02:13:07.362 align:middle line:100%,end position:50%,middle\n“我们过去吧”\n";
